INSERT INTO terminos (id, termino, definicion, campo_softland, estado_origen, nota_origen, revisado, nota_decision, es_nuevo, editado, eliminado_en, actualizado_en) VALUES
  ('4979eb1c-3073-408c-8303-21e288e292aa'::uuid, ' Algoritmos de extracción (E-Flow)', ' Lógica del WMS que determina qué ubicaciones y qué productos se deben extraer para cumplir pedidos', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ae0a4ed4-a3dd-4b6d-957e-9cdc19d695f1'::uuid, ' Alisto (Picking)', ' Proceso de preparar los pedidos de los clientes, seleccionando y organizando productos según la orden', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('eb2aacb7-f805-47fc-bdb0-fb3d8fe72c6b'::uuid, ' Alisto batch (por lotes)', ' Método de preparación en el que se agrupan varias órdenes para optimizar recorridos y tiempos', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('89af55eb-9c33-4cbb-a251-b2548b8a693e'::uuid, ' Asignación de viaje', ' Vinculación de la carga con chofer, vehículo, ruta y hora de salida para garantizar trazabilidad', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f69f1e62-c818-4c57-ba7a-cafc356bed17'::uuid, ' Capacidad', ' Es la medida del volumen máximo de recursos que una instalación, vehículo o proceso puede manejar en un periodo determinado', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('99c5eedb-aad8-422f-9d85-208ef594ed9d'::uuid, ' Certificación de alisto', ' Punto de control que valida que un pedido esté completo y correcto antes del despacho', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9fd66c8f-8752-42ea-a733-17f96207133b'::uuid, ' Chequeo', ' Verificación física y documental de mercancías para asegurar cantidad, estado y exactitud', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3e946d3d-b212-47ff-ad7d-e3903d3f5110'::uuid, ' Consolidación', ' Agrupación de productos por cliente o pedido antes del despacho, evitando mezclas entre clientes', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('dd628283-d383-46ed-adf2-99fc052ffc24'::uuid, ' Control de Inventarios', ' Supervisión y conteo de existencias en el CEDI para garantizar exactitud y disponibilidad', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('69e6a98c-97b2-4d72-8700-669697c81dd7'::uuid, ' Desconsolidación', ' Separación de cargas consolidadas para su distribución individual', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6dd8d1ea-c987-4da3-86d4-533d5e718643'::uuid, ' Despacho', ' Preparación y salida de pedidos desde el CEDI hacia el cliente', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:48:20.411Z'::timestamptz),
  ('33703e15-f853-4b8c-a737-b2247db621ba'::uuid, ' Eficiencia', ' Capacidad de alcanzar un resultado con el mínimo uso de recursos, manteniendo la calidad', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('bd18cd20-f053-4ac5-bd1c-3eeb28fec53e'::uuid, ' Etiquetado de pallets', ' Asignación de códigos y rótulos únicos a cada pallet para garantizar trazabilidad', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7f77a437-5fd2-4454-97f2-74965041220a'::uuid, ' Fulfillment', ' Es el proceso logístico integral que abarca la preparación y entrega de pedidos de clientes, desde la recepción de la orden y el almacenamiento de productos hasta su empaquetado, envío y distribución final', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('403dfab9-0c64-4e98-a2a8-5c8c19d275f5'::uuid, ' Gestión de inconsistencias', ' Registro y resolución de diferencias detectadas entre lo recibido, lo registrado y lo esperado en el sistema', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e19a0033-a0db-4eb9-8981-7989df88dc92'::uuid, ' GTP (gestión total de productividad)', ' Es un modelo integral de indicadores de desempeño que mide de forma sistemática la productividad', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4fc7c8a4-e653-4a44-bc96-b345fe6b5de4'::uuid, ' Handheld', ' Dispositivo portátil conectado al WMS que permite escanear productos y registrar operaciones sin errores manuales', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:48:35.826Z'::timestamptz),
  ('12f5ca55-df15-406d-b846-79284591a0f7'::uuid, ' Inbound', ' Logística de entrada, relacionada con el transporte y almacenamiento', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('10603b47-ba82-4cdf-92b9-7f5bc92fa9fd'::uuid, ' Logística Inversa (devoluciones)', ' Procesos para recibir productos devueltos, defectuosos o sobrantes y darles el tratamiento adecuado', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a211a5ee-112b-41c8-be70-7e26535b1cd6'::uuid, ' Mínimos y máximos', ' Niveles de control de inventario que activan reposición (mínimo) o previenen sobrestock (máximo)', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('059a95df-72a9-47f0-93e2-373bf725ff13'::uuid, ' Outbound', ' Todas las actividades relacionadas con la distribución y entrega de productos terminados a los clientes finales, incluyendo la preparación de pedidos, el embalaje, el transporte, la gestión de envíos', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('250d9de4-4429-4bde-ad83-7e9fc0037b59'::uuid, ' Pallet máster', ' Pallet consolidado que agrupa varios pedidos o cargas de un cliente para transporte', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('46238357-6cbc-4703-8246-1e9043e86635'::uuid, ' Pick-to-Belt', ' Acción donde el asistente de logística recoge y coloca en una banda/contenedor intermedio', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('571c5523-7328-4269-8d86-4668415e9131'::uuid, ' Pick-to-Order', ' Acción donde el asistente de logística recoge y arma directamente un pedido', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0f773c04-e1ab-49e7-ab6e-cf3853ddfa91'::uuid, ' Pick-to-Put', ' Acción donde el asistente de logística recoge en lote y clasifica en compartimentos para consolidar varios pedidos', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('51af7f43-1f3c-4c6c-adfe-62e8b7afa033'::uuid, ' Productividad', ' Se refiere a la cantidad de pedidos entregados por hora, los vehículos que circulan por día, o los productos procesados por empleado', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('dfc67e4c-c2bc-4862-aa58-d7937c50b123'::uuid, ' Putaway', ' Proceso logístico de mover mercancías, una vez recibidas en un almacén, desde el área de recepción a sus ubicaciones de almacenamiento designadas', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a3b3c87e-a9b3-43b4-a3d2-21c466b5b530'::uuid, ' Reposición', ' Traslado automático de inventario desde reserva hacia zonas de picking cuando el stock llega al mínimo', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('379a7b64-aacd-4991-9b26-bdecadb6cb08'::uuid, ' SEL (servicios estratégicos locales)', ' categoría del Régimen de Zonas Francas en Costa Rica que permite a empresas, como operadores 3PL, brindar servicios logísticos y de apoyo con beneficios fiscales y aduaneros', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b261db36-61be-47bd-bc5b-e3ca037f4af0'::uuid, ' SIO (Sistema de información de OLO)', ' Es una plataforma interna que centraliza y gestiona la información de la empresa para facilitar el control de procesos y la toma de decisiones', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d9d3b2fc-44ec-44ea-b1ff-72b9a00e0666'::uuid, ' SLA (Service level agreement)', ' Acuerdo de nivel de servicio donde se establecen metas específicas para el cumpliento de los acuerdos de servicio con los clientes', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('11d77557-7489-4621-ae5d-ec2eb5ace5b1'::uuid, ' TI-HI', ' Estándar logístico que define cuántas cajas por piso (TI) y cuántos pisos por pallet (HI), optimizando espacio y estabilidad', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4226625f-a0ca-462f-a0f8-a52f66b576c2'::uuid, ' Tipos de recepción', ' Modalidades de ingreso de mercancía, como compra/importación, libre, cross docking o devoluciones', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4d497265-29ad-4b68-9098-bf95b247b3f9'::uuid, ' TMC (transport management system)', ' Software de gestión de transportes que planifica, ejecuta y optimiza los movimientos de mercancías, permitiendo controlar rutas, costos, flota y entregas para mejorar la eficiencia y el servicio al cliente', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0b52d8a5-5a05-48cf-864b-67f4b79b20ff'::uuid, ' Torre de Control', ' Sistema centralizado de monitoreo en tiempo real que coordina y optimiza todas las operaciones del CEDI, como una torre aérea', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('20b1f6b0-da8c-4dbc-96ae-ba1952df2e58'::uuid, ' Transporte', ' Movilización de mercancías desde/hacia el CEDI hasta el cliente o punto de distribución', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('57bb491a-3485-4619-81fe-588070d2474d'::uuid, ' Valor Agregado', ' Servicios extra como etiquetado, reempaque, kits o control de calidad que complementan la operación básica', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3395e5f6-ef7c-46ae-b921-4e5561e90c1c'::uuid, ' WMS (warehouse management system)', ' Sistema de Gestión de Almacenes, es un software que optimiza todas las operaciones dentro de un almacén o centro de distribución, desde la recepción de productos hasta su envío', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c41a9032-721e-456f-86c0-2ef40f404df4'::uuid, ' Zona de cuarentena', ' Espacio destinado a productos en revisión o pendientes de aprobación', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('90db3b92-aff4-4484-87be-2f9b2df5eb35'::uuid, ' Zona de picking', ' Área de preparación de pedidos con productos listos para alisto', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('55b87d9c-7ad7-4644-992d-a60c84d49bb0'::uuid, ' Zona de reserva', ' Área de almacenamiento profundo, normalmente por pallet completo', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('88d06b11-4229-4fac-b068-a3c1886d6097'::uuid, ' Zona Franca', ' Régimen especial donde OLO opera parte de su logística, con control aduanero y beneficios fiscales', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4971f6f4-dfb3-43e6-8480-957adf39b36d'::uuid, 'Abono extraordinario', 'Se refiere a los abonos extras que hagan los clientes a sus deudas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('327bf95c-9219-4ab4-a4ef-42639cf87597'::uuid, 'Acceso', 'Derecho o permiso que tiene un usuario para entrar a un sistema o consultar datos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b97abec6-a176-413f-a520-a5b9d3aaa76b'::uuid, 'Accidente', 'Hecho no premeditado del cual resulta un daño considerable. Es una ocurrencia en una serie de hechos que, en general y sin intención, produce lesión corporal, muerte o daño material.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f0a0efcd-68b1-49fa-bcad-7c737f2dd2d1'::uuid, 'Accidente laboral', 'Evento no planeado que resulta en daño o enfermedad para los colaboradores durante el desempeño de sus tareas laborales.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2b4dc552-f196-463e-b340-24b8fddb74cd'::uuid, 'Acciones de preparación de pedidos', 'Tareas que eflow WMS crea automáticamente después de generar órdenes de expedición, basándose en las ubicaciones con mercadería disponible para su extracción.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('137fea0e-0bcb-48fd-9686-cd51884d30af'::uuid, 'Acción correctiva', 'Medida tomada para eliminar la causa de una no conformidad detectada.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('55f7d2ad-b94f-4da6-9daf-917100539ed6'::uuid, 'Acción de personal', 'Documentos que registran y establecen los movimientos del empleado, ya sea por abandono temporal del puesto o bien, por cambio de puesto o terminación de labores.', 'Número Acción', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:48:46.418Z'::timestamptz),
  ('84ade85b-710b-4699-8fe4-7edd6581425b'::uuid, 'Acción de trabajo', 'Tarea generada por el sistema para preparar artículos según la orden de expedición.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('71337e1f-db49-4c60-9f08-10d4dcf220a2'::uuid, 'Acción preventiva', 'Medida implementada para evitar que ocurra una no conformidad potencial.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e7c5727d-900e-470b-b2bf-8911299aa58f'::uuid, 'Acta de finiquito', 'Documento que deja constancia de la terminación de la relación laboral y el acuerdo mutuo sobre los pagos pendientes (liquidación final). Sinónimo de "Acuerdo de Cese" o "Finiquito".', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4a62a163-f307-46c2-8b9f-dd456bb3c7a1'::uuid, 'Actividad', ' Corresponde a un subnivel del proceso que será utilizado o no, según se requiera para el entendimiento del mismo. (múltiples tareas, múltiples agentes, paralelas o secuenciales). ', 'Actividad Económica SGRL', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:48:47.756Z'::timestamptz),
  ('560ba3fb-0a79-4ae8-b895-0b93684a02dd'::uuid, 'Activos', 'Recursos económicos controlados por la empresa como resultado de eventos pasados, de los cuales se espera obtener beneficios económicos futuros. Se clasifican en Activos Corrientes y Activos No Corrientes.', 'Activo', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:38:37.245Z'::timestamptz),
  ('7ab3d352-4745-4dc0-b321-f40d02a1d394'::uuid, 'Adelanto', 'Proceso mediante el cual se realiza un avance de efectivo a la caja chica. El detalle de su ejecución se presenta en la sección "Adelanto Caja Chica" en la página 75.', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:48:49.085Z'::timestamptz),
  ('4155f205-171c-42b4-9932-a93231a5aa90'::uuid, 'Aftermarket', 'Mercado de autopartes no originales, pero compatibles con los vehículos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6da8ca0b-007c-4287-8442-5f5e3becb0ae'::uuid, 'AFV', 'Aplicación móvil de la fuerza de ventas', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('eee64272-fb29-4353-a8cd-919f802951ca'::uuid, 'Agente', 'Vendedores o cobradores que realizan preventa y / o cobros.', 'AGENTE', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:48:50.292Z'::timestamptz),
  ('c3f3471e-c75d-4565-9727-6ee9da50914b'::uuid, 'Agrupación', 'Conjunto de clientes agrupados que poseen el mismo nombre y diferentes razones sociales.', 'Agrupación', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('9dbb7635-04f1-4372-8ed2-81d17ae8a4cc'::uuid, 'Ajuste contable', 'Modificación de un asiento contable, realizada para corregir errores, registrar transacciones omitidas o reconocer ingresos y gastos en el período correcto (devengo).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8b5298f2-f783-446b-82e5-f421d21a032b'::uuid, 'Ajuste de inventario', 'Modificación de cantidades de inventario existentes, ya sea por entrada o salida, desde una ubicación específica.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('41ecc608-60ba-4bf2-a2ff-fd5f4fafb8cc'::uuid, 'Ajuste de saldos', 'Transacción administrativa que modifica saldos de clientes, generalmente por montos inmateriales o diferencias cambiarias, que no justifica la emisión de un documento fiscal.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('afb9bd4a-79e4-4c99-bb1c-935d5686f8e1'::uuid, 'Ajustes de precios', 'Se refiere a la ejecución, análisis y validación de las modificaciones en los precios de artículos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('348e8b8f-aa77-4e3c-b176-383088f58812'::uuid, 'Alcance', ' Establecer el cubrimiento y propósito del documento. Debe indicar tanto las áreas como las situaciones donde el documento debe ser usado, además de indicar sus excepciones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4c2736f3-5f41-4ab7-8ed5-0e51af7ebcf6'::uuid, 'Alfanumérico', 'Carácter que puede corresponder a cualquier dígito o letra.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2773e9f0-b2f4-46ef-8f0d-a38b17576969'::uuid, 'Algoritmo', 'Conjunto de pasos o instrucciones que una computadora sigue para resolver un problema, como una receta de cocina.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f5f7de91-0abc-49ae-957d-44769bb90c86'::uuid, 'Algoritmo genético', 'Técnica inspirada en la evolución natural que sirve para encontrar soluciones a problemas complejos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('bd94cf74-4ba3-41d9-bcbf-cc51580fd3f6'::uuid, 'Alias', 'Se refiere al nombre o identificador alternativo que se le asigna a un cliente.', 'Alias', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('527ac1f6-2acc-48e5-954c-bc4dccd32cb1'::uuid, 'Almacenaje', 'Los procesos relacionados con el almacenamiento de artículos y su funcionalidad en el módulo eflow WMS, incluyendo movimientos en el dispositivo de radio frecuencia.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2c803123-f70f-4ca0-99b4-7e2e2be342d2'::uuid, 'Almacenamientos', 'Son estructuras físicas donde se guarda la mercadería. Se configuran con información general, composición (columnas, niveles, posiciones), situación y coordenadas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5543bcb4-54ba-4306-8f68-99c585fd811e'::uuid, 'Almacén', ' También conocido como Centro de Distribución (CEDI), es una instalación o espacio que sirve para ubicar materiales y productos con la función de coordinar los desequilibrios entre la oferta y demanda ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('bf7cc120-47d7-459e-bc81-c59f8c56a567'::uuid, 'Alta en el seguro social', 'Proceso de inscripción de un nuevo empleado en el sistema de seguridad social (caja de seguro de salud, pensiones, etc.) del país correspondiente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f72c4bef-78d9-4c9a-959a-9d39384bf8cc'::uuid, 'AMEF', ' Análisis de Modo y Efecto de Falla. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7836196b-26d6-49f1-8415-f4e6152aff40'::uuid, 'Amortización fija', 'Tipo de condición de pago en el que para todas las cuotas, el monto que se amortiza al principal es siempre el mismo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('84eda7b2-8ba6-441a-a404-ce6bc8f06b00'::uuid, 'AMP', 'Unidad de intensidad de corriente eléctrica', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1a86f0a1-8368-4954-8b9c-1394edd8dc22'::uuid, 'Analítica', 'Uso de datos para identificar patrones y ayudar a tomar mejores decisiones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('91a349d6-1753-473f-83a5-476a238c3e6a'::uuid, 'Andón', 'Herramienta de gestión visual, cuyo origen proviene del término japonés "lámpara". Comúnmente, los andones son luces que se colocan en máquinas o líneas de producción para indicar el estado de las operaciones y notificar a la gerencia, el personal de mantenimiento y otros trabajadores. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('38a9a6ac-b761-4c81-ab82-51ba5e6a76d9'::uuid, 'Anexo', ' Documento que presenta información referencial como complemento de un macroproceso, proceso, actividad o tarea específica. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9aab3557-cb41-4944-b553-52beae877422'::uuid, 'Anexo de deposito', 'Comprobante que entrega el asesor de ventas por medio del AFV al depositar en cuentas bancarias de la compañía el efectivo recaudado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('54054d6a-a5c8-4b93-9438-5797875bc6c4'::uuid, 'Antenas de radio frecuencia', ' Equipos encargados de emitir señal de Recepción a las pocket RF para el uso del sistema eflow WMS. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('acafd1f1-2e19-4d9b-952a-52dc430e7d3e'::uuid, 'Anticipos a proveedores', 'Pagos realizados a un proveedor antes de la recepción de los bienes o la factura correspondiente. Se registra como un activo (un derecho a recibir un bien/servicio) hasta que se aplica a la factura final.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('10b71976-93a5-40b0-be8a-c841c006c3bc'::uuid, 'Antigüedad empresa', 'Tiempo total que un colaborador ha laborado para la empresa de forma ininterrumpida o acumulada, incluso si ha habido reingresos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9b5576bd-8e4c-4ae7-8f1b-84913db15d84'::uuid, 'Antigüedad organización', 'Tiempo que un colaborador ha permanecido en su puesto actual o dentro de la misma área o estructura organizacional, sin cambios significativos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a4a9bde8-e65e-4fbf-9d65-e28147834458'::uuid, 'Antivirus', 'Programa que detecta y elimina virus o programas maliciosos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2a8fabee-9893-4414-8201-a19a4532aa39'::uuid, 'ANUL (anuladas)', 'Tareas que, por motivos operativos, no deben ejecutarse.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5f862776-ad73-43c2-9421-fca1b36b2a58'::uuid, 'Análisis de Escenarios', 'Metodología de simulación que permite evaluar el impacto de diferentes variables (optimistas o pesimistas) en los niveles de inventario y flujo de caja, facilitando la creación de planes de contingencia.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b29d596a-40c6-496d-b2a5-fe322cd0abef'::uuid, 'APE', 'Error porcentual absoluto entre la demanda real y el pronóstico.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('912f0772-34a9-45a0-ae87-59b5d610cc15'::uuid, 'Apilador / montacarguista', 'Operador de equipos de manejo de materiales (montacargas, apiladores) que requiere certificación interna.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5353a285-0b21-4559-a7e8-e9ecc5d3ca6d'::uuid, 'Aplicaciones', 'Es el concepto comercial en Mayoreo Autopartes que reúne los tipos de transportes.', 'APLICACIONES', 'homonimo'::estado_origen_termino, 'Se separó de un término homónimo compartido con: Movilidad (Personal).', true, NULL, false, true, NULL, '2026-09-30T19:30:00.000Z'::timestamptz),
  ('fd94e0a3-32d5-46df-9298-53696467dd83'::uuid, 'Aplicación', 'El uso principal o la función prevista de un artículo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2a343c49-9dad-45eb-8d03-8774e1ce7aaf'::uuid, 'Aplicación al mayor', 'Proceso del ERP que traslada los registros de transacciones (asientos) desde el libro diario al libro mayor, actualizando los saldos de cada cuenta contable.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('25248767-700c-4654-a976-db862eb0ce44'::uuid, 'Aplicación de documento', 'Proceso de vincular un pago o nota de crédito a su factura o documento de origen correspondiente, saldando o reduciendo la deuda pendiente. Es un paso clave en la gestión de cuentas por cobrar y pagar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('26e00352-72ab-4d3b-91a2-f47d84317719'::uuid, 'Aplicar', 'Sinónimo de mayorizar.', 'Aplicar', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:49:20.620Z'::timestamptz),
  ('3ec20b94-cf26-40e8-b433-1906e6ca413e'::uuid, 'Aporte', 'Es un rubro utilizado dentro de los conceptos como una variable, que no afecta directamente al salario, pero lo toma como referencia.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('87800534-77b4-414f-b091-aa5607cd0d27'::uuid, 'Aprendiz', 'Persona que recibe formación teórica y práctica en un oficio o actividad, bajo la modalidad de contrato de aprendizaje. Regulado por leyes específicas de formación profesional en cada país (Ley de Juventud en Colombia, Ley Orgánica del Trabajo en Venezuela, etc.).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0ee617ed-1696-43fd-895c-605a8a26e129'::uuid, 'Aprendizaje no supervisado', 'El sistema aprende encontrando patrones por sí mismo, sin ejemplos previos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f38f1048-cffd-4a64-8548-e39493039fbe'::uuid, 'Aprendizaje por refuerzo', 'El sistema aprende probando acciones y recibiendo “premios” o “castigos” (ej. un robot que aprende a caminar).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7bfb10f8-b734-4a58-811e-a40701388542'::uuid, 'Aprendizaje supervisado', 'El sistema aprende usando ejemplos ya clasificados (ej. fotos marcadas como “gato” o “perro”).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('edb5b7ad-3403-41a4-9652-ee13584e82e8'::uuid, 'Aprobación', 'Validación formal de un documento o proceso por parte de los responsables.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5735cb7c-5b72-4b58-8ed8-137a62e8c356'::uuid, 'ARA', 'Accesorios y repuestos automotrices', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f4bddfde-e390-4564-b6ce-4e5f02076e0f'::uuid, 'Arancel', 'Impuesto que se debe pagar sobre un artículo extranjero, debido al ingreso del mismo al país.', 'Arancel', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('4354b86f-2813-4ba5-b49f-82af8445d0c4'::uuid, 'Archivado', 'Almacenamiento de documentos para fines históricos, legales o de consulta.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b83b9a9b-1527-4cdb-b58b-db2508b1806a'::uuid, 'Archivo BMP', 'Archivo cuyo contenido puede verse como una matriz M de dimensiones mxn, donde la entrada M[i,j] tiene como valores {0,1} y representan una imagen gráfica. ​', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('cd487562-3733-4006-9e1c-f08b487a11dc'::uuid, 'Archivo PBIX', 'Archivo nativo de Power BI que guarda tanto los datos como las visualizaciones creadas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('804708fe-b877-4ab1-b7e3-b3158d6b3e23'::uuid, 'Arqueo', 'Proceso mediante el cual se ejecuta un recuento de los movimientos efectuados en la caja chica. El detalle de su ejecución se presenta en la sección "Arqueo de Caja Chica" en la página 63.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('56be082e-6f8c-4781-bd9c-9a5ffde9398b'::uuid, 'Arquitectura de procesos', ' Proporciona un lenguaje común (BPMN) para que los involucrados se puedan comunicar de forma clara y a su vez puedan divulgar los procesos. Dentro de la Arquitectura de Procesos tenemos los niveles de comprensión. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('882266a0-81c4-4129-8c43-3022046461a0'::uuid, 'Arquitectura de software', 'La manera en que se diseña y organiza una aplicación para que funcione de forma correcta y ordenada.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('54dd51b5-de9c-47a7-ac8f-db288aa0d235'::uuid, 'Articulo', 'Reporte SIM – Dimensión Compras: Dimensión que muestra el código y descripción de los articulos de la compañía. Reporte SIM – Filtro Compra: Permite seleccionar el código y descripción de uno o varios artículos en específico.', 'Artículo', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-10-02T01:38:51.612Z'::timestamptz),
  ('9cb95e2f-92a6-412d-8cfb-9ef066b35505'::uuid, 'Artículo', 'Elemento esencial del inventario. Los artículos son las unidades mínimas almacenadas en bodega y sobre los cuales se realizan las transacciones de compra.', 'Artículo', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:38:55.262Z'::timestamptz),
  ('c93e35b5-1596-4903-9f97-9c7408942fa6'::uuid, 'Artículo Complementario (J)', 'Repuestos que no forman parte del surtido regular y se usan para reparaciones en talleres de servicio.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('14626fcc-a1a3-4473-ae01-70bb1034a059'::uuid, 'Artículo Dummy', 'Código y descripción genéricos de producto creados temporalmente en el ERP para presupuestar, planificar o registrar operaciones comerciales cuando el artículo o SKU definitivo aún no ha sido identificado o dado de alta.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3b664f51-9504-4c3d-8648-e395adc4a6bc'::uuid, 'Artículo en buen estado', 'Es un artículo que, hecha la revisión correspondiente, cuenta con las condiciones apropiadas para su comercialización.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a610d962-5a08-4d9c-ae48-b89670ffff8c'::uuid, 'Artículo en el que no aplica la garantía', 'Es un artículo que por su condición o por política de proveedor no se reconocerá como garantía. El artículo no cuenta con las condiciones apropiadas para su comercialización.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6efeaa8c-1c50-4f58-97ae-179de8cd4d1a'::uuid, 'Artículo en garantía', 'El producto presenta defecto de fábrica, se encuentra dentro del periodo de garantía de la marca y no requiere revisión por el taller de servicios.', 'Artículo garantía', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:49:29.830Z'::timestamptz),
  ('2b7d3243-d267-4cac-beb1-09152cbe4dee'::uuid, 'Artículo en garantía de taller', 'El producto se encuentra dentro del periodo de garantía de la marca y sí requiere revisión por el taller de servicios.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a09a1469-5bab-42b5-a0cc-06067c6ba4fc'::uuid, 'Artículo en garantía por medio de descuento', 'Es un artículo cuya garantía es reconocida por medio de un descuento por parte del proveedor o una reserva del área comercial.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('653a0477-80fd-4bca-b3ce-51a5f971e212'::uuid, 'Artículo en garantía por medio de nota crédito', 'Es un artículo que el proveedor sí reconoce como garantía, no necesita una revisión previa y su forma de reconocer la misma es por medio de la aplicación de una nota de crédito. El artículo no cuenta con las condiciones apropiadas para su comercialización.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('38bdd1c5-9bd5-4205-adbc-704f5d4ab0cf'::uuid, 'Artículo para evaluación proveedor', 'Es un artículo que pertenece a una marca o proveedor que por su política, realiza una revisión del mismo antes de decidir si lo reconoce como garantía. El artículo no cuenta con las condiciones apropiadas para su comercialización.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d1e3820e-5f2f-41ae-88c5-47d0dc70c04a'::uuid, 'Artículos', 'Indicador que contabiliza la cartera de artículos para un periodo determinado.', 'Artículo', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:38:57.092Z'::timestamptz),
  ('fba042dc-2d2b-491a-b46c-d41e951877e1'::uuid, 'Artículos alternos', 'Artículos que pueden sustituir a otros, presentando características similares.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3159cadb-3c1f-4240-ba03-f33ac4230f1d'::uuid, 'Artículos Básicos (F)', 'Los siguientes 800 artículos contados después de los doble básicos que generan la mayor cantidad de ventas para la empresa, evaluados en cantidades y precio durante un año.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c59aa0f2-9f8d-4051-9fdc-0a6b50f6410c'::uuid, 'Artículos Complementarios (H-K-M)', 'Artículos que complementan el surtido de la empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('28113b90-b7a1-429c-be22-5518ab989f0f'::uuid, 'Artículos de importación', 'Artículos a los que se les debe asignar un código arancelario único antes de emitir la orden de compra.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b1bed8c4-6aee-4d53-b558-63cc28972c4c'::uuid, 'Artículos Descontinuados (E)', 'Artículos bloqueados o por eliminar del surtido de la empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c6f44a66-9dc9-4ccb-ac1d-db808c93c4a9'::uuid, 'Artículos Doble Básicos (D)', 'Los siguientes 200 artículos contados después de los triple básicos que generan la mayor cantidad de ventas para la empresa, evaluados en cantidades y precio durante un año.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('99c392dc-9ebe-4146-8ce4-8ed54c796cf6'::uuid, 'Artículos Mercadeo y Suministros (S)', 'Suministros de Oficina y Material POP.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('45160c14-dc31-4bb1-99dd-6e2c91add35f'::uuid, 'Artículos Nuevos (N)', 'Artículos que se incluyen por primera vez en el surtido de la empresa y una vez transcurridos seis meses desde la primera venta pasan a clasificarse según los criterios definidos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fa84ce89-acef-43d3-9293-f3c1399e71bc'::uuid, 'Artículos Ocasionales (L)', 'Artículos que se adquieren para promociones determinadas, solo por una vez.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d85c6ec7-3e47-49a0-a942-98707878afc7'::uuid, 'Artículos Pedido Especial (P)', 'Artículos que no poseen inventario. Se almacenan en el Centro de Distribución o se despachan directo del proveedor una vez el cliente realiza la compra.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9a90766b-0366-4b29-b599-7b92e6a21bf7'::uuid, 'Artículos por desarrollar (X)', 'Este término se atribuye a los artículos creados en el ERP para soportar los procesos de proyección de presupuesto y planificación. Su clasificación BDF es X.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b876a0e1-cfd5-45fd-ba9f-1663cfa6d889'::uuid, 'Artículos Suspendidos (Z)', 'Artículos suspendidos por reducción de inventario o faltante temporal del proveedor.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a921fe06-9e53-4444-9175-c29a6318ae3c'::uuid, 'Artículos Temporada (T)', 'Se compran para épocas determinadas todos los años.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b5767fac-92f3-40c0-afc5-6d9001fabf61'::uuid, 'Artículos Triple Básicos (B)', 'Los primero 50 artículos que generan la mayor cantidad de ventas para la empresa, evaluados en cantidades y precio durante un año.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6c659bc6-b43d-4cb5-9ecd-e138e7a6693b'::uuid, 'Ascenso', 'Movimiento vertical ascendente de un colaborador a un puesto de mayor responsabilidad, jerarquía y remuneración.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('80593ba1-d3a3-4974-9b4e-cd65ee946439'::uuid, 'Asesor', 'Refleja el nombre de los Asesores de ventas activos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6405d99e-e7a4-4715-9ed0-e52dbce7e0d1'::uuid, 'Asesor de televentas', 'Realiza la gestión de ventas de forma remota por teléfono para la comercialización de productos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('869ee472-863c-4dcb-b31b-f0235b82349d'::uuid, 'Asesor de ventas', 'Es un profesional estratégico que no solo se encarga de vender, sino también de construir y mantener relaciones con los clientes, actuando como un consultor y un embajador de la marca.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4a43bcfb-60e4-4479-a0d5-1dc339273837'::uuid, 'Asiento', 'Registro formal de una transacción financiera en los libros contables. Cada asiento afecta al menos a dos cuentas (un débito y un crédito) y es la unidad básica para la construcción de los estados financieros.', 'Asiento', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:39:02.557Z'::timestamptz),
  ('f93401a7-54f4-4662-baa2-966397d42e30'::uuid, 'Asignación de expedición', 'Proceso de vincular una expedición con una unidad de transporte específica.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1978b6b0-0816-4c06-bd15-c3e9386e33fe'::uuid, 'Asignación de seguridad', 'Proceso de vincular perfiles con permisos específicos en módulos del sistema.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('82bd6a08-78d7-4497-b821-99a36656151d'::uuid, 'Asignación expedición camión', 'Proceso mediante el cual se debe asignar una expedición a una unidad de transporte para poder realizar la carga del camión.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ddcf1d3a-f07d-46f8-aec9-e58dc3205f6d'::uuid, 'ATEN (atendiéndose)', 'Tareas que los recursos están preparando en el momento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2d44a9ce-0df7-43cb-8d0c-04ee5bb1e93b'::uuid, 'Atributos', 'Las características específicas o propiedades de un artículo que ayudan a definirlo y distinguirlo de otros productos.', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:49:32.409Z'::timestamptz),
  ('9b87f39f-5941-49a0-87b4-11632ba76e49'::uuid, 'Atributos cualitativos del artículo', 'Permiten definir el valor cualitativo de la característica de calidad.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('18a6320b-1473-4455-b202-dcd495003009'::uuid, 'Atributos de colaboradores', 'Conjunto de competencias, habilidades, conocimientos y comportamientos evaluados en el colaborador, utilizados como insumo para la retroalimentación y la toma de decisiones de desarrollo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('98e6b0b2-ec51-441d-80fb-81bc7f12f514'::uuid, 'Audiencia', 'es el grupo de personas que es más probable que se interese en adquirir tu producto, servicio o en interactuar con el contenido de tu marca. Es el público al que se dirigen todas las estrategias de comunicación y publicidad.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4ceed903-7f8b-4034-8e8e-128ee1450007'::uuid, 'Auditoría', 'Proceso sistemático de revisión y verificación de los registros contables y procesos operativos para asegurar su exactitud, cumplimiento con las normativas y eficiencia.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('63080814-630d-4ae7-9395-573b5578b3f1'::uuid, 'Auditoría de normas', 'Evaluación formal del cumplimiento y aplicación de las normas documentadas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f80a6a04-52a4-44c5-bd0b-a6fc6a74ff5a'::uuid, 'Auditoría de procesos', 'Evaluación sistemática para verificar el cumplimiento, eficacia y mejora de los procesos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a363100e-663f-4ef8-a904-f1b582375527'::uuid, 'Auditoría de sistemas', 'Revisión para verificar si los sistemas funcionan bien, son seguros y cumplen con lo esperado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fb77f861-4e2b-4d7c-9e53-a631238d5a35'::uuid, 'Auditoría externa', 'Auditoría realizada por una firma independiente para emitir una opinión objetiva sobre la razonabilidad de los estados financieros. Es clave para la confianza de inversores y bancos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a4917d57-5278-4ac4-87cb-a568130bc23f'::uuid, 'Auditoría interna', 'Actividad independiente dentro de la organización, diseñada para evaluar y mejorar la eficacia de los procesos de gestión de riesgos, control y gobierno corporativo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7aed4c7e-5620-4074-92a3-92047ca70a08'::uuid, 'Ausentismo', 'Frecuencia o duración del tiempo de trabajo en el que un empleado está ausente de su puesto, ya sea por enfermedad, permisos o razones no justificadas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('29cf6716-ca3d-4f5e-8b72-9e11e3bccfe5'::uuid, 'Autenticación', 'Proceso de verificar la identidad de un usuario (ej. ingresar usuario y contraseña).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('336bd53a-c95e-456f-818e-5cc33f33b62d'::uuid, 'Autoevaluación de normas', 'Revisión interna realizada por colaboradores para verificar el cumplimiento de las normas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('20f292a0-beba-4ead-a70d-d38444529da7'::uuid, 'Autoparte', 'Pieza o conjunto de piezas que forman parte de un vehículo, ya sean mecánicas, eléctricas, de seguridad o estéticas', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('93580ff2-6b41-4396-806f-149537b08b3e'::uuid, 'Avalúo', 'Informe que detalla la antigüedad de los saldos de la cartera de clientes (cuentas por cobrar), clasificando la deuda en vencida y por vencer. Es una herramienta crucial para evaluar el riesgo crediticio.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f8df2642-33c5-49a6-9c31-35a616cd8e33'::uuid, 'Backup (respaldo)', 'Copia de seguridad de la información que permite recuperarla en caso de borrado o daño (ej. un archivo guardado en la nube como copia).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('09e66518-a81f-4ef4-86cb-a2e1cb7774a7'::uuid, 'Balance de situación', 'Un estado de la posición financiera de una empresa en un instante de tiempo que muestra los activos y los pasivos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('05ad0b8d-df30-4865-be8a-6900a32388c5'::uuid, 'Balance general', 'Informe financiero que actúa como una "fotografía" de la salud financiera de la empresa en un momento específico. Detalla los activos, pasivos y el patrimonio neto, basado en la ecuación contable:', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('677a7bac-6a56-4edc-abe5-7048966181b5'::uuid, 'Banner', 'En marketing, un banner es un formato publicitario que se utiliza para promocionar una marca, producto o servicio en Internet. Se trata de una pieza gráfica o multimedia (como una imagen, animación o video) que se coloca estratégicamente en una página web con el objetivo de atraer la atención del usuario y dirigir tráfico hacia el sitio web del anunciante.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('12e41012-b323-413c-ad9d-515079a5e992'::uuid, 'Banque', 'Formato de archivo específico (.bak) utilizado para la transmisión de extractos bancarios al sistema de gestión de tesorería XRT.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6779a7de-acd0-4eb3-b57c-814a06eb3164'::uuid, 'Base de datos', 'Conjunto estructurado de datos almacenados de forma sistemática para su posterior recuperación, análisis y transmisión. A diferencia de un reporte estático, una base de datos permite la manipulación dinámica de la información mediante herramientas de BI.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('978bbf94-9f13-42c2-b58c-ecaba813d23f'::uuid, 'BDF', 'Reporte SIM – Dimensión Compras: Refleja la clasificación de los artículos de acuerdo a la nomenclatura BDF. Reporte SIM – Filtro Compra: Permite seleccionar una o mas clasificaciones BDF de articulos.', 'BDF', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, 'Se registran ambos campos técnicos porque varían según la empresa.', false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('7f8e0077-9350-4e58-a59e-69a86f6ae61b'::uuid, 'Benchmarking', 'Comparación de procesos con los de otras organizaciones para identificar mejores prácticas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('322927ed-2f94-40d6-b731-3bcf52815d50'::uuid, 'Beneficiario', 'En el módulo de Caja Chica es la persona a nombre de quien se registrará el vale.', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:49:37.546Z'::timestamptz),
  ('eef1c009-d23a-4b45-abe2-799efc9f3062'::uuid, 'Beneficio', 'Es una remuneración que el empleado recibe por su trabajo. Es un flujo positivo del salario de un empleado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('374800bb-e35a-4b3f-8380-5dd9a56d431e'::uuid, 'BI (Business Intelligence)/ Inteligencia de Negocios', 'Conjunto de metodologías, aplicaciones y tecnologías que permiten reunir, depurar y transformar datos estructurados en información accionable. Su propósito es facilitar la toma de decisiones estratégicas mediante el análisis retrospectivo y predictivo de la operación corporativa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9048360b-7b3f-4d02-b4b3-61e130370c58'::uuid, 'Big data', 'Conjuntos muy grandes de información que requieren herramientas especiales para ser analizados (ej. datos de redes sociales).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('694e0029-10e1-4af3-a090-a0816f46c95b'::uuid, 'Bitácora', 'Registro estructurado de decisiones, alertas y comentarios clave del proceso.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1888ecb9-cfa8-45dd-abba-e5df45dae7a1'::uuid, 'Bizagi', ' Herramienta aprobada para la documentación de los procesos de las compañías de la Organización.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0d4fb517-1f2f-4022-b87e-507e8b6b854d'::uuid, 'Bloques de texto', 'es un componente o elemento de diseño que agrupa un conjunto de palabras, frases o párrafos con un propósito específico dentro de una página web, un correo electrónico, una landing page o cualquier otro formato digital.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e6e40aa1-3a74-441e-9eed-439505447e28'::uuid, 'Boceto', 'es una representación visual preliminar, rápida y esquemática de una idea o concepto. Es el primer paso en el proceso creativo, ya sea en el arte, el diseño, la arquitectura o incluso en la publicidad y el marketing.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f6dfaec7-a1ed-440e-ae23-9d2fb12f04c2'::uuid, 'Bodega', 'Softland: Instalaciones físicas donde se almacenan las materias primas, los productos terminados y los suministros relacionados con la empresa. La definición de privilegios por usuario para cada bodega se realiza en el módulo de Administración del Sistema. Reporte SIM – Dimensión Ventas: Muestra las bodegas que conforman los almacenes de las compañías.', 'Bodega', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-10-02T01:39:09.269Z'::timestamptz),
  ('3d9bc66c-3e85-4635-b05e-43acf096c125'::uuid, 'Bodega comercial', 'Bodega que contiene el inventario disponible para la venta', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c4e11d09-6085-44b2-aec7-a52604e6aea8'::uuid, 'Bodega consignación', 'Bodega que contiene el inventario que se recibe por medio de consignación', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('319219ff-0102-4acb-aa78-2f8167eed6f2'::uuid, 'Bodega dañado', 'Bodega que contiene el inventario proveniente de la bodega de garantías que se ha decidido sea destruido por medio de rebaja cero', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e6d10ea0-5797-477d-b8c5-5f7464dc464a'::uuid, 'Bodega garantías', 'Bodega que contiene el inventario no disponible para la venta debido a que la mercancía se encuentra dañada o averiada y está pendiente de la validación de la garantía', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('385f0450-0b1b-46d1-9ca5-8485ac76f5ef'::uuid, 'Bodega mercadeo', 'Bodega que contiene el inventario de regalías y materiales de mercadeo', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1ad2abd1-55e0-4e2d-a840-cf2ce5766928'::uuid, 'Bodega suministro', 'Bodega que contiene el inventario de suministros para consumo propio de la empresa', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8cb331b0-6765-46ff-9e18-ec417f56e3be'::uuid, 'Bodega taller/laboratorio', 'Bodega que contiene el inventario de repuestos para Taller', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1ab74e29-b076-4683-995d-aaf066a55bf3'::uuid, 'Bonificaciones', 'Valor total de bonificaciones o descuentos aplicados a la venta.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f6ae7d9c-ddb4-47a7-b5c0-124b45c6e2f3'::uuid, 'Bono', 'Compensación económica adicional al salario base, usualmente asociada al cumplimiento de metas, resultados, productividad o para ocasiones especiales (bono navideño, de vacaciones, etc.). En Venezuela se le conoce comúnmente como "Utilidades".', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2c4bffe8-885d-4d9d-8240-cad82991c026'::uuid, 'Bono de alimentación', 'Beneficio no salarial que se otorga a los empleados para cubrir parcial o totalmente sus gastos de alimentación. Muy común en Venezuela y de aplicación en ciertos sectores en Colombia. En Costa Rica existe la figura del "Aguinaldo" que es diferente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c8fc44e8-574f-40f0-885c-dc318e3fce9f'::uuid, 'Booleano', 'Tipo de dato que solo puede admitir uno de dos valores posibles: Verdadero (True) o Falso (False). Se utiliza para indicadores de estado binario (ej. Facturado: Sí/No, Entregado: Sí/No).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1ed78209-8954-47d5-ae1a-bf29a656c0ab'::uuid, 'BPA', ' Business Process Architecture. Es una visión general del negocio. Es una herramienta de comunicación (Comerciales, Técnicos y Modeladores). Muestra la secuencia lógica del flujo de Procesos de la Organización y sus relaciones. Facilita el entendimiento de la conexión entre los objetivos o plan estratégico y la cadena de valor del Negocio. Representa lo que se hace. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d4a11ae2-2b86-4ab2-acd6-56fc286e30d6'::uuid, 'BPM', ' Business Process Management. Es un conjunto de herramientas, tecnologías, técnicas, métodos y disciplinas de gestión para la identificación, modelización, análisis, ejecución, control y mejora de los procesos de negocio. Las mejoras incluyen tanto cambios de mejora continua como cambios radicales. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('cae3b7db-ac82-4be4-9a27-8989ba4fd4d6'::uuid, 'BPMN', ' Business Process Modeling Notation es una notación gráfica que describe los procesos de un Negocio. Es un lenguaje común para que la comunicación de los procesos sea de forma clara, completa y eficiente. Ha sido diseñado para coordinar la secuencia de los procesos y los mensajes que fluyen entre los participantes de las diferentes tareas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('78d65aca-aeec-4ced-8d66-6f77d25c834d'::uuid, 'Branding', 'El proceso de crear y gestionar una marca. Esto incluye el logo, los colores, la voz y la estrategia de comunicación para generar una percepción positiva y coherente en la mente del consumidor.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8d3bd529-aa4b-4771-af0b-6a9d1e43f0a8'::uuid, 'Brief', 'En marketing, un brief es un documento conciso y claro que sirve como hoja de ruta para un proyecto. Su principal objetivo es comunicar de manera efectiva las necesidades, metas y expectativas de un cliente a un equipo de marketing, una agencia o un profesional independiente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('99940ac2-aad5-434a-ac7c-1fc8b51d9504'::uuid, 'Business Blueprint', 'Documento de referencia del proyecto que recoge el alcance, las funcionalidades, la gobernanza, las reglas de negocio, la arquitectura conceptual y los criterios de aceptación. Es la línea base del proyecto una vez firmado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4d952bd5-aa10-432a-8c50-dfeceba06263'::uuid, 'Buyer persona', 'En marketing, un buyer persona es una representación semi-ficticia y detallada de tu cliente ideal. A diferencia del "público objetivo", que es una descripción amplia y demográfica', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b045f075-a27d-44d9-8b06-ed3a16d1dc15'::uuid, 'Cabecera de la recepción', 'Indica la información general de la orden de recibo y la información necesaria para el control de la mercadería en el almacén.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d8de4c4d-ad7e-4aa5-ba1b-12934411d19f'::uuid, 'Cadena de Texto', 'Tipo de dato compuesto por caracteres que pueden incluir letras, números, espacios y símbolos. Se utiliza para descripciones, nombres o códigos que no requieren cálculos matemáticos (ej. Nombres de clientes, SKUs, observaciones).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('cdbdf3f6-82b3-4e54-bf7e-c7afa108fcc7'::uuid, 'Caja', ' Se refiere a la denominación utilizada para referirnos a un macroproceso, proceso, una actividad o una tarea que se encuentra diagramado. ', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:49:40.552Z'::timestamptz),
  ('d54b84b3-37ee-411d-98cd-c6acd0c6e641'::uuid, 'Campaña', 'es un conjunto de acciones y esfuerzos coordinados que una empresa realiza durante un período de tiempo determinado para alcanzar un objetivo específico. Es una iniciativa estratégica y planificada, a menudo con un mensaje central o un tema unificador, que se ejecuta a través de diversos canales de comunicación.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('63d3eb0a-0cfe-46d0-9755-ae2b044003d4'::uuid, 'Campo calculado', 'Silo Sistemas: Unidad mínima de información que compone un registro. En una estructura de datos, corresponde a las columnas y representa un atributo específico (ej. Fecha, Monto, SKU). Silo Sistemas: Columna creada a partir de una fórmula para mostrar información derivada de los datos originales.', '', 'dudoso'::estado_origen_termino, 'Las dos filas originales compartían término y etiqueta (Silo Sistemas), pero una definición describía “Campo” en general y la otra sí describía “Campo calculado”. Se conservó la definición correcta para el término; “Campo” no existe como término aparte en el glosario y podría agregarse.', false, NULL, false, false, NULL, NULL),
  ('8dfc0f6d-ea80-4325-9aa1-0a3f5aa29129'::uuid, 'Canales de ventas', 'Representan los puntos de contacto donde los clientes pueden descubrir, evaluar y comprar nuestros productos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('88744fcc-cb27-4602-aa4b-fce0149a7e0d'::uuid, 'Cantidad de empaque', 'La cantidad de cajas teóricas de un artículo en una ubicación específica.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d61cc8d9-82ea-4b05-87c7-5b29107b0fa0'::uuid, 'Cantidad días pedidos', 'Número de días con pedido.', '', NULL, NULL, false, NULL, false, false, NULL, NULL)
ON CONFLICT DO NOTHING;

INSERT INTO terminos (id, termino, definicion, campo_softland, estado_origen, nota_origen, revisado, nota_decision, es_nuevo, editado, eliminado_en, actualizado_en) VALUES
  ('61868244-4edd-4e3f-ba94-a52acf3a2b2a'::uuid, 'Cantidad pedido', 'Conteo de pedidos generados.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('60003f55-6cee-4784-a1e0-51be7d4b8c5c'::uuid, 'Capa de costo', 'Cuando se utiliza el tipo de costeo UEPS o PEPS, el sistema permite un infinito número de capas de costo por cada ingreso al inventario. Cada capa representa un ingreso, y en cada una de ellas se guarda la información de la cantidad original ingresada, la cantidad restante (después de hacer consumos), el costo unitario y el costo total.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('44365b45-4db2-4853-9b36-cae664e3ce77'::uuid, 'Capital de trabajo', 'Métrica de liquidez que representa los recursos que necesita la empresa para sus operaciones diarias. Se calcula como', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('af3168a4-867d-4f30-b78c-17fb7b564add'::uuid, 'Capital intelectual', 'Conocimiento y experiencia documentada que permanece en la empresa como activo estratégico.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('305e0d18-6827-46eb-8a1e-9da8f7a851f5'::uuid, 'Captura fotográfica', 'Registro visual de condiciones del producto durante la recepción.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f510e273-6f65-45c9-88c3-c2cd16c8942e'::uuid, 'Carga a piso / a piso', 'Tipo de estiba que corresponde a la modalidad de transporte y almacenamiento en la que la mercancía se coloca directamente sobre el piso del vehículo, contenedor o bodega, sin utilizar pallets, estibas ni ningún otro tipo de plataforma de soporte intermedia.
Nombre Internacional Oficial: Floor Loaded Cargo / Loose Loaded', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('71c524f2-85b9-4064-b658-88ccd225b167'::uuid, 'Carga camión rf', 'Proceso de carga de camión que se realiza utilizando el dispositivo de radio frecuencia.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('719cfe41-ac48-44da-a550-56f665c0c231'::uuid, 'Cargo', 'Conjunto de funciones, responsabilidades y deberes asignados a un empleado. Sinónimo de "Puesto de Trabajo".', 'Cargo del Contacto', NULL, NULL, false, NULL, false, false, NULL, '2026-09-30T19:30:00.000Z'::timestamptz),
  ('2ea5bcba-ba7a-4354-be1f-b7d168d9cc05'::uuid, 'Cartera (Clientes)', 'Conjunto de clientes que debe ser mantenido al día por el departamento de Operaciones y Administración de Ventas.', '', 'homonimo'::estado_origen_termino, 'Se separó de un término homónimo compartido con: Cartera (Cuentas por Cobrar).', true, NULL, false, false, NULL, '2026-09-28T16:05:00.000Z'::timestamptz),
  ('74da4cc1-da25-4776-930a-4f5fe6cb584f'::uuid, 'Cartera (Cuentas por Cobrar)', 'Silo Control: El valor total de las deudas que los clientes tienen con la empresa en una fecha determinada. Su análisis por antigüedad de saldos es fundamental para gestionar el riesgo de incobrabilidad. Reporte SIM – Indicador Venta: Sumatoria del total de las Cuentas por Cobrar, es decir el monto total de dinero que los clientes le deben a la compañía.', '', 'homonimo'::estado_origen_termino, 'Se separó de un término homónimo compartido con: Cartera (Clientes).', true, NULL, false, false, NULL, '2026-09-28T16:05:00.000Z'::timestamptz),
  ('cad059d2-b187-4d74-804c-3a9b94c3fe34'::uuid, 'Cartera >30', 'Es la sumatoria de la deuda por cobrar a más de 30 días', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('96cea58c-9c9c-4bae-9bab-b10ab037649f'::uuid, 'Casos contables', 'Particularidades que se pueden presentar para un Evento Contable determinado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ea677fc7-f5f7-4737-a4ea-611b8915d33a'::uuid, 'Cat- Marca', 'Es la categoría en la cual el proveedor clasifica el producto.', 'Cat-Marca', NULL, NULL, false, NULL, false, false, NULL, '2026-09-30T19:30:00.000Z'::timestamptz),
  ('672bb14a-6d84-48da-bb59-1f4a1f582315'::uuid, 'Categoría', 'Reporte SIM – Dimensión Compras: Muestra las categorias creadas para segmentar los artículos. Reporte SIM – Dimensión Ventas: Una categoría es una clasificación o grupo que se utiliza para agrupar elementos que comparten características o propiedades comunes. Reporte SIM – Filtro Compra: Permite seleccionar una o mas categorias especificas de los articulos. Silo Compras: Una clasificación dentro de un grupo, donde cada grupo debe contener un rango de 10 a 30 categorías. Los nombres de categorías deben ser descritos en singular, en mayúsculas y sin acento, y no deben llevar conectores. Es la clasificación más general de un producto.', 'Categoria', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 4 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('54c95665-119b-4a6d-a401-7a7f3d1abc29'::uuid, 'Categoría cliente', 'Reporte SIM – Filtro Venta: Permite seleccionar una o mas categorias de clientes. Reporte SIM – Dimensión Ventas: Muestra la clasificación que se utiliza para agrupar a los clientes de la compañía.', 'Categoría', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('e36e4409-2f84-4cd7-be22-0488fa92b308'::uuid, 'Categoría Proveedor', 'Clasificación que el proveedor asigna al producto según su propio criterio comercial, independiente de la categoría interna definida por la empresa.', 'Categoría Proveedor', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:34:54.630Z'::timestamptz),
  ('86af93da-172d-4768-ac54-9501cf94ded7'::uuid, 'Catálogo de promociones', 'Vista consolidada de todas las promociones del sistema, con filtros de búsqueda por estado, tipo, vigencia, canal, etc.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('62bd4b73-155a-4da3-ab84-a656a26931bb'::uuid, 'Causas comunes', 'En control de calidad, fuente inherente de variación que es 1. aleatoria, 2. siempre presente y 3. afecta todos los resultados del proceso. La causa común suele atribuirse a un elemento del sistema que solo la gerencia puede corregir. También se denomina causa asignable.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('272f5e2a-23c1-406b-b04a-02f5b147fb2e'::uuid, 'CCA', ' Customer Consulting Application. Portal de consulta web integrado a eflow WMS. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('260eda61-b279-49e9-aba7-fc748b824f77'::uuid, 'CEDI', 'Centro de Distribución. Área operativa crítica donde se realizan actividades de almacenamiento, picking, empaque y despacho, que requiere estrictos protocolos de seguridad y uso de EPP.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c4ed6b87-b155-4324-b142-422bfc746f46'::uuid, 'Centro de costo', 'Unidad organizativa (departamento, proyecto, etc.) a la que se le asignan costos y gastos para un mejor control y análisis de la estructura de costos de la empresa.', 'Centro de Costo', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:39:22.833Z'::timestamptz),
  ('e41c3b16-7eca-4119-8883-0200ba956f05'::uuid, 'Centro de Costos', '', 'Centro de Costo', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:39:24.532Z'::timestamptz),
  ('03d966f9-539b-4c8e-a9da-1136e069f191'::uuid, 'CEO', 'Es el líder que traza el rumbo para que el equipo de mercadeo pueda ejecutar las acciones. La relación entre ambos es crucial: un CEO visionario y un equipo de mercadeo que lo entiende bien pueden crear una marca poderosa y exitosa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ff6a102a-a7aa-4c34-8703-b578b0c6046a'::uuid, 'Certificación interna', 'Proceso mediante el cual la empresa valida que un colaborador cumple con los estándares requeridos para operar equipos o desempeñar funciones específicas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5f87cf47-1635-44d0-b71d-a05348599d25'::uuid, 'Cesantías', 'Prestación social a la que tiene derecho el empleado en Colombia, que consiste en un ahorro forzoso para su protección en caso de quedar desempleado. Equivalente aproximado a la "Prestación de Antigüedad" en Venezuela y a la "Cesantía" en Costa Rica, aunque los regímenes de cálculo y pago son diferentes.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e795b72b-63aa-45b9-919b-f823fc02ef1c'::uuid, 'CFR', '(Cost and Freight - Costo y flete (puerto de destino convenido)). El vendedor se hace cargo de todos los costos, incluido el transporte principal, hasta que la mercancía llegue al puerto de destino. Sin embargo, el riesgo se transfiere al comprador en el momento que la mercancía se encuentra cargada en el buque, en el país de origen.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b1def5e6-ec46-49a0-a66f-9bda9573169c'::uuid, 'Chatbot', 'Programa que conversa con los usuarios de forma automática, como los asistentes en páginas web.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5a923afb-d8c5-4573-89a2-2b9df9d8fc55'::uuid, 'Check box', 'Especie de "interruptor" que habilita o deshabilita una opción asociada. ​ Este interruptor se puede activar con el ratón, presionando el botón izquierdo con su cursor sobre el recuadro, o bien, con el teclado cuando la opción esté encerrada en un recuadro punteado. ​', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0cf63b13-f647-47d2-881f-bd33faff13c5'::uuid, 'Check list', 'Tipo de marca que se utiliza para seleccionar una casilla con múltiples opciones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1d938d02-ff4b-4f95-a708-8b3177860dbc'::uuid, 'Cheque', 'Documento de débito por medio del cual es posible pagar documentos pendientes.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5b7846a7-7b7a-4c42-ba7a-3e28d87135f6'::uuid, 'Ciclo de vida del software', 'Etapas por las que pasa un sistema: análisis, desarrollo, pruebas, implementación y mantenimiento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6c4e9190-a7a5-44d5-af4f-66a392445986'::uuid, 'Ciclo PDCA (ciclo de deming)', 'El ciclo de Deming, o ciclo PDCA (también conocido como ciclo PDSA), es un modelo de mejora continua de la calidad que consiste en una secuencia lógica de cuatro pasos repetitivos para la mejora continua y el aprendizaje: Planificar, Hacer, Estudiar (Verificar) y Actuar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4a780c50-d29a-4e4e-90de-40c5474c0ea6'::uuid, 'Ciclo PHVA', 'Metodología de mejora continua: Planificar, Hacer, Verificar, Actuar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('603a8209-c844-4453-a939-b380a9c9a20e'::uuid, 'Cierre de orden', 'Finalización del proceso de recepción y envío de datos al ERP.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8984ea5e-3b2f-48ca-a47d-28d73bbb1046'::uuid, 'Cierre de orden de recepción', 'El paso final para dar por recibido el documento y proceder con el envío de información vía interfaz al ERP.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('44a65f9d-d5b0-4b81-91b2-66b8ddc35ce0'::uuid, 'Cierre forzado', 'Finalización manual del proceso de carga cuando hay pendientes, requiere autorización.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ab148210-e1d1-4dc0-a11b-fd0b1b3c9808'::uuid, 'CIF', '(Costo, Seguro, Flete). Es el valor aduanero que representa la base para el cálculo de todos los impuestos asociados a la importación. Se calcula sumando el costo, el seguro, el flete internacional y los gastos incurridos desde el origen hasta la llegada al puerto de embarque.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('cd331226-cd6b-48fc-b64b-33cc66061965'::uuid, 'Cinco S (5S)', '5S es una herramienta sencilla para organizar su lugar de trabajo de forma limpia, eficiente y segura, mejorando así su productividad, la gestión visual y garantizando la introducción del trabajo estandarizado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6ad2327c-5e6b-4b06-9ff6-0c9f452d8787'::uuid, 'CIP', '(Carriage and Insurance Paid (To) - Transporte y seguro pagados hasta (lugar de destino convenido)). El vendedor se hace cargo de todos los costos, incluidos el transporte principal y el seguro, hasta que la mercancía llegue al punto convenido en el país de destino. Aunque el seguro lo ha contratado el vendedor, el beneficiario del seguro es el comprador.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5cb30859-86f6-40d1-a06f-9918cfbd4636'::uuid, 'Clasificaciones adicionales del artículo', 'Información que sirve para establecer una búsqueda más rápida y exacta de los diferentes artículos del inventario.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('722d3b03-deef-42a7-b4d1-daa174746cf1'::uuid, 'Clasificaciones del artículo', 'Son posibles subdivisiones para cada tipo de clasificación de artículos. El sistema permite un máximo de seis clasificaciones por artículo, y los nombres de estas se definen en la sección de Parámetros del Módulo.', 'Clasificación Artículo', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:49:51.537Z'::timestamptz),
  ('24f73744-0786-43d7-9418-00c3828a43f7'::uuid, 'Clasificación BDF', 'Un sistema para clasificar artículos según su tipo: N (Nuevo), L (Ocasional) o P (Pedido Especial).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('879bc3e2-1f38-4aec-8cfe-a1fb6c4ade57'::uuid, 'Clasificación de información', 'Categorización del contenido documental según su nivel de sensibilidad: restringida, interna o pública.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2da438cf-e4ff-42ab-9d96-330753c41554'::uuid, 'Cliente', 'Silo Ventas: Persona natural o jurídica, debidamente registrada que realiza transacciones sobre los bienes comercializados. Reporte SIM – Dimensión Ventas: Muestra los clientes que adquieren los productos y servicios de la organización.', 'Cliente', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-10-02T01:39:28.790Z'::timestamptz),
  ('5e111960-30c1-4a79-9448-aade3eac7166'::uuid, 'Cliente corporativo', 'Cliente que trabaja bajo una jerarquía organizacional donde se tiene un único cliente principal llamado Corporación o Matriz de Corporación y otros múltiples asociados a ésta, llamados sucursales.', 'Otros — Corporación', NULL, NULL, false, NULL, false, false, NULL, '2026-09-30T19:30:00.000Z'::timestamptz),
  ('6fead420-048f-4f17-954f-51943ec68902'::uuid, 'Cliente Dummy', 'Registro genérico y temporal en el ERP utilizado para presupuestar y registrar operaciones cuando no se dispone de clientes reales identificados, permitiendo consolidar transacciones iniciales que, posteriormente, se reasignarán a los clientes definitivos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fbee7bc3-bb79-4855-8cbc-f9222628459a'::uuid, 'Cliente espejo', 'Se refiere a una réplica de un cliente existente, que comparte sus mismos atributos. El propósito es permitir una diferenciación y gestión independiente entre portafolios.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0d52f24a-ba82-4396-9c81-bdc0e8eb6d64'::uuid, 'Cliente externo', 'Un usuario final que adquiere los productos o servicios de una empresa, pero no es empleado ni forma parte de la organización. El objetivo de las empresas de clase mundial es deleitar continuamente a este cliente, creando así un creciente afecto por sus productos y servicios.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1c0e85be-4f10-415d-b081-463cc96a0a78'::uuid, 'Cliente interno', 'Cualquier miembro de una organización que depende de la ayuda de otro para cumplir con sus tareas laborales, como un representante de ventas que necesita ayuda de un representante de servicio al cliente para realizar un pedido.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('082cd402-ffff-4ba0-a019-121120dc9f14'::uuid, 'Cliente registro', 'Cliente donde se registra una transacción, ya sea propia o de otra entidad.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5f0c90f2-00c8-47a4-9361-44d8db8d4cc1'::uuid, 'Cliente reporte', 'También es llamado cliente origen y representa la entidad que generó la transacción.', 'Cliente Reporte', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:49:53.429Z'::timestamptz),
  ('144b0c7c-b38a-493e-9942-b17d79a296c7'::uuid, 'Cliente sucursal', 'Cliente que pertenece a un esquema organizacional y que depende directamente de un cliente corporación, el cliente sucursal no puede tener asociado alguna otra subsidiaria solamente existe una relación uno a uno con la corporación.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('075f07d5-10ab-4417-8c6b-6f2b0d5c3f6a'::uuid, 'Clientes', 'Total cartera de clientes actual.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('80f860f9-c5ab-484d-945b-711b4b0cb293'::uuid, 'Clientes activados', 'Todos los clientes con una venta superior a 0.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('00e5d40b-cda2-486d-954d-afb6bdfb1363'::uuid, 'Clientes activados %', 'Representa el índice o tasa de activación de clientes', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('97035dc3-536f-4b5c-afc3-4be86d60f3c2'::uuid, 'Clientes bloqueados', 'Es un cliente al que se le ha restringido la posibilidad de realizar ciertas transacciones, como crear nuevos pedidos o facturas. Este bloqueo puede ser temporal o permanente, y las razones para aplicarlo pueden variar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1f819569-19c1-4ab0-8a10-cf930aa5fe9c'::uuid, 'Clientes Inactivos', 'Representa el número de clientes inactivos. Aclara que un "cliente inactivo" no es un cliente que ha dejado de serlo por completo, sino uno que está en un estado de inactividad dentro de la base de clientes activos.', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:50:05.940Z'::timestamptz),
  ('db79e919-4abc-40a3-9c79-425c100615fc'::uuid, 'Clima', 'Es una métrica cuantitativa que mide la percepción colectiva de los colaboradores respecto a su ambiente de trabajo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8c755284-5b00-48d9-ac26-4e2cf6b03c73'::uuid, 'Clima organizacional', 'Percepción colectiva y subjetiva de los colaboradores sobre el ambiente de trabajo, las relaciones interpersonales y las condiciones laborales en un momento dado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3226b77f-59ce-48e8-8ef0-a4e880a67727'::uuid, 'Cloud computing', 'Servicios de almacenamiento y programas que funcionan en internet en lugar de instalarse en la computadora (ej. Google Drive, OneDrive).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ba0b37d4-e3a7-4f6f-9964-0f2ade015909'::uuid, 'Cláusula', 'Una disposición o condición específica dentro de un contrato que define derechos u obligaciones de las partes.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0103ffea-8643-4a5f-90aa-2bbd33b4e12b'::uuid, 'Cláusula de confidencialidad', 'Acuerdo incluido en el contrato de trabajo por el cual el empleado se compromete a no divulgar información sensible o propietaria de la empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0591371a-b0a6-4c2d-bb15-a45a1e3ff5b7'::uuid, 'CMYK', 'es un modelo de color que se utiliza principalmente en la impresión de materiales físicos. Es un acrónimo de los cuatro colores de tinta que se usan para crear la mayoría de los colores impresos: C = Cian (un azul verdoso), M = Magenta (un rojo purpúreo), Y = Yellow (Amarillo), K = Key (Negro)', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('bbb04904-62a7-4425-b4e6-872b97e1a99d'::uuid, 'Cobro', 'Monto de cobranza realizada por vendedor distribuida por artículo.', 'COBRO', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:50:07.525Z'::timestamptz),
  ('705656df-3e02-4d5d-b5e3-03ab5c140722'::uuid, 'Colaborador', 'Silo Personal: Persona que trabaja en la empresa y está sujeta a sus normas y políticas. Reporte SIM – Dimensión Personal: Refleja a todas las personas que presta sus servicios para la compañía, contribuyendo al logro de sus objetivos y metas.', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('6393a36f-6089-4e04-88ad-29c364e11735'::uuid, 'Colaboradores', 'Es un indicador de capacidad y tamaño de la fuerza laboral que representa el número total de personas que tienen una relación laboral activa con la organización en un momento específico en el tiempo (una fecha de corte).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('383c1915-433a-4bd6-8f7e-10f6b6290fed'::uuid, 'Colaboradores %', 'Es un indicador de composición o distribución que se utiliza para medir la proporción o el peso que un subgrupo específico de colaboradores representa dentro del total de la fuerza laboral de la organización. Expresa el tamaño de una parte en relación con el todo en forma de porcentaje.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('52b95173-f65c-4f6a-98c0-c3e473e46798'::uuid, 'Color', 'Describe el color principal del producto. Si un artículo tiene dos o más colores, se mencionan todos. Si el color no es una característica esencial para la venta, no se incluye en la descripción.', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:50:08.961Z'::timestamptz),
  ('0f871c56-32d1-4abd-9dce-682d15668aa6'::uuid, 'Combinación', 'Ordenaciones de elementos en un conjunto donde no importa el orden de estos elementos, las selecciones de los objetos se llaman combinaciones, donde abc es igual que bca.', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:50:10.366Z'::timestamptz),
  ('99f2e0b3-21cf-4ecc-bae8-092d688c8631'::uuid, 'Combo', 'Silo Compras / Silo Mercadeo: Se refiere a una oferta que agrupa varios productos, a menudo a un precio reducido, para incentivar la compra. Los productos en un combo no necesariamente se utilizan juntos, pero se venden como un paquete promocional.', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('9049f3f5-3d13-4812-ab89-541d77b5598c'::uuid, 'Combo box', 'Especie de "lista" que muestra los posibles valores que puede tomar la opción asociada a un campo. Este interruptor se puede activar con el teclado cuando la opción esté encerrada en un recuadro punteado, utilizando las flechas para desplazarse a través de él.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('cdfa5be7-46d7-4bdc-9a71-01e855bbb05c'::uuid, 'Comité de aprobación', 'Es el equipo que evalúa y aprueba las solicitudes de inclusión de nuevos productos y proveedores en el sistema.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('16fc7bbc-3f7e-4892-b6a7-54f1c26ce748'::uuid, 'Comité de Control de Cambios (CCB)', 'Instancia formal para la revisión y aprobación de modificaciones al alcance del proyecto.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ea7736ed-3a99-4c6f-ba05-89a975c2be5d'::uuid, 'Comité de salud ocupacional', 'Grupo conformado por representantes de la empresa y de los empleados, encargado de promover la seguridad y salud en el trabajo. Su nombre y conformación puede variar ligeramente (Copaso en Colombia, Comité de Seguridad y Salud Laboral en Venezuela).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('57bc8c06-7952-4fdd-9b1e-9b1df66d925d'::uuid, 'Compañía', ' Entidad propietaria de los catálogos, documentos e inventarios que se gestionan en el almacén. ', 'Compañía', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:39:44.984Z'::timestamptz),
  ('33c7f3e2-e555-4574-a7b9-0b8603f8304f'::uuid, 'Compensación', 'Aportaciones que confiere la organización a cada persona a cambio de su trabajo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('468bdddc-ce8a-4022-b9e0-01620617e70a'::uuid, 'Competencias organizacionales', 'Conjunto de conocimientos, habilidades, destrezas y actitudes que un empleado aplica para desempeñar exitosamente sus funciones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a883cf3b-21da-4f0d-9fe8-a920991ae397'::uuid, 'Componentes', 'Estos son partes o submontajes que se encuentran listos para ir al montaje final del producto.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ca726239-15d9-4409-bab1-a67871704628'::uuid, 'Composición', 'es la organización y disposición de los elementos visuales dentro de un espacio o formato. Es el arte de colocar y relacionar objetos, formas, colores, líneas y texturas de manera armónica y equilibrada para crear una imagen atractiva y con un propósito.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6b728f4d-aa09-4823-b33e-392edd58f23f'::uuid, 'Comprador', 'Empleado encargado de crear y dar seguimiento de las órdenes de compra enviadas a los proveedores de la empresa', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('18e70aa5-6cc9-4d00-928c-1dd9746aa36a'::uuid, 'Compras', 'Sumatoria del monto liquidado de los embarques en moneda local y dólar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('950aed9e-4739-4f2d-8ea6-21609a741d09'::uuid, 'Conceptos', 'En cualquier sistema de nómina existen rubros que se le pagan al empleado, rubros que se le deducen, y rubros que no afectan el pago neto del empleado, pero que se toman en cuenta para efectos de previsiones o aportes patronales. Para agrupar estos rubros se utiliza el término concepto; dentro del sistema, la forma de calcular cada concepto es configurable mediante una fórmula algebraica.', 'Concepto', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:39:49.110Z'::timestamptz),
  ('0e165717-a0d2-4d87-bc84-d3902e499e14'::uuid, 'Conciliación bancaria', 'Proceso crítico de control que consiste en comparar los registros contables internos (Saldo en Libros) con los extractos bancarios externos (Saldo en Bancos) para identificar, explicar y corregir cualquier discrepancia.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b278c633-65a3-4efa-be40-90630bb20b54'::uuid, 'Conciliación de cobranzas', 'Proceso específico de validación en Sage XRT que consiste en hacer coincidir los recibos de cobro generados internamente con los depósitos y transferencias reflejados en los extractos bancarios.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('45acdd76-b08b-425b-a3fa-4b917679313e'::uuid, 'Conciliado en firme', 'Indica que la conciliación entre los documentos del sistema y los reportados por el banco ha sido satisfactoria por lo que la conciliación ha sido aprobada. Debemos recordar que un documento aprobado no puede ser modificado en la base de datos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4515e60e-c9dd-498a-bc76-f8e8cc4333e5'::uuid, 'Conciliado temporal', 'Indica que el documento se encuentra en el estado de cuenta del banco, pero aún no ha sido aprobado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ddd900c6-fe56-4687-9883-859f9bc66e65'::uuid, 'Condiciones comerciales de compra', 'Conjunto de acuerdos comerciales negociados entre la empresa y el proveedor de un bien o servicio. Incluye aspectos como descuentos, días de crédito, rebajas, condiciones de despacho, garantías y formas de pago.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ab24f441-88fa-41c4-bd75-329d26c1d2fc'::uuid, 'Condición de pago', 'Define la forma en que deberá ser cancelado un documento de débito, ya sea al contado o al crédito. La condición de pago involucra un descuento por pronto pago y una tasa de interés involucrada en el período de crédito.', 'Condición de Pago', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('1369e5d7-4baa-497e-9b55-4162184d69e9'::uuid, 'Configuración general', 'Sección del sistema donde se definen parámetros globales.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('cab3e766-3cf9-49d9-8ca7-c1ca9099a170'::uuid, 'Confirmación', 'Validación de que el contenedor está en condiciones para ser recibido.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b206bd39-864d-44aa-b0df-c337a15e8b4c'::uuid, 'Conflicto', 'Situación en la que dos o más promociones coinciden en vigencia, canal, audiencia y artículos, generando incompatibilidad según las políticas definidas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('35b0dfde-ef5a-46f7-9ff1-5d1e554aa3ab'::uuid, 'Consecutivos', 'Un número consecutivo que se generará automáticamente una vez que el usuario defina el tipo de consecutivo, lo que permite controlar las transacciones de inventario. El manejo del código del artículo tiene una condición especial si los artículos utilizan consecutivos definidos en Administración del Sistema.', 'Consecutivo', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:35:31.286Z'::timestamptz),
  ('b183ec05-17f7-4a10-b775-88b74fa2d50b'::uuid, 'Consulta (query)', 'Proceso para obtener y transformar datos desde una fuente específica.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7add3bb1-6d86-48a2-861a-ccb64935d6c0'::uuid, 'Contabilidad', 'Sistema de control y registro de los gastos, ingresos y demás operaciones económicas que realiza una empresa, con el fin de extraer información financiera útil para la toma de decisiones.', 'CONTABILIDAD', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:40:30.013Z'::timestamptz),
  ('8e7065db-72cb-4ad1-9e1c-f29e8c4d0689'::uuid, 'Contenedor (en recepción)', 'Un identificador de la orden, puede ser la unidad de transporte o un dígito verificador. Se usa para diferenciar órdenes cuando se recibe más de una por muelle.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('76beeb7b-72e2-4e80-9ba7-d34d4e8c649a'::uuid, 'Conteo', 'Registro de cantidades físicas por ubicación, artículo, lote y fecha de vencimiento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c9fec659-9f86-4173-a3f1-55e87865dc1f'::uuid, 'Conteo cíclico', 'Consiste en hacer inventarios con una muestra de elementos específicos en intervalos regulares, de modo que los registros sean verificados periódica y parcialmente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('334d1c95-f825-4b1c-a563-8586e21810f1'::uuid, 'Conteo por ubicación', 'Se denomina conteo por barrido y esto quiere decir que se va contando la mercancía de acuerdo a su ubicación geográfica dentro del almacén, contando todo lo que se observe en el pasillo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3a18157e-34fe-4016-817e-6493357fb901'::uuid, 'Contratación outsourcing', 'Modalidad mediante la cual la empresa contrata a un tercero (empresa externa) para que gestione la nómina y la administración de un grupo de empleados, quienes prestan servicios para la empresa usuaria. Sujeta a regulaciones estrictas en los tres países.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3afffc20-7aaf-4afa-a52c-9d515c9e42bc'::uuid, 'Contratista', 'Personal temporal o asignado a proyectos específicos, como mantenimiento o construcción.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('df2a5f2b-824b-4b7e-aae4-8daa90fd06fd'::uuid, 'Contrato', 'Acuerdo legal, oral o escrito, entre dos o más partes que genera derechos y obligaciones.', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:50:11.742Z'::timestamptz),
  ('973acff1-3e05-4f31-9bbc-ca10695b97ef'::uuid, 'Contrato de trabajo a término fijo', 'Contrato laboral que se celebra por un tiempo determinado, previamente establecido.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d03373dd-300f-4b90-91bc-2d703eb78740'::uuid, 'Contrato de trabajo a término indefinido', 'Contrato laboral que no tiene una fecha de finalización definida.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f22bccba-178e-4b14-885d-4446ab180ab0'::uuid, 'Contribución', 'Silo Control: Resultado de restar el costo de la mercancía vendida (CMV) a las ventas netas. Refleja el ingreso disponible para cubrir gastos operativos y generar utilidad. Reporte SIM – Indicador Compra: Esta fórmula calcula la ganancia inicial de la compañía. Simplemente, resta el costo directo de lo que vendiste (el costo de venta) de los ingresos totales que generaste (la venta neta).', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('e38f6dbc-02b8-4bb7-b680-a96cf071ae57'::uuid, 'Contribución con rebates', '', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ce8663c7-7119-49ae-b7fa-b4648099110e'::uuid, 'Contribución total', '', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('16fb12bd-227c-4bd9-847f-6468b69c2452'::uuid, 'Contribución vacacional', 'Cada uno de los factores que inciden en la cantidad de días de vacaciones que le corresponden a un empleado por derecho por el tiempo laborado, que pueden responder tanto a disposiciones legales como a políticas particulares de empresa. Un grupo de contribuciones vacacionales define un régimen vacacional en el mismo sentido en que un grupo de conceptos define una nómina o planilla.', 'Contribución Vacacional', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:35:46.846Z'::timestamptz),
  ('f5758307-f729-434e-91e5-dc43078f083a'::uuid, 'Control bancario', 'Módulo del ERP que permite registrar, controlar y conciliar las transacciones realizadas en las cuentas bancarias de la compañía.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f2c756e9-b874-42d6-8c46-031770b8675f'::uuid, 'Control de calidad', 'Punto de control obligatorio que debe aprobarse antes de que el dato pase a la siguiente etapa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('93bdb177-e62d-42d3-940f-286e686ae424'::uuid, 'Control de calidad de todo el grupo (GWQC)', 'Un sistema de interacción continua entre todos los elementos, incluidos los proveedores, responsables de lograr la mejora continua de la calidad de los productos y servicios que satisfacen la demanda de los clientes.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4026eda0-a294-40a8-bfb6-483c1dee1099'::uuid, 'Control de calidad no estadístico', 'La mayor parte del control de calidad no es estadística, en particular la parte relacionada con los recursos humanos. Sus elementos son la autodisciplina, la moral, la comunicación, las relaciones humanas y la estandarización.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e01a16ac-bd20-4758-be74-2d8940e536ee'::uuid, 'Control de cambios del documento', ' Espacio donde se registra la historia de los cambios realizados a un documento, detallando fechas, revisiones y cambios realizados. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('eb1b8021-aa99-40f8-b41f-69ed1bace4c6'::uuid, 'Control de localizaciones', 'Establece si el sistema considerará la ubicación de los artículos en distintas localizaciones dentro de una misma bodega.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a0f9be39-5579-4d4c-8169-e7110e5c37ed'::uuid, 'Control de lotes', 'Se basa en el registro y seguimiento de las fechas de entrada, cuarentena, salida de inventario y vencimiento de los mismos. Permite la restricción de transacciones de artículos de un lote específico que no cumplan los requerimientos establecidos. Se establece desde la definición de compañías en el módulo de Administración del Sistema.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ecf3d1db-fe84-4af7-a79f-20e490f20a6e'::uuid, 'Control de misión (control obeya)', 'La palabra japonesa Obeya significa “gran sala visual”, también conocida como Sala de Control de Misión: Son espacios donde se realiza la gestión de proyectos (Mejora Continua).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2024f4b3-e234-4ad7-a6d8-cf4e28a14e00'::uuid, 'Control de números de serie', 'Si está configurado, los números de serie de los artículos que ingresan serán registrados y se contará con funcionalidad de consulta y reporte de existencias con detalle por números de serie.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('355f6560-e2b5-47b3-90f0-68b0034ca979'::uuid, 'Control de recibo de materiales (CRM)', 'Es un consecutivo que se asigna a los documentos de embarque cuando se aplican al inventario para establecer el orden en que los artículos y sus correspondientes lotes ingresan al mismo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ca94e7f4-96c1-44f4-8010-a4e346db6efd'::uuid, 'Control de variabilidad', 'Un concepto KAIZEN™ que a menudo se llama Pregunta por qué cinco veces porque busca a través de preguntas curiosas llegar a la causa raíz de un problema para que el problema pueda eliminarse de una vez por todas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fd3df67a-afc5-4ee5-9f6b-0673ed26bcff'::uuid, 'Control estadístico de calidad (SQC)', 'El uso de herramientas estadísticas (diagramas de Pareto, histogramas, diagramas de causa y efecto, etc.) para asegurar que las máquinas están dentro de tolerancias aceptables, o para solucionar problemas de calidad mediante el uso de herramientas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b0608711-832b-4136-9926-1664648eafda'::uuid, 'Conversión', 'Determina si la conversión de moneda debe hacerse de moneda funcional a dólares, de dólares a local o no debe hacerse. ​ Debe tenerse en cuenta que esto es para la versión del sistema con FASB-52.', 'Conversión', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:50:13.052Z'::timestamptz),
  ('f1fff8b7-81c8-42c2-a0c2-bbb63b3c7bf5'::uuid, 'Corrida BDF', 'Proceso automatizado que se ejecuta para realizar la clasificación de artículos de acuerdo a los criterios establecidos por la compañía.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f4bc020f-47da-4882-8dfd-76a2dc01ad52'::uuid, 'Costeo estándar', 'El costo estándar se refiere al costo que define arbitrariamente el usuario del sistema. Este costo deberá actualizarse periódicamente y de manera manual.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d235eeb7-1583-4219-9655-0beaf8be8e54'::uuid, 'Costeo PEPS', 'Método que supone para los propósitos de costeo que las unidades adquiridas de último se encuentran todavía en inventario. Los costos iniciales se consideran como los costos de las mercaderías vendidas. En otras palabras, supone que los artículos que ingresan al inventario de primero son los que salen de primero del inventario.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5d0244cf-913a-4c85-b5cd-1ffc7e0ce587'::uuid, 'Costeo promedio', 'Este método supone que todos los artículos disponibles para la venta durante un período están mejor representados por un promedio ponderado', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('976003fe-736b-4507-acbc-7a0f0f31a988'::uuid, 'Costeo UEPS', 'Método que supone que las unidades adquiridas primero son las que se mantienen en inventario. Así, los costos de inventario, más recientes o últimos, se consideran los costos de las mercaderías vendidas. La intención es correlacionar los costos más recientes con las ventas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9c20735f-ee7e-463d-b36b-869290a8aad2'::uuid, 'Costo', 'Es el valor de adquisición de un artículo, que incluye todos los costos asociados imputables al mismo.', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:50:22.017Z'::timestamptz),
  ('b17781fb-cfe5-4eb1-b101-62195c2e5178'::uuid, 'Costo (plan semestral)', 'Corresponde al costo directo de adquisición de la mercancía que se ha presupuestado vender durante el semestre.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7dde307a-6882-47d7-8f30-c27f0d1817a9'::uuid, 'Costo comparativo', 'Tipo de costo utilizado para realizar estudios comparativos.', 'Costo Comparativo', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:35:56.998Z'::timestamptz),
  ('53a2eb25-c882-4aa3-9e0f-f32e35942fc7'::uuid, 'Costo de venta', 'Costo del articulo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e39b995d-285c-445c-b64e-f11a2cfdfe8b'::uuid, 'Costo de ventas', 'Cuenta y centro de costo en el cual se asignarán los rubros asociados con los costos incurridos al vender los artículos de inventario.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('133e4395-58f4-47b5-9ce9-cd6f06c076b2'::uuid, 'Costo fiscal', 'Tipo de costo para reportes fiscales.', 'Costo Fiscal', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:36:03.605Z'::timestamptz),
  ('36354a95-28a0-4189-9a22-50a936a0ae06'::uuid, 'Costo para el cálculo del precio de venta', 'El costo utilizado para determinar el precio de venta, que se actualiza en la lista de precios base. Los parámetros para este cálculo pueden ser el último costo, el costo del producto o el costo del mercado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6f2f49ef-c124-4cf2-89dc-25a9236aeb0f'::uuid, 'Costo Producto', 'Hace referencia al costo de adquisición de la mercancía.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7b5dd10b-a062-4a38-9515-2bce4124176a'::uuid, 'Costos por omisión', 'Métodos de costeo que se definen por omisión para cada artículo para medir el rendimiento de la empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e1b3d41c-2d75-497a-8534-fd57328e3d19'::uuid, 'Cotización', 'Un documento que se puede generar para un cliente y que no representa un compromiso de compra, se puede convertir en un pedido', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('54ed1074-b921-4d12-ad95-15d3ce274024'::uuid, 'CPT', '(Carriage Paid To - Transporte pagado hasta (lugar de destino convenido)). El vendedor se hace cargo de todos los costos, incluido el transporte principal, hasta que la mercancía llegue al punto convenido en el país de destino. Sin embargo, el riesgo se transfiere al comprador en el momento de la entrega de la mercancía al transportista dentro del país de origen. Si se utilizan varios transportistas para llegar a destino, el riesgo se transmite cuando la mercancía se haya entregado al primero .', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c38af7b3-cd0f-4616-805f-18e34ff1fe1f'::uuid, 'Creación', 'Etapa inicial del ciclo de vida documental donde se redacta el contenido.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d937d1eb-72b1-4715-9bb7-3e32cc63da0e'::uuid, 'CREE', 'Tipo de impuesto utilizado en Colombia.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('33a985f1-dd16-4c84-af75-bd3a3b0f086c'::uuid, 'Cross Docking', 'Eprac: Corresponde al flujo directo de mercancía a través de una instalación, de muelle de recepción al muelle de expedición, eliminando la necesidad de almacenamiento y alisto. Silo Logística: Transferencia directa de mercancías de un transporte a otro, sin almacenar en el almacén.', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('bdc5f517-6576-48c9-83e6-86472237bc3e'::uuid, 'Crédito', 'Es definido también como Haber . Mercancías o beneficios entregados en una transacción u operación, un asiento (o entrada) o pase de asientos a los libros de contabilidad, que registra la eliminación o disminución de una partida de activo o de un gasto, o la creación o aumento de un pasivo, de una cuenta de valuación, de una partida de capital neto (o contable) o de ingresos o productos. Es un asiento en el lado derecho de una cuenta, representa la cantidad así registrada.', 'Crédito', NULL, NULL, false, NULL, false, false, NULL, '2026-10-03T10:43:31.660Z'::timestamptz),
  ('bd8aca7f-665a-43e8-909e-82db8e4aac43'::uuid, 'CTA (call to action)', 'es una instrucción o un mensaje diseñado para provocar una respuesta inmediata en el público. Su propósito es guiar al usuario para que realice una acción específica y deseada, que generalmente se alinea con los objetivos del negocio.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('bf257244-c945-414c-98b5-4d5b8157e7c9'::uuid, 'Cuadricula', 'es una estructura de líneas horizontales y verticales que se utiliza como guía para organizar los elementos de una composición. Funciona como una herramienta invisible que ayuda a los diseñadores a alinear, distribuir y equilibrar el texto, las imágenes y otros elementos visuales de manera coherente y ordenada.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('462c0879-e6ab-4ed0-8e31-0db2e60c26e3'::uuid, 'Cuarentena', 'Período de tiempo en que el artículo debe permanecer en la bodega sin poder ser utilizado para participar en alguna transacción de inventario. La cuarentena se utiliza para aquellos artículos que requieren adquirir alguna característica después de finalizada su producción, y que sin ésta no pueden definirse como disponibles en el inventario. Generalmente se aplica sobre artículos de tipo perecederos, sin embargo puede generalizarse a cualquier artículo, si así se requiere.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('46b31ab9-da76-477a-a5eb-b150802e7bf3'::uuid, 'Cuello de botella', ' Se refiere a aquellas operaciones que se ejecutan que fluyen a un ritmo constante hasta que se presenta algún obstáculo que ralentiza todo o parte del proceso. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('862dc68e-cacb-4638-b856-e6306b2a6bd6'::uuid, 'Cuenta 133', 'Denominación interna para la cuenta contable de "Fondos por depositar", donde se registra temporalmente el efectivo recaudado por la fuerza de ventas antes de ser depositado en el banco.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d60645c0-90b1-486a-80b8-60ac9cf94877'::uuid, 'Cuenta activa', 'Cuenta bancaria que tiene frecuentes movimientos de entrada y salida de dinero.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f3e0961e-aadd-4be1-882b-34341aca2e61'::uuid, 'Cuenta bancaria', 'Representa el código de identificación asignado por una entidad financiera a una persona, empresa o entidad jurídica bajo el cual se registran todas las transacciones bancarias de una empresa, expresadas en forma de cargos y abonos.', 'Cuenta Bancaria', NULL, NULL, false, NULL, false, false, NULL, '2026-10-03T10:42:46.945Z'::timestamptz),
  ('e6d6c25a-ad48-459e-ab2f-2a5dd81365c3'::uuid, 'Cuenta bloqueada', 'Indica si la cuenta acepta o no movimientos contables. ​', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6f3df057-63d5-4fbb-890a-117be5f2ded4'::uuid, 'Cuenta contable', 'Unidad básica de registro que clasifica y agrupa transacciones de la misma naturaleza (ej. "Efectivo", "Ventas", "Cuentas por Pagar"). Su correcta asignación es fundamental para la integridad de la información financiera.', 'Cuenta Contable', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:41:28.032Z'::timestamptz),
  ('605759ec-39fe-433f-8d95-91927a559ddf'::uuid, 'Cuenta de anticipos de clientes', 'La cuenta de Anticipos de Clientes representa los anticipos (adelantos de dinero) realizados por los clientes de la empresa para la compra de bienes, por ejemplo materias primas, o servicios. Por lo tanto, corresponde a un Pasivo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('74d0f881-372f-4387-bc53-7dd2986aa52a'::uuid, 'Cuenta de clientes', 'En la cuenta de Clientes se registran las ventas a crédito, que la compañía realiza a sus clientes. Por lo tanto, corresponde a un Activo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c6a2c8d2-c803-4903-8679-93f05c4534e7'::uuid, 'Cuenta de gasto', 'Cuenta contable que registra los desembolsos necesarios para mantener las operaciones de la empresa, como salarios, alquileres o servicios.', 'Cuenta Gasto', NULL, NULL, false, NULL, false, false, NULL, '2026-10-03T10:43:33.198Z'::timestamptz),
  ('5236dfee-a646-43b0-8bcc-5664e5c6b012'::uuid, 'Cuenta de ingreso', 'Cuenta contable que registra los ingresos generados por la actividad principal de la empresa, como la venta de bienes o servicios.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('27f4e7a0-f6dd-469c-ac58-2f9a1287e624'::uuid, 'Cuenta de orden', 'Cuenta contable que se utiliza temporalmente para cargar los montos debidos a una transacción contable, que posteriormente se ubicarán en las cuentas contables que corresponden.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('835209c9-22d5-4a3a-aadf-8b652ff67a50'::uuid, 'Cuenta inactiva', 'Cuenta con escaso o nulo movimiento. El saldo puede ser siempre el mismo, debido a que no se han efectuado depósitos ni retiros de la cuenta durante un periodo prolongado de tiempo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('22ae1a63-d8ec-40d4-8f71-9c2d5bbee91d'::uuid, 'Cuenta padre', 'Cuenta de primer nivel, que contiene una serie de subcuentas específicas donde se detallan los cambios en un activo o pasivo particular, se expresa según su número de cuenta al tener los niveles inferiores en cero.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('35e93f64-8590-4225-bed0-0fd6d7e972af'::uuid, 'Cuentas', 'Campo en la ventana de artículo donde se indica el tipo de cuenta contable.', 'Cuentas', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('971dac8b-8470-42a0-ac8e-8f90a0c86a40'::uuid, 'Cuentas contables', 'Las cuentas contables se utilizan para definir los rubros que son involucrados en una transacción. ​ El sistema permite la definición del patrón de cuentas contables según las necesidades de la empresa. ​ Las cuentas están definidas y agrupadas según su código bajo una cuenta padre que englobará las subcuentas hasta llegar a los movimientos propios de cada una. ​', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('09b5e32d-2d1b-4da0-a9d9-0143dff54bc5'::uuid, 'Cuentas contables (de artículos)', 'Opciones donde se definen las cuentas contables que serán asociadas a cada artículo en el inventario. Estas permiten realizar los asientos contables e integrar los movimientos de Control de Inventario con el módulo de Contabilidad General. Incluyen cuentas de inventario, variación de costo, faltante en inventario físico, sobrante en inventario físico y vencimiento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('dc6d69af-9a09-4be2-b81c-e17a7c8dbc94'::uuid, 'Cuentas por cobrar', 'Un Abono, Crédito o Haber representa una disminución en una cuenta de activo o un aumento en una cuenta de pasivo o de capital.', 'Cuenta Cuentas por Cobrar', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:41:32.214Z'::timestamptz),
  ('d5157c64-ba43-4814-8c6b-8a2944308847'::uuid, 'Cuentas por Pagar', 'Suma total de las deudas de la empresa con sus proveedores.', 'Cuenta Cuentas por Pagar', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:41:33.540Z'::timestamptz),
  ('5cda38cb-b0fe-4960-bf63-7da9a0ced869'::uuid, 'Cuentas por Pagar (CP)', 'Área y módulo del ERP responsables de gestionar todas las obligaciones de pago de la empresa con sus proveedores y acreedores.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9b274939-d392-4fbc-8878-94fec95b8b9e'::uuid, 'Cuentas por Pagar Vencida', 'Suma total de las deudas a proveedores que ya han excedido su fecha de vencimiento', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('34a88758-5698-4039-98f4-23b87ab87848'::uuid, 'Cultura kaizen', 'Una cultura organizacional basada en tres principios: Proceso y Resultados, Pensamiento Sistémico y Sin Juicios ni Culpabilización.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('87496a44-e516-468c-89ff-61c11af5e955'::uuid, 'Cultura organizacional', 'Conjunto de valores, creencias, comportamientos y normas compartidos que caracterizan a la empresa y guían la forma de trabajar de sus miembros.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0dbe7b2d-e08b-4963-aa57-c2f9ebdd8bdf'::uuid, 'Cump ppto venta %', 'El porcentaje que representa la venta neta real en relación con la meta de ventas establecida.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5656db19-0b32-436f-baf7-0444c551a3c4'::uuid, 'Cumplimiento', 'Se refiere a la responsabilidad de roles como el Gerente de Compras, Gerencia de Ventas y Especialista Comercial de Compras de asegurar que se cumplan los requisitos para la inclusión de nuevos productos y proveedores. También implica garantizar que los nuevos productos y proveedores se alineen con la estrategia comercial y las necesidades del mercado, y supervisar el balance del surtido y la operación sostenible de la empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('30d3c72f-bda2-4a51-991b-4b6c4383c3f7'::uuid, 'Cuota fija', 'Tipo de condición de pago en el que todas las cuotas son por el mismo monto, pero el monto que se amortiza al principal y los intereses que se calculan para cada cuota varían.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ac4b7888-0097-4c41-b069-a2b7080bb6a2'::uuid, 'Curvas', 'es una herramienta visual que permite a las empresas entender el comportamiento del consumidor, la vida de sus productos y cómo deben adaptar sus estrategias para tener éxito.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d5f87625-e16c-48bd-872d-3e7cbd2b5105'::uuid, 'Custodio del dato', 'Rol responsable de asegurar la calidad, estandarización y cumplimiento de las normas definidas por el dueño del dato.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7e778586-c998-454b-8d13-df5ebfa34842'::uuid, 'Custodio técnico', 'Rol técnico responsable del almacenamiento, seguridad, transporte y disponibilidad del dato en los sistemas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('cc5c217e-72fe-4bf0-9377-9290487c98df'::uuid, 'Customer journey', 'Es el camino completo que recorre una persona desde que tiene su primer contacto con tu marca hasta que se convierte en un cliente fiel. Es una representación del proceso de compra, desde el descubrimiento inicial de la necesidad o del producto hasta la compra y la post-compra.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ab1115fd-0473-4a60-81f5-21fc7bdee866'::uuid, 'Cálculo vacacional', 'Proceso completo periódico de actualización de la cantidad de días de vacaciones pendientes de goce de los empleados de una organización, que inicia con el establecimiento de los parámetros generales de configuración, hasta la aplicación en firme del nuevo cálculo de días acumulados de vacaciones de los empleados. Un cálculo vacacional está conformado por información general que define los parámetros y condiciones del cálculo así como por información detallada por empleado con los resultados particulares obtenidos.', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:36:31.936Z'::timestamptz),
  ('b68235a5-b85d-437a-b219-6522feb9132d'::uuid, 'Código arancelario', 'Un código específico de producto que se encuentra en el Sistema Armonizado (SA), mantenido por la Organización Mundial de Aduanas (OMA). Este código se utiliza para calcular impuestos y asegura una clasificación uniforme de los productos en todo el mundo. Su longitud puede variar de 8 a 12 dígitos, y cuantos más dígitos tenga, más específico es el producto.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a0a8426e-68d0-4ea8-aa47-f4a4dfcbb616'::uuid, 'Código Cabys', 'Catálogo de Bienes y Servicios. Es un sistema obligatorio en Costa Rica, creado por el BCCR y el Ministerio de Hacienda, que asigna un código numérico único de hasta 13 dígitos a cada producto o servicio comercializado, para estandarizar su clasificación en facturas electrónicas y mejorar el control fiscal, la generación de estadísticas y la identificación de impuestos diferenciados. ', 'Código Cabys', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('cc88857b-05ee-4333-8514-838320775f60'::uuid, 'Código de artículo', 'Identificador único asignado a cada producto dentro del sistema.', 'Código', NULL, NULL, false, NULL, false, false, NULL, '2026-09-30T19:30:00.000Z'::timestamptz),
  ('3b052d4d-96c6-4b18-87aa-16a203a6103f'::uuid, 'Código de barra', 'Un identificador numérico o alfanumérico que permite identificar un artículo para el control de inventario, punto de venta y seguimiento en la cadena de suministro.', 'Código barras', NULL, NULL, false, NULL, false, false, NULL, '2026-10-03T10:43:35.847Z'::timestamptz),
  ('bb8f6d12-4f68-4335-a7dd-c111f4baad28'::uuid, 'Código de barras unidad almacen', 'En este campo se ingresa el código de barras utilizado para el almacenamiento.', 'Código de barras unidad de almacen', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T14:07:00.000Z'::timestamptz),
  ('8b0d67eb-c048-4412-be6c-87b3f57a0e89'::uuid, 'Código de barras unidad detalle', 'En este campo se ingresa el código de barras utilizado para la venta.', 'Código de barras unidad de detalles', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T14:07:00.000Z'::timestamptz),
  ('8d3e85b7-3149-4c8b-8f0c-669420e6bff8'::uuid, 'Código de cliente', 'Identificador numérico único asignado a cada cliente en el sistema para garantizar la correcta imputación de transacciones y seguimiento.', 'Código del cliente', NULL, NULL, false, NULL, false, false, NULL, '2026-09-30T20:00:00.000Z'::timestamptz),
  ('bb1e3383-e848-4dfb-89ba-5e099b43a263'::uuid, 'Código de cuenta', 'Patrón de números que identifica cuenta contable. El formato de la cuenta se establece en la opción de Administración en el menú principal. ​ Al crear una cuenta se debe considerar que los niveles superiores del patrón deben definirse antes que los menores. ​', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('968e71bc-13de-45ba-9dbc-438bc52c2110'::uuid, 'Código de documento', 'Identificador único que permite rastrear y controlar un documento.', 'Código Documento', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:41:37.050Z'::timestamptz),
  ('a6e95ec5-23e6-48b6-afae-52190c043859'::uuid, 'Código de paquete', 'Identifica el paquete por medio de una secuencia de caracteres única definida por el usuario. ​ Este código no puede ser cambiado. ​', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7bfbc5cf-4bbd-4bc9-b39a-1236ac629940'::uuid, 'Código de proveedor', 'Identificador numérico único asignado a cada proveedor en el sistema para una correcta gestión de las cuentas por pagar y el historial de compras.', 'Código Proveedor', NULL, NULL, false, NULL, false, false, NULL, '2026-09-30T19:30:00.000Z'::timestamptz),
  ('9ed439d3-0d03-40ef-958e-bd84eddda054'::uuid, 'Código lester', 'Número de referencia automotriz de un componente eléctrico', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f58a1fba-6b4b-4e99-9390-0181ca7ac57b'::uuid, 'Código M', 'Lenguaje de programación que se usa dentro de Power Query para definir transformaciones de datos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2b759da7-f87b-4cda-8d20-15d739e44f5b'::uuid, 'Código OEM', 'Es el código asignado por el fabricante a un componente que forma parte de un vehículo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fb2a3361-e143-4f6c-ac25-931c77dc9727'::uuid, 'Códigos', 'Son los artículos que se encuentran dentro de las subcategorías. Cada subcategoría debe contener un rango de 10 a 30 códigos y vender al menos $1,000 al mes.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('bba202e3-b0ee-4fef-8def-d64f73014f59'::uuid, 'D.E.P.', 'Abreviatura de "Depósito". Transacción financiera que consiste en la entrega de efectivo o cheques a una entidad bancaria para abonar a una cuenta.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('60727b9b-2dd2-45ce-b5e4-24ef68316e73'::uuid, 'Dantotsu', 'El concepto de Benchmarking se basa en la palabra japonesa Dantotsu que significa lo mejor de lo mejor.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('63cedff9-3000-465f-bf3f-76b39fba8dd0'::uuid, 'DAP', '(Delivered At Place - Entregado en un punto (lugar de destino convenido)). El vendedor se hace cargo de todos los costos, incluidos el transporte principal y el seguro (que no es obligatorio), pero no de los costos asociados a la importación, hasta que la mercancía se ponga a disposición del comprador en un vehículo listo para ser descargado. También asume los riesgos hasta ese momento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b02f6d0b-5952-4f01-b2e2-d3c6d26192ae'::uuid, 'Dashboard', 'Panel visual interactivo que muestra indicadores clave (KPIs), gráficos y métricas en un solo lugar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('114a8191-e796-4e32-b7d1-050e32d626a2'::uuid, 'DAT', '(Delivered At Terminal - Entregado en terminal (puerto de destino convenido)). El vendedor se hace cargo de todos los costos, incluidos el transporte principal y el seguro (que no es obligatorio), hasta que la mercancía es descargada en la terminal convenida. También asume los riesgos hasta ese momento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('debab99f-9abd-46a7-90c8-848575d80f14'::uuid, 'Data mining (minería de datos)', 'Proceso de encontrar patrones o tendencias en grandes volúmenes de datos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fb404425-9f5b-4d1a-98de-b3fcfe886e9d'::uuid, 'Dato', 'Elemento básico de información, por ejemplo: “23”, “Ana”, “CR”.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a518ba93-e044-430b-8a3a-6c8699a1a361'::uuid, 'Dato dummy', 'Registro maestro genérico y temporal en el ERP utilizado como comodín para procesar transacciones, presupuestos o pruebas cuando el dato real definitivo aún no está identificado o disponible.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('bfd3ae97-aa4b-4e0b-83b2-5b057b36e8ec'::uuid, 'Dato maestro de artículo', 'Registro único que representa un producto, conteniendo sus atributos esenciales de identificación, logística, comercial y financiera.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('65f7df2c-9d44-4e67-a5dd-9042deacf1d4'::uuid, 'Dato nulo', 'Dato que indica ausencia de valor o información desconocida en un campo. Técnicamente, un valor nulo no equivale a cero (0), sino a la inexistencia de registro para dicho atributo. Este a diferencia de 0 no impacta en cálculos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e2e1d54a-5e08-488b-8529-1afc7202f867'::uuid, 'DAX (data analysis expressions)', 'Lenguaje usado en Power BI para crear medidas y cálculos avanzados.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('761955ec-8af4-4ffb-9dfe-ee8b86b2c317'::uuid, 'DDP', '(Delivered Duty Paid - Entregado con derechos pagados (lugar de destino convenido)). El vendedor paga todos los gastos hasta dejar la mercancía en el punto convenido en el país de destino. El comprador no realiza ningún tipo de trámite. Los gastos de aduana de importación son asumidos por el vendedor.', '', NULL, NULL, false, NULL, false, false, NULL, NULL)
ON CONFLICT DO NOTHING;

INSERT INTO terminos (id, termino, definicion, campo_softland, estado_origen, nota_origen, revisado, nota_decision, es_nuevo, editado, eliminado_en, actualizado_en) VALUES
  ('75f88e1b-531f-4ecd-8424-f1c5fe55c4a1'::uuid, 'Debito', 'Es definido también como Deber. Mercancías o beneficios recibidos de una transacción u operación; un asiento (o entrada) o pase de asientos a los libros de contabilidad, que registra la creación o el aumento de una partida de activo o de un gasto, o la reducción o eliminación de una partida de pasivo, de una cuenta de valuación (crédito) o de una partida de capital neto (o contable) o de ingresos (o productos).', 'Débito', NULL, NULL, false, NULL, false, false, NULL, '2026-10-03T10:44:12.909Z'::timestamptz),
  ('57b8b668-f908-466b-af54-1e86c3f560f7'::uuid, 'Declaración fiscal', 'Documento oficial presentado ante la autoridad tributaria donde se reportan los ingresos y gastos para calcular los impuestos a pagar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e7700a11-52c5-43d7-9287-0e675e2538d4'::uuid, 'Deducción', 'Es una disminución que se realiza al salario del empleado. Es un flujo negativo del salario de un empleado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c9fc606a-da62-4019-8c89-5fbbf977ca4c'::uuid, 'Deep learning (aprendizaje profundo)', 'Forma avanzada de aprendizaje automático que usa redes neuronales para reconocer patrones complejos (ej. reconocer rostros en fotos).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('066c5e98-90ad-41a9-aa93-332b3648af95'::uuid, 'Default', 'Concepto que define la asignación de un valor por defecto o rebote.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b2a30de1-7207-469e-99dc-abaadd43919c'::uuid, 'Defecto de fábrica', 'Una imperfección en el producto que puede ser motivo de devolución, siempre y cuando esté cubierto por la política de garantía del proveedor.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5bbd0de8-cf4a-487e-99a3-4fc127b4292e'::uuid, 'Demanda (legal)', 'Reclamo o petición formal presentada ante un tribunal para iniciar un proceso judicial.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('59a49b15-f234-491f-8349-493ae498b8fc'::uuid, 'Departamento', 'Softland: Unidad funcional de la empresa, en la cual se agrupan las actividades que son semejantes y están relacionadas lógicamente entre sí. El departamento representa la estructura formal de la organización tal como aparecería en un organigrama. Reporte SIM – Dimensión Personal: Muestra las sub divisiones que existen dentreo de las areas de la compañia.', 'Departamento', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-10-02T01:36:44.548Z'::timestamptz),
  ('d4ade745-ca07-4e69-8a5a-45bf37868fd4'::uuid, 'Departamento de control', 'Departamento con la misión de articular el crecimiento rentable del negocio a través de la inteligencia financiera, una cultura de eficiencia y un sólido ambiente de control.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('66db2076-eb9b-45d7-b230-4a6aa148eed3'::uuid, 'Deposito', 'Se refiere a una transacción que permite al cliente pagar documentos pendientes por medio de un depósito del monto parcial o total del documento a una cuenta bancaria de la compañía. Este pago se debe realizar directamente, es decir, el cliente debe realizar un depósito en la entidad bancaria donde la empresa tiene su cuenta. En este caso no es preciso que el cliente tenga cuentas bancarias en la misma entidad.', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-03T10:44:26.959Z'::timestamptz),
  ('59f44e56-9e9a-4117-b1b2-251221005813'::uuid, 'Depreciación', 'Gasto contable que distribuye el costo de un activo tangible (ej. vehículo, maquinaria) a lo largo de su vida útil, para reflejar su desgaste o pérdida de valor.', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-03T10:44:29.391Z'::timestamptz),
  ('2901df4f-ee6d-4718-97e0-eb24b3c4383c'::uuid, 'Depuración de surtido', 'Proceso que consiste en identificar, evaluar y eliminar productos de un catálogo que ya no son rentables, relevantes o que no se ajustan a la estrategia comercial.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c8209fc3-250b-4d29-a7f9-1dbd80b21768'::uuid, 'Derecho de retracto', 'El cliente puede cancelar el pedido previo a la entrega y tiene derecho al retracto de pedido bajo las restricciones indicadas en la presente norma.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0878e7eb-d429-450f-b086-b131057ff6c9'::uuid, 'Descripciones de cargo', 'Documento que detalla funciones, responsabilidades y requisitos de cada puesto en la empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('288b6d35-b029-4286-b7b8-6f551ae22360'::uuid, 'Descripción de cargo', 'Documento formal que detalla las funciones, responsabilidades, objetivos, competencias requeridas y relaciones jerárquicas de un cargo específico.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9dc7b33d-dd2c-42ed-b0ca-f63e2cb240b2'::uuid, 'Descripción de cuenta', 'Patrón de caracteres alfanuméricos que distinguen de una manera menos determinante la cuenta. ​ Por así decirlo, es el nombre de la cuenta.', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-03T10:44:34.356Z'::timestamptz),
  ('8914816b-4626-4599-877f-98ca1af1f052'::uuid, 'Descripción del artículo', 'El nombre comercial del artículo, seguido de sus atributos más importantes y finalizando con la marca comercial.', 'Descripción', NULL, NULL, false, NULL, false, false, NULL, '2026-09-28T00:00:00.000Z'::timestamptz),
  ('aaafac17-d36f-43a6-b714-761900be9270'::uuid, 'Descuento', 'Es un valor porcentual que disminuye el precio de venta de un producto.', 'Descuento', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('11fc47a9-1e3c-4662-8385-3d03cb1ec7e4'::uuid, 'Descuento en línea', 'Porcentaje que se rebaja al comprador por cada línea de pedido, en una orden de compra. El porcentaje del descuento en línea podría ser diferente para cada artículo solicitado.', 'Descuento por Línea', NULL, NULL, false, NULL, false, false, NULL, '2026-10-03T10:44:39.491Z'::timestamptz),
  ('162fe414-c107-43ab-885b-84ca3e97dc49'::uuid, 'Descuento por forma de pago', 'Reducción de precio concedida al cliente en función del método de pago utilizado, incluso si no liquida la totalidad de la deuda.', 'Descuentos Forma de Pago', NULL, NULL, false, NULL, false, false, NULL, '2026-09-30T19:30:00.000Z'::timestamptz),
  ('08a9a1ab-f0b0-45b2-ac66-fdf8201610da'::uuid, 'Descuento por pronto pago', 'Incentivo ofrecido a los clientes por pagar una factura antes de la fecha de vencimiento establecida.', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-03T10:44:41.514Z'::timestamptz),
  ('1a5dcb7f-befc-438d-ba7a-c0ec8b56b4b8'::uuid, 'Deserción', 'Es un métrica de personal que mide el porcentaje de colaboradores que abandonan una organización durante un período de tiempo determinado (mes, trimestre, año).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('317b035d-d9b8-4321-bc8c-1d3b8fbab970'::uuid, 'Deserción %', 'Es un métrica de personal que mide el porcentaje de colaboradores que abandonan una organización durante un período de tiempo determinado (mes, trimestre, año).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b211eb53-647e-4878-b400-197a85c1c4e0'::uuid, 'Despacho directo', 'Se modifica una expedición con este tipo de carga y la carga se realiza directamente desde el desktop, sin usar la RF.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('76ca5da9-aba5-4cfa-a754-691f8804bc6c'::uuid, 'Despacho múltiple', 'El operario usa la RF para leer el código de barras del total de artículos de cada bulto a despachar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('047b171d-3c49-4e6d-ba08-23dcac7c1cc5'::uuid, 'Despacho por palet', 'Se realiza mediante la RF, cargando por palet completo asumiendo que se cargó todo el pedido.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5eb8ce30-1e0c-449d-9590-0f9326474ff2'::uuid, 'Despacho único', 'El operario debe de hacer uso de la RF, este tipo de despacho consiste en leer el código de barras de cada bulto e indicar la cantidad que se va a despachar', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5ba1a453-95ed-4981-bcb8-0dbe7a325995'::uuid, 'Despido', 'Terminación de la relación laboral por iniciativa del empleador. Puede ser con o sin justa causa (improcedente), lo que afecta directamente al pago de indemnizaciones y prestaciones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8988aa0b-14cb-4955-96ca-1cfb9a37244f'::uuid, 'Despliegue de la función de calidad', 'Un sistema mediante el cual los requisitos del cliente, conocidos como características de calidad reales, se traducen en características de diseño, conocidas como características de contraparte, y luego se implementan en subsistemas como componentes, piezas y procesos de producción para desarrollar nuevos productos diseñados con precisión para satisfacer las necesidades del cliente. QFD es uno de los siete sistemas KAIZEN™.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d7f83fa7-69c6-4a75-b2b0-dc12e25df4ec'::uuid, 'Destino', 'Conjunto de criterios que determinan a qué clientes y por qué canales se ofrecerá la promoción. Define el "a quién" y el "dónde" de la oferta comercial.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d40f99fa-931b-4a4f-bf07-c56a3bdb0267'::uuid, 'Detalle de recepción', 'Indica los artículos que conforman la orden, sus lotes, cantidades y bodegas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('addeb14e-2ba6-42c2-ac05-9a3f4cbb1b48'::uuid, 'Detalles (en picking RF)', 'Permite consultar los detalles del picking.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('55c18305-456e-4170-afc5-559f129717c5'::uuid, 'Deuda', 'Obligación financiera que una parte tiene con otra, que debe ser liquidada en un plazo acordado, generalmente con intereses.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1195ac80-39fd-41c1-8311-170a69b12bea'::uuid, 'Devolución', 'Silo Ventas: proceso en el que un cliente devuelve un producto a un vendedor o empresa. Esto puede suceder por varias razones, como que el producto esté defectuoso, sea del tamaño o color incorrecto, o simplemente no cumpla con las expectativas del cliente. Reporte SIM – Indicador Venta: Suma de la venta multiplicando por -1, se aplica para todos los documentos con estado “D”.', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-10-03T10:44:57.246Z'::timestamptz),
  ('1cc466a1-9c72-42f0-bc69-16a0385799b6'::uuid, 'Devolución %', 'Silo Control: Métrica que mide el porcentaje de productos devueltos en relación con el total de ventas. Se calcula como (Valor de Devoluciones / Ventas Totales) x 100. Es un indicador de la calidad del producto y la satisfacción del cliente. Reporte SIM – Indicador Venta: El porcentaje de productos vendidos que son devueltos por los clientes.', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-10-02T01:36:54.599Z'::timestamptz),
  ('0e0cd126-bb78-4f1f-b9bd-78397c2a3bc9'::uuid, 'Diferencial cambiario', 'Ganancia o pérdida que surge de la fluctuación del tipo de cambio entre la fecha de una transacción en moneda extranjera y la fecha de su liquidación.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('164f0739-2e3b-4929-850f-22bf6613562a'::uuid, 'Dimensiones', 'Las medidas de un artículo en su empaque individual, incluyendo alto, ancho y profundidad.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c3fdbfd2-cbcc-4a4f-8a65-88e2a5068b5d'::uuid, 'Dimensión', 'Es un atributo o una característica que describe y categoriza los datos para su análisis.', 'Dimensión', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('9012680a-f2f8-4c20-8395-b4aa20e7d77d'::uuid, 'Diseño', 'Es el proceso de planificar y crear una solución para un problema, con un propósito específico y para un público determinado. Es un proceso creativo que va más allá de la simple estética; combina arte, funcionalidad, estrategia y empatía.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4b65f25d-b9d8-482c-b9a6-6d6d27dd12f7'::uuid, 'DISP (disponible)', 'Tareas que están disponibles para ser asignadas a un recurso.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9994fd77-c02f-4df9-a2e4-76043b8d3c30'::uuid, 'Disponibilidad para pagos', 'Se refiere al efectivo y equivalentes de efectivo que la empresa puede utilizar de inmediato para cumplir con sus obligaciones a corto plazo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5adc1b08-a57b-4685-a634-b5484ba5946a'::uuid, 'Disponible', 'Dimensión que hace referencia al filtro "Disponible para la venta" en el SIM.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0edf13f6-9c16-4bbb-9792-4170fcb9abf5'::uuid, 'Disponible para la venta (P1)', 'Determina que la mercancía se visualice disponible en los canales de venta.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('962a1e6d-a4de-4fe9-9451-0374976d7ace'::uuid, 'Distribución', ' Lista de Áreas o Roles a los cuales se les distribuye o da acceso al documento. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2f2b18b6-b86a-4f80-bf07-515f79372e79'::uuid, 'Doble cierre', 'Permite llevar la contabilidad fiscal y la corporativa al día. ​', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('cf743f84-7fab-48f5-9000-74ab18ce0fbb'::uuid, 'Documentación mercantil', 'Conjunto de documentos (facturas, notas de crédito, cheques, etc.) que respaldan y formalizan las transacciones comerciales de una empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a2c33f56-078c-477e-80bd-02e299150046'::uuid, 'Documento', 'Se refiere al comprobante físico de una transacción. Existen documentos de débito que son documentos por cobrar, originados a partir de la adquisición de un bien o servicio ofrecido a un cliente. También existen documentos de crédito que se relacionan con las transacciones realizadas para el pago de los bienes o servicios.', 'Código Documento', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:41:50.817Z'::timestamptz),
  ('69552fbd-80fd-4dfa-a552-b78e298ff943'::uuid, 'Documento de conteo', 'Documento que se crea desde eflow-WMS para iniciar el proceso de toma física, indicando el tipo de toma a realizar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('abe54920-a183-4bc1-83c5-7c680318da25'::uuid, 'Documento normativo', 'Texto que establece reglas, políticas o estándares que deben cumplirse.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ee7a0b16-dcf8-44e9-8719-58d28d3c587a'::uuid, 'Documentos de crédito', 'Es definido también como Haber y es el origen de una transacción. Es un asiento contable que registra la reducción o eliminación de una partida de activo o de gastos, o la creación o aumento de un pasivo, o de una partida de capital neto o de ingreso; un asiento en el lado derecho de una cuenta; la cantidad contabilizada como tal.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('14acb9a8-d8c8-458d-bea2-badd357c48c0'::uuid, 'Documentos de deposito', 'Se refiere a una transacción que permite al cliente pagar documentos pendientes por medio de un depósito del monto parcial o total del documento a una cuenta bancaria de la compañía acreedora.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('dc5c6b9d-02ab-470f-b475-102a7ff9b7ec'::uuid, 'Documentos maestros', 'Documentos en formato texto asociados con una fuente de datos que ingresa datos dentro de los campos en el documento. La fuente asocia a la fuente de datos los campos definidos y los reemplaza.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('460653a7-a46f-48ba-b423-02dde715ea09'::uuid, 'Documentos relacionados', ' Lista de Documentos asociados a la tarea. Estos pueden ser otros manuales, instrucciones de trabajo, anexos, etc. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7283b819-28d4-4c0e-8197-f4ac994103c1'::uuid, 'DPI', 'Es una unidad de medida que se utiliza para describir la resolución de una imagen o de un archivo que será impreso.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('552c4845-31fb-49ec-9680-9adbaf53a0f1'::uuid, 'DUA', 'Declaración Única de Aduana.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fd56569d-4464-4f13-8c93-a78bae28a8a4'::uuid, 'Dueño del Dato', 'Rol de negocio con la autoridad final sobre la definición, reglas y políticas del dato.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('bd906c33-8160-4f1a-8baa-89b27ee0963a'::uuid, 'Día frecuencia pedido', 'Es la división del rango de días desde que se realizó el primer pedido hasta el último pedido realizado entre la cantidad de días con pedido.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('15dd0329-b05c-4bef-be03-1264bf3511fa'::uuid, 'Días de CxC', 'Son los días promedio que le toma a la empresa convertir sus ventas a crédito en efectivo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4d774ecf-3b0a-4c52-bf81-8dab919d5704'::uuid, 'Días de falla', 'Días sin disponibilidad de producto, afectando la demanda real observada.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b4c3661b-881a-44b5-af92-16e5c1705f09'::uuid, 'Días de vacaciones', 'Período de descanso remunerado al que tiene derecho el trabajador después de un año de servicios continuos. La cantidad mínima de días está fijada por la ley de cada país.', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-03T10:45:15.784Z'::timestamptz),
  ('59ca3f1a-84ce-440e-80c9-23cc595c06e0'::uuid, 'Días libres contenedor', 'Cantidad de días otorgados sin costo adicional para realizar las gestiones logísticas correspondientes, como retiro del contenedor, almacenamiento o devolución del equipo, según las condiciones establecidas por el operador logístico.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8d1f2e30-cc9e-4a5c-94ec-df3245c9c799'::uuid, 'EAN', 'Código de barras estándar utilizado para identificar artículos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('21fc1afd-7c6e-46c9-8de9-a7d35a121451'::uuid, 'EBITDA', '(Earnings Before Interest, Taxes, Depreciation, and Amortization) Utilidad Antes de Intereses, Impuestos, Depreciación y Amortización. Mide la capacidad de la empresa para generar efectivo a través de sus operaciones principales.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5ee575db-5641-4555-b13b-fa0bb440511e'::uuid, 'EDI', 'Significa intercambio electrónico de datos. Es la transferencia electrónica de información de un negocio a otro, utilizando un formato estándar y predefinido. Básicamente, es una forma de que las computadoras de dos empresas se "hablen" entre sí sin intervención humana, para intercambiar documentos comerciales como órdenes de compra, facturas o avisos de envío.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('06a658bc-c0c0-41e9-8add-cf3e39ce65f0'::uuid, 'Editable', 'cuando se puede modificar, cambiar o personalizar fácilmente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('cab5c2ad-7f79-4e18-bf3f-3f7bd874e1cc'::uuid, 'Eficiencia operativa', 'La capacidad de realizar una tarea en el menor tiempo y con el menor costo posible, minimizando errores y manteniendo la calidad.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('786a250c-36b5-4e11-8386-77250197d429'::uuid, 'Egresados', 'Es un indicador de salida de talento que representa el número total de colaboradores que han salido de la organización, ya sea de forma voluntaria o involuntaria, durante un período específico de tiempo (por ejemplo, un mes, un trimestre o un año).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('daa12537-7406-482e-bbe2-4bb66658872e'::uuid, 'Egresados %', 'Es el indicador principal de retención y estabilidad de una organización. Representa el porcentaje de colaboradores que salieron de la empresa (egresados) en relación con el número total promedio de colaboradores en un período determinado', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9100fbb9-a96c-4c05-8ca3-37385716eb84'::uuid, 'Ejecutor del proceso', 'Persona encargada de realizar las actividades definidas en el proceso.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4906d4ea-bef2-4411-b043-42acbc7024d3'::uuid, 'Elasticidad precio', 'Medida del cambio en la demanda cuando varía el precio.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d1c7b315-69ab-430f-a0a1-c97ada716727'::uuid, 'Embarque', 'Documento que hace constar el recibo de los artículos enviados por el proveedor para satisfacer los requerimientos de una o varias órdenes de compra.', 'Embarque', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:41:53.513Z'::timestamptz),
  ('af48b27c-be30-4c7e-86f7-1fa7bf599805'::uuid, 'Embudo de marketing', 'es una representación visual del viaje que un cliente potencial realiza, desde que descubre una marca hasta que se convierte en un cliente fiel. Su forma de embudo ilustra que, de un gran número de personas que inicialmente entran en contacto con la marca, solo una pequeña fracción se convertirá en clientes.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9cdfc090-1dee-4a32-ad47-d5108824423a'::uuid, 'Empaque', 'La forma de embalaje de un artículo para su venta, que asegura su integridad durante el almacenamiento y el transporte en el proceso de distribución mayorista.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1c4ce8a4-fa58-444c-b742-10d87a329223'::uuid, 'Empaque comercial', 'Unidad mínima de comercialización de un artículo, es múltiplo del Empaque de Inventario, y no necesariamente está relacionado a la cantidad de Piezas o Juegos que están contenidas en el empaque físico, aunque sí están estrechamente ligados. Este define en la empresa la cantidad mínima comercializable de un producto en el mercado de mayoreo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e3b097d5-2e8a-4ea6-98f5-0edc55a446c7'::uuid, 'Empaque de inventario', 'Unidad mínima e indivisible de un producto. Este clasifica si el artículo se considera una pieza, un Juego o un Rollo. Representa la unidad de conteo de inventario, por cuanto el costo y el precio de un artículo se relaciona con esta unidad.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('68c167e2-d50e-4e74-8b5f-fcf9e519eb41'::uuid, 'Empleado', 'Los empleados constituyen el sistema social interno de la empresa. ​ Un empleado es, para el sistema, el registro en el que se almacena la información personal del empleado físico. ​ Este registro se distingue mediante un código único. ', 'Empleado', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:37:02.177Z'::timestamptz),
  ('3724a687-cdb4-4901-a424-3a30ee39f5ff'::uuid, 'Empleado/ colaborador de confianza', 'Trabajador que desempeña funciones de dirección, administración, vigilancia o fiscalización, o cuyas labores sean de naturaleza personalísima. Su régimen horario y de prestaciones puede tener particularidades legales.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6a3a4f63-4dce-4d1b-bba3-d7aa0b69a7f6'::uuid, 'Encabezado / pie de página', 'Áreas del documento que contienen información como fecha, autor, versión, etc.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6f835bff-a1e2-46ab-9e2f-af4fa5d57e49'::uuid, 'Encuesta de satisfacción laboral', 'Herramienta de diagnóstico que mide la percepción de los colaboradores sobre el ambiente de trabajo, la cultura organizacional y las condiciones en la empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d6fe6c9b-635c-43d9-83dd-78f799f84912'::uuid, 'Engagement', 'La interacción y participación que los usuarios tienen con el contenido de una marca, especialmente en redes sociales (me gusta, comentarios, compartidos).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1cd604d3-c3db-4f5c-89d2-3e07a4bc4637'::uuid, 'Engagement (compromiso)', 'Grado de identificación, compromiso y entusiasmo que un empleado tiene hacia su trabajo y la organización.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('77283da6-d5af-4bfd-b0ca-db1f3686c15e'::uuid, 'Entidad comercial', 'Toda entidad jurídica con la cual se pueda realizar una transacción comercial. Para fines de esta Norma, transacción comercial se resume fundamentalmente en venderle mercancía.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('796cc318-2109-4381-93ee-c5548d0b3938'::uuid, 'Entradas', ' Se especifica lo que se requiere para el proceso, la actividad o la tarea se pueda iniciar. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d2151e84-fed4-45c6-a448-81bd73d0b9ee'::uuid, 'Entrega', 'Días en los que el proveedor realiza la entrega de la mercancía.', 'ENTREGA', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('129d3316-cdb8-4caf-8f79-9ce3d29649e6'::uuid, 'Equipo comercial', ' Mesa de trabajo que busca el desarrollo de los proyectos estratégicos de un Área Funcional. Está conformado por el Responsable Comercial, Responsable de Métodos, el Responsable Técnico, y los Usuarios Expertos. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('10ba0b09-2c66-4f0e-8469-77856a2c0277'::uuid, 'Equipo de mercadeo', 'Equipo a disposición de desarrollo y seguimiento de proyectos del área funcional de Mercadeo. Compuesto por Responsable Comercial, Responsable de Métodos y Gerente de Proyectos de Mercadeo; y los Funcionales Expertos de Mercadeo representando a cada compañía.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9ac34da6-1c52-49c2-b7d4-4ea080a7fd0d'::uuid, 'ERP', 'Sistema de Planificación de Recursos Empresariales', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1f89de2d-be3e-4142-b6b2-4a28454e2f9c'::uuid, 'Escala', 'es la relación entre el tamaño de un objeto real y su representación. En otras palabras, es la proporción de un elemento en comparación con otro, lo que ayuda a crear una sensación de tamaño, distancia y perspectiva.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('95d9c52c-1d97-4c81-8f55-1261a1eb93d3'::uuid, 'Escala de grises', 'se refiere a una gama de tonos monocromáticos que van desde el negro más puro hasta el blanco más puro. Cada tono de gris se crea mezclando diferentes cantidades de negro y blanco, sin incluir ningún otro color.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('bb1c91fe-0a73-47dc-9fad-495da5432118'::uuid, 'Eslogan', 'es una frase corta, memorable y concisa que resume la misión, los valores o los beneficios de una marca. Es una herramienta poderosa diseñada para ser fácil de recordar y asociar con un producto o servicio.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('18534369-e5bd-410f-bf7d-9e82f7ff689d'::uuid, 'Especificaciones', 'Lista de requisitos técnicos y funcionales que un sistema debe cumplir (ej. debe funcionar en móviles o permitir reportes).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('826c34c7-cf4c-43ce-9622-a309a10ad605'::uuid, 'Especificación técnica', 'Documento que define requisitos técnicos de productos, servicios o procesos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6de1abf5-e4b5-4a08-8df9-8865aa74a893'::uuid, 'Estacionamiento', 'Área designada para el estacionamiento de vehículos de colaboradores y visitantes, sujeta a normas de uso y seguridad.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c37a4105-9af2-405a-bbae-05b5b78150a1'::uuid, 'Estado', 'Se refiere a la condición o la situación actual de una entidad en un momento específico.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a963844a-6d07-47e3-952c-d9d122ab95e8'::uuid, 'Estado activo (Artículo)', 'Permite filtrar si el artículo está activo (Vigente) o no (Bloqueado).', '', 'homonimo'::estado_origen_termino, 'Se separó de un término homónimo compartido con: Estado activo (Empleado).', true, NULL, false, false, NULL, '2026-09-28T16:05:00.000Z'::timestamptz),
  ('0be5ac17-d76c-4015-b05e-df895b317366'::uuid, 'Estado activo (Empleado)', 'Estado del empleado que indica si el mismo está trabajando normalmente o si está suspendido ya sea por vacaciones, por despido, enfermedad u otros.', '', 'homonimo'::estado_origen_termino, 'Se separó de un término homónimo compartido con: Estado activo (Artículo).', true, NULL, false, false, NULL, '2026-09-28T16:05:00.000Z'::timestamptz),
  ('7289526d-4362-4241-8c73-eec2a2cba69a'::uuid, 'Estado de cuenta', 'Es un documento financiero que una empresa emite para su cliente. Detalla todas las transacciones pendientes, como facturas impagas y pagos recibidos, en un periodo de tiempo determinado. Es un resumen de la relación financiera entre el negocio y el cliente desde la perspectiva del proveedor.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e6ce3f85-c316-43c5-b677-f89e5fec9c90'::uuid, 'Estado de cuenta bancario', 'Informe emitido por un banco que resume todas las transacciones de una cuenta durante un período específico, esencial para la conciliación bancaria.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b4a09102-2e7f-4d89-b8c6-8deabca3d663'::uuid, 'Estado de ganancias y pérdidas', 'Reporte financiero que resume el desempeño económico de la empresa durante un período. Muestra los ingresos, costos y gastos, culminando en la utilidad o pérdida neta. Es el indicador clave de la rentabilidad operativa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('21ed3384-2dea-42d5-b342-0ff1f0b2300d'::uuid, 'Estado de resultados', 'Presentación formal de todos los ingresos y gastos pertenecientes a un período de tiempo específico.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7a871cb3-78a9-4e20-a435-7b3a1d80aa2e'::uuid, 'Estados (unidad de transporte)', 'Pueden ser Activo (en uso) o Inactivo (no en uso).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('329fe90d-dd99-4f40-be47-3f1d56d4bd4e'::uuid, 'Estados de la situación (unidad de transporte)', 'Pueden ser Asignado, Bloqueado o Disponible.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3ffc0f69-0757-43c9-b6e5-0dd57358f5fa'::uuid, 'Estadísticas', 'Muestra indicadores de ventas como presupuesto, ventas facturadas, renglones facturados y total de clientes, entre otros', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b8a17f5d-4668-44dc-8bbe-b18cb7afe88c'::uuid, 'Estandarización', 'Proceso de establecer normas y procedimientos uniformes para asegurar consistencia.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4d86efc1-0e57-4896-b4da-91f8e0b26b4a'::uuid, 'Estandarización de Datos', 'Proceso de ajustar los datos a un formato, tipo y estructura común. Su objetivo es eliminar discrepancias en la captura de información para permitir la consolidación de datos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('76000ca9-d790-49cc-a5ef-a649b2b03480'::uuid, 'Estantería', ' se le denomina así a los Racks o Bloques que se definen dentro del almacén, son estructuras que se conforman de niveles y columnas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b6342c59-7629-4967-bd0d-4d8df69682f1'::uuid, 'Estiba europea (EUR / EPAL)', 'Tipo de estiba que corresponde al pallet estándar utilizado en Europa para el transporte y almacenamiento de mercancías, regulado y certificado por la organización EPAL (European Pallet Association). Medidas: 120 × 80 cm. Nombre internacional oficial Europallet / EPAL 1', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a4075f49-b6bd-4636-8bf3-1c751f262add'::uuid, 'Estiba GMA (Estándar Norteamericano)', 'Tipo de estiba que corresponde al pallet estándar utilizado principalmente en Norteamérica (Estados Unidos y Canadá), definido por la Grocery Manufacturers Association (GMA).
Medidas: 122 × 102 cm. Nombre internacional oficial North American Standard (GMA)', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3ec711e7-5531-4c74-97ca-95b71b03157c'::uuid, 'Estiba ISO / Estándar', 'Tipo de estiba que corresponde al pallet cuyas dimensiones están normalizadas bajo la norma internacional ISO 6780.
Medidas: 120 × 100 cm. Nombre internacional oficial ISO Pallet / Estándar internacional', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e0479815-c66f-4c95-9710-1ec803a1da4e'::uuid, 'Estrategia', ' Es la manera general como orientamos nuestras acciones para lograr los objetivos propuestos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4204bc9d-4f97-4756-a5df-16b6ee4c794b'::uuid, 'Estructura organizativa', 'Organización jerárquica de cargos y funciones dentro de la empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e369fde7-513a-4e47-b926-b683d03192da'::uuid, 'ETL (extract, transform, load)', 'Proceso de extraer datos de una fuente, transformarlos y cargarlos a un sistema de análisis.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('76df97ce-c137-4db9-890a-6356421d5510'::uuid, 'Evaluación de desempeño', 'Proceso sistemático y periódico para medir el rendimiento de un colaborador en su puesto, en función de objetivos establecidos y competencias requeridas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c12b7008-c2bd-43bf-b0a7-ebe411a071bc'::uuid, 'Evaluación de necesidades', 'Diagnóstico de los problemas presentes y de los desafíos futuros que pueden enfrentarse mediante capacitación y desarrollo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d36d88ec-30b3-4c76-b1b1-80d6bc2f29ee'::uuid, 'Evaluación del interés', 'La fase de la venta donde se realizan preguntas exploratorias y se manejan las objeciones del cliente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1c3a137f-448f-4d5e-94ef-c550f14f2a4a'::uuid, 'Evento contable', 'Nombre que se le asigna a cada uno de los procesos que implican la generación de una transacción en la contabilidad.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4db007c6-c715-471f-be41-45bae35462d0'::uuid, 'Exactitud de pronóstico', 'Porcentaje de acierto del plan consensuado vs. la venta real', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('63ffd8a3-7467-4494-8cb1-3b11f117b7b5'::uuid, 'Expedición', 'Proceso de preparación y despacho de pedidos desde el CEDI hacia el cliente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('47b7d1ad-d844-431d-a7ed-71486587abfc'::uuid, 'Extracto bancario', 'Documento oficial del banco que detalla todos los movimientos (créditos, débitos, comisiones) en una cuenta durante un periodo, mostrando fechas, importes y saldos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('cde4b67b-fa4e-42b6-b416-748a71e21e41'::uuid, 'EXW', 'Ex Works - en fábrica (lugar convenido) . El vendedor pone mercancía a disposición del comprador en sus propias instalaciones, fábrica, almacén, etc. Todos los gastos a partir de ese momento son por cuenta del comprador.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e4c727d2-ff97-442a-9325-62330d6374eb'::uuid, 'Factor de gasto', 'Representa el resultado del análisis de los costos y gastos imputables al costo de la mercancía vendida en un lapso no mayor de 6 meses según lo establecido en disposiciones legales presentadas en la Gaceta Oficial N°40.341, de la Superintendencia Nacional para la Defensa de los Derechos Socio Económicos de la República Bolivariana de Venezuela.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4b40dce8-95ea-4116-918f-725a5f754602'::uuid, 'Factor logístico', 'La cantidad de unidades por caja.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4c23bf01-82bb-476d-954f-3fc4a8fb5c5a'::uuid, 'Factura', 'Documento mercantil con validez fiscal que detalla una operación de compraventa, especificando productos, precios, impuestos y condiciones de pago.', 'Factura', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:37:08.304Z'::timestamptz),
  ('8405afee-de94-4470-ab90-bd4af3190a08'::uuid, 'Facturación 4.4', 'Se refiere a la versión 4.4 del sistema de comprobantes fiscales electrónicos establecido por el Ministerio de Hacienda de Costa Rica.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7124d2aa-5d1c-4f99-bb24-7a17fd6f47b9'::uuid, 'Facturación de rutero', 'Un módulo que optimiza el proceso de preventa y cobro, y que está integrado con las actividades de control de inventarios, control de cobros y facturación. Refuerza la automatización de la fuerza de ventas, ruteo y preventa de la empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f1c2f511-e395-4b62-8724-2206c7cc89cb'::uuid, 'Facturación de rutero desktop', 'Es el componente a nivel de escritorio que sirve como administrador de rutas. Permite el registro, modificación y borrado de información como PDA''s, agentes, clientes, artículos y rutas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('76e11483-cbdf-4389-a868-8a3a79bbd31f'::uuid, 'Facturación de rutero móvil (FR)', 'Es el componente móvil del módulo que tiene como función principal facilitar la labor de preventa en el punto de venta a nivel móvil.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b64a8331-c47c-4f39-97c8-0728b869493c'::uuid, 'Falla', 'Cantidad de artículos con inventario en cero.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('bd21e91a-8780-4772-b861-c415335a79e9'::uuid, 'Falla %', 'Cantidad de artículos en falla entre el total de artículos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('693053d5-4a14-4708-adf8-cb980158ecf3'::uuid, 'Faltantes', 'Al cliente no le llegó el pedido, una línea o menos de lo indicado en la factura.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a9979f50-e827-47d9-b1f8-4c7b33216eb6'::uuid, 'Familia', 'División especifica dentro de cada sub categoría de artículos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f3810e3c-2e25-46a8-a41c-97d9aea69664'::uuid, 'Familia de productos', 'Es el nivel más granular y se basa en las especificaciones del producto. Agrupa productos que son casi idénticos en su función, pero que varían en detalles técnicos cruciales para el cliente.', 'FAMILIA DE PRODUCTO', NULL, NULL, false, NULL, false, false, NULL, '2026-09-30T19:30:00.000Z'::timestamptz),
  ('71e86388-67e1-48fc-9a73-dbd3764bc14f'::uuid, 'FAS', '(Free Alongside Ship - Libre al costado del buque (puerto de carga convenido)). El vendedor entrega la mercancía en el muelle pactado del puerto de carga convenido; esto es, al lado del barco. El vendedor es responsable de las gestiones y costes de la aduana de exportación.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('611937a7-00e6-41ea-afb7-6c63c6f6cec5'::uuid, 'FASB-52', 'Habilita el control de movimientos en moneda funcional y en moneda reporte según el tipo de cambio especificado. ​', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('69e3cfac-a236-45d2-b253-8ed297796f97'::uuid, 'Fase de adopción', ' Fase 5 de la Metodología de Cambio. Pone la solución a operar y evalúa los resultados. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('488d0519-f283-457b-addb-a8dd5c0ac31a'::uuid, 'Fase de alineación', ' Fase 1 de la Metodología de Cambio. Crea un entendimiento común entre los participantes del propósito del proyecto. Se establece cuál es el área de oportunidad. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('46336647-5425-4fa3-8000-db79698f1344'::uuid, 'Fase de construcción', ' Fase 3 de la Metodología de Cambio. En la fase de  preparación se desarrollan los planes de  construcción e implementación (automatizada o no). Se establece quién hace cuándo para entregar la solución. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ff9c8634-215b-442b-b5a2-0465083bf6fc'::uuid, 'Fase de diseño', ' Fase 2 de la Metodología de Cambio. Se identifican las razones del área de oportunidad, se aterriza el proyecto y establece un curso de acción. Se establece la forma de proceder para resolución. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0cfb3a80-51d7-4b0c-a4a8-e04ca95aaf67'::uuid, 'Fase de implementación', ' Fase 4 de la Metodología de Cambio. En esta fase se prepara a la Organización/Compañía para recibir  la solución. Se prepara a la operación para operar el nuevo proceso.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('61c00dbd-3eee-4c24-8910-1f4597287276'::uuid, 'FCA', '(Free Carrier - Libre transportista (lugar convenido)). El vendedor se compromete a entregar la mercancía en un punto acordado dentro del país de origen, que pueden ser los locales de un transitario, una estación ferroviaria. (Este lugar convenido para entregar la mercancía suele estar relacionado con los espacios del transportista). Se hace cargo de los costos hasta que la mercancía está situada en ese punto convenido.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('41de50a8-f938-4c77-9299-b1f5b89ef76f'::uuid, 'Fecha', 'Tipo de dato cronológico que indica el día calendario. Debe ser expresado en formato AAAA-MM-DD', 'Fecha', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:42:25.128Z'::timestamptz),
  ('3a8587e8-f662-41b4-aa52-6a3409be7a96'::uuid, 'Fecha de revisión', ' Fecha en que se elabora o se realizan modificaciones al diagrama. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8bdff05d-db3d-4448-91bc-07476266afb8'::uuid, 'Fecha ETA estimada', 'ETA significa Estimated Time of Arrival, en español Fecha Estimada de Llegada. Es la fecha estimada de llegada del medio de transporte al puerto o destino establecido para la importación.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9509e71b-bd55-467a-896a-1152bafd8cad'::uuid, 'Fecha ETA real', 'ETA significa Estimated Time of Arrival, en español fecha estimada de llegada. Al agregar la palabra "real": es la fecha efectiva en la que el medio de transporte llegó al puerto o destino establecido para la importación.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('10f53a08-b2eb-49af-ad27-44f9dc305193'::uuid, 'Fecha ETD estimada', 'ETD significa Estimated Time of Departure; en español, es Fecha Estimada de Salida. Es la fecha estimada de salida del medio de transporte desde el puerto de origen hacia el destino de la importación.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3c153793-215a-4f88-ae7a-da6fb26aeafb'::uuid, 'Fecha ETD real', 'ETD significa Estimated Time of Departure, en español es Fecha Estimada de Salida. Cuando se agrega la palabra "real", es la fecha efectiva en la que el medio de transporte salió del puerto de origen con la mercancía embarcada.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('abaded62-063f-4c35-a64c-6d6c1a566f40'::uuid, 'Fecha ofrecida', 'Fecha en la que el proveedor se compromete a tener la mercancía completamente preparada, empacada y disponible en las condiciones acordadas para su carga y posterior transporte desde el proveedor hacia el CEDI', 'Fecha Ofrecida', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:42:29.911Z'::timestamptz),
  ('0d59e30a-eec9-4b48-bbb6-3a8f7548f825'::uuid, 'Fecha requerida', 'Fecha en la que se requiere contar con la mercancía disponible en el CEDI, considerando el Lead Time del proveedor', 'Fecha Requerida', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:42:31.101Z'::timestamptz),
  ('852466dd-8ace-4204-a730-b7bf91dc365f'::uuid, 'Fecha requerida embarque', 'Fecha objetivo en la que se requiere que la mercancía sea embarcada desde el país de origen, considerando los tiempos de tránsito internacional y demás procesos logísticos necesarios para cumplir con la fecha requerida', 'Fecha Requerida Embarque', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:42:32.731Z'::timestamptz),
  ('a351cc47-2bd4-4ff7-a1ec-814dd9dc3588'::uuid, 'Feedback (retroalimentación):', 'Comunicación bidireccional destinada a informar a un colaborador sobre su desempeño, con el objetivo de reforzar conductas positivas y corregir áreas de oportunidad.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('52969983-b2a0-4eff-a85a-77065d8fe339'::uuid, 'FEFO', 'Acrónimo de “First Expired, First Out”, método de rotación de inventario basado en la fecha de caducidad.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9b26198b-ec30-4763-8b73-f38090f5453b'::uuid, 'Ficha de cliente', 'Una sección de la aplicación que muestra información detallada de un cliente, incluyendo sus datos, ubicación, contactos, finanzas y cuentas bancarias.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d80d31b8-635a-4246-b54f-14ad8a6f6e37'::uuid, 'Ficha técnica', 'Información adicional para los artículos que puede incluir sustitutos, artículos relacionados y una descripción detallada.', 'Ficha Técnica', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('23235013-1de4-44dd-9629-693b32ebddfc'::uuid, 'Fijación de precio', 'Proceso para determinar el valor monetario al que una empresa venderá sus productos o servicios. Es una decisión estratégica que debe considerar múltiples factores internos y externos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7fcee247-f184-482b-95e2-12052d652da6'::uuid, 'Fill Rate', 'Silo Control: Métrica de cadena de suministro que mide el porcentaje de la demanda de un cliente que se satisface con el inventario disponible de forma inmediata. Silo Logística: La tasa de cumplimiento o nivel de servicio, es un indicador que mide el porcentaje de pedidos de clientes que se entregan completos y a tiempo. Reporte SIM – Indicador Compra: Mercancía recibida entre mercancía solicitada.', '', 'dudoso'::estado_origen_termino, 'Las 3 definiciones originales no son idénticas: disponibilidad inmediata de inventario (Control), pedidos entregados completos y a tiempo (Logística), y mercancía recibida entre solicitada (Compras). Podrían ser métricas relacionadas pero distintas en vez de una sola.', false, NULL, false, false, NULL, NULL),
  ('4f08050d-3ef8-4c1f-b9a9-09c0da44cbbe'::uuid, 'Filtro', 'Herramienta que permite mostrar solo la información que cumple ciertos criterios (ej. ventas de enero).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fcdd3730-f613-460a-9ed1-4d048e80e7ba'::uuid, 'Finalizar pedido', 'Es la acción decisiva que convierte la intención de compra del cliente en una orden de venta activa y procesable para el negocio.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d4822292-be2c-4700-b3b8-ff68873dc93c'::uuid, 'Firewall', 'Programa o equipo que actúa como filtro de seguridad, bloqueando accesos no autorizados desde internet.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('514c23c2-3a2b-4022-9575-1255372307a2'::uuid, 'Firmas autorizadas de bancos', 'Personas designadas y registradas en el banco con la potestad para aprobar y ejecutar transacciones financieras en nombre de la empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ef5d9c40-a804-46fa-a304-c518e4c64f77'::uuid, 'Flete internacional', 'Precio a pagar por los exportadores o los importadores por el servicio de transporte de las mercancías transportadas. Represente el monto desde el origen, es decir, desde el momento en que se elabora el conocimiento de embarque original y se inicia el servicio de transporte hasta el puerto o lugar de importación.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('94d0f325-3853-4841-9f0c-a24056459342'::uuid, 'Flujo de caja', 'Informe que muestra el movimiento de efectivo generado y utilizado por la empresa en sus actividades de operación, inversión y financiación durante un período. Es vital para evaluar la liquidez.', 'Flujo de Caja', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:42:34.212Z'::timestamptz),
  ('c2f701d1-7dc8-4507-9581-0c3d194e15b0'::uuid, 'Flujo de una pieza', 'La producción de flujo de una pieza consiste en fabricar las piezas una a una y pasar al siguiente proceso. Entre las ventajas del flujo de una pieza se encuentran: 1) la rápida detección de defectos para evitar un gran lote de defectos; 2) plazos de producción cortos; 3) reducción de costes de material e inventario; y 4) diseño de equipos y estaciones de trabajo de tamaño mínimo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b05d4c35-0aaa-4727-9e0e-7efc5abe6952'::uuid, 'Flujograma / diagrama de flujo', 'Representación visual de las etapas y decisiones dentro de un proceso.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d76ac863-b452-47e2-9148-54c93c916f92'::uuid, 'Flyer', 'es una hoja de papel suelta, generalmente de tamaño A5 o más pequeño, que se utiliza para distribuir información y promocionar un producto, servicio, evento o idea.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('173c2074-4e95-4675-b648-344d0ef095c2'::uuid, 'FOB', '(Free On Board - Libre a bordo (puerto de carga convenido)). El vendedor entrega la mercancía sobre el buque. El comprador se hace cargo de designar y reservar el transporte principal (buque).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3fdc2d33-0d0c-460c-b247-9b16acb6e98b'::uuid, 'Fondo de prestaciones sociales', 'Mecanismo de ahorro forzoso en Venezuela donde las empresas deben depositar un porcentaje del salario para cubrir las prestaciones sociales (equivalentes a cesantías y intereses sobre cesantías en Colombia)', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2dc54bd3-d2bb-4781-9da8-d65c3bd54e8a'::uuid, 'Footer', 'es la sección inferior de una página web que se mantiene fija y visible en todas o la mayoría de las páginas de un sitio.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e6483ab9-d100-42d1-92e4-934504e7db2b'::uuid, 'Forecast bias', 'Tendencia sistemática a sobreestimar o subestimar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('66691f84-9d4e-48c0-8fc7-d196a1de335f'::uuid, 'Forecast Consensuado', 'El plan de demanda consensuado para toda la organización.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('46e8edf0-073a-41b3-9a13-f31e3a8c6fac'::uuid, 'Forecast performance', 'Porcentaje de coincidencia entre el pronóstico y la demanda real.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('306b3852-8727-455b-981a-60627913d027'::uuid, 'Formato', ' Se elaboran con el propósito de solicitar, monitorear, registrar, analizar datos y dejar evidencia de los macroprocesos de la empresa. ', 'Formato', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:42:35.399Z'::timestamptz),
  ('c0977f82-7f84-41f8-b0f2-fedd9430c9b0'::uuid, 'Fotomontaje', 'es una técnica de edición digital que consiste en combinar o superponer varias fotografías para crear una única imagen que parece ser real o, al menos, coherente. Es una forma de "manipular" la realidad para lograr un efecto visual específico o para contar una historia que no podría ser capturada con una sola toma.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3707ade5-9bc1-413b-ab78-fbf06f658571'::uuid, 'Fracciones de intereses', 'Se refiere a la modalidad de cálculo de porciones de intereses, que puede ser utilizada al cancelar un pago antes de la fecha de pago o pagos parciales de cuotas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('dda6e654-de3d-4a8d-9c98-070b3801198c'::uuid, 'Frecuencia de colocación de orden de compra', 'Es el tiempo en días que transcurre entre una colocación de una orden de compra y la siguiente orden de compra.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('737ae589-cd55-4d15-93c7-6c1cea5eb6cb'::uuid, 'Frecuencia de revisión de la descripción de artículos', 'Se establece una frecuencia semestral para efectuar una revisión general de la estructura del surtido.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('76db48c0-495b-40ed-aba3-da360432b072'::uuid, 'Fuente', 'Relaciona un movimiento contable con el documento que lo sustenta (número de cheque, de factura, etc.). ​', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-03T10:45:41.834Z'::timestamptz),
  ('2e1d70fc-99b4-424c-b283-de1e0079ee65'::uuid, 'Fuente (tipografía)', ') es un conjunto de caracteres alfanuméricos y símbolos con un estilo y diseño unificados. Se refiere a la apariencia visual del texto, incluyendo su forma, peso, tamaño, espaciado y estilo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('451ee6b5-e458-465c-9d4a-4f9747521c2d'::uuid, 'Fundación kaizen', 'Los tres principios y siete conceptos de KAIZEN™ que sirven como base para los sistemas y herramientas necesarios para la implementación de la Mejora Continua y la Gestión de la Calidad Total, y que dan forma a la cultura y al pensamiento del liderazgo de una organización.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('26098429-0cc2-4012-a598-d862389a9d1f'::uuid, 'Fusión', 'Operación en la que dos o más empresas se unen para formar una sola entidad legal.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6094dff6-5db8-45ab-9b56-d9c853e6a2a4'::uuid, 'Físico de empaque', 'La cantidad de cajas físicas de un artículo en una ubicación específica.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e3a21df6-499a-40f0-b2e9-9b14e8729186'::uuid, 'Físico unidades', 'Cantidad física de unidades contabilizadas en una ubicación específica.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b47031ea-52f8-4a18-aee5-c70aa7321734'::uuid, 'GAN (generative adversarial network)', 'Tipo de red neuronal que genera contenido nuevo, como imágenes o música.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c3e39344-e626-4774-a756-9c4bd7ecd480'::uuid, 'Ganancia operativa', 'Silo Control: Beneficio generado por las operaciones principales del negocio, antes de deducir intereses e impuestos. Mide la eficiencia y rentabilidad del core business. Reporte SIM – Indicador Control: Suma de las ganancias obtenidas de las operaciones principales de la empresa.', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('829963e2-5428-466a-8234-3f6a34cc49ca'::uuid, 'Garantía', 'Es una promesa del proveedor que asegura la calidad y el buen funcionamiento de un artículo por un período determinado. En el comercio mayorista, es crucial para la gestión de devoluciones y la satisfacción del cliente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('589c89ef-5bd7-4272-9045-51df779f4cc5'::uuid, 'Gasto', 'Desembolso de dinero que una empresa realiza para sus actividades operativas que no está directamente ligado a la producción o adquisición de mercancía (ej. salarios administrativos, alquiler).', 'Gasto', NULL, NULL, false, NULL, false, false, NULL, '2026-10-03T10:45:52.381Z'::timestamptz),
  ('f0fb3d0c-9b1d-403d-b223-10404463e563'::uuid, 'Gasto Personal', 'Es un indicador financiero clave que representa la suma total de todos los desembolsos e inversiones que realiza una organización para compensar y mantener a su fuerza laboral durante un período específico (normalmente un año o un trimestre fiscal). Es el costo total de emplear a las personas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3d90d835-0f33-4819-87c8-f8e5bdae2dd8'::uuid, 'Gastos de personal', 'Todos los costos asociados a la remuneración de los empleados, incluyendo salarios, cargas sociales, beneficios, etc.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('66f28f69-670c-4ba9-9c68-bc3cd0c4056a'::uuid, 'Gastos operativos', 'Silo Control: Costos incurridos en las actividades principales del negocio, excluyendo el costo de la mercancía vendida (CMV), intereses e impuestos. Reporte SIM – Indicador Control: Suma total de los gastos incurridos en las operaciones cotidianas de la empresa.', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('76dfb724-036d-439b-af19-f83cbc743030'::uuid, 'Gastos operativos / Renta Bruta', 'Ratio que muestra la proporción de la renta bruta que es consumida por los gastos operativos', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('60332d87-3bd5-4c83-a051-b57b0a315267'::uuid, 'Gastos operativos sin tributos', 'Suma de los gastos de operación de la empresa excluyendo los impuestos y tributos pagados.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7496be25-ccc1-405e-bcbc-974a656558da'::uuid, 'Gemba', 'Palabra japonesa que literalmente significa "el lugar real". En el contexto de KAIZEN™, gemba suele referirse al lugar donde se añade valor, como el taller. En un sentido más amplio, gemba se refiere a cualquier lugar de una empresa donde se realiza el trabajo; por ejemplo, puede haber un gemba de ingeniería, un gemba de ventas, un gemba de contabilidad, etc.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6e775fb6-7e1e-40ef-b565-cdd071df95ed'::uuid, 'Generación de asientos', 'Proceso automático o manual dentro del ERP que crea los asientos contables correspondientes a las transacciones operativas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f8d7cda0-71f6-416e-867f-dbe04b1e2c12'::uuid, 'Gestión de calidad total (TQM)', 'La Gestión de Calidad Total (GCT) es una filosofía de gestión integral que busca la mejora continua de la calidad de productos y procesos. La GCT se basa en la premisa de que la calidad de los productos y procesos es responsabilidad de todos los involucrados en la creación o el consumo de los productos o servicios que ofrece una organización, lo que requiere la participación de la gerencia, el personal, los proveedores y los clientes para cumplir o superar las expectativas de los clientes.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3abd6eda-e147-4eec-a98f-f9ba770069c1'::uuid, 'Gestión de cobranza', 'Es el conjunto de procesos y estrategias que la empresa implementa para recuperar el pago de las deudas que sus clientes tienen con ella. Su objetivo principal es asegurar que los pagos se reciban a tiempo, lo que mantiene un flujo de caja saludable y evita problemas financieros.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8a7f1f41-ede9-4cf3-ba71-b8d8be357e6e'::uuid, 'Gestión de Restricciones', 'Etapa del S&OP en la que el plan de demanda (irrestricto) se confronta contra las limitaciones reales de suministro (capacidad productiva, inventario, lead times, proveedores, presupuesto). Su objetivo es transformar un plan "deseado" en un plan factible y ejecutable, resolviendo los desbalances entre lo que se quiere vender y lo que se puede abastecer.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('eb380dce-f66d-4e80-970c-ab4c50384ef6'::uuid, 'Gestión de ventas', 'Es el proceso integral de planificar, dirigir, coordinar y controlar todas las actividades relacionadas con las ventas de una empresa para alcanzar sus metas de ingresos y crecimiento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('746362d3-7001-4f29-9b78-e8fc38130ef8'::uuid, 'Gestión multifuncional', 'La coordinación interdepartamental necesaria para alcanzar los objetivos estratégicos y de políticas de KAIZEN™ y la Gestión de Calidad Total. Su importancia fundamental reside en el seguimiento para alcanzar los objetivos y medidas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2a4be756-cc6e-41cf-b658-7b61674cc1d7'::uuid, 'Gestión orientada a resultados', 'Un estilo de gestión generalmente asociado con controles, desempeño, consideraciones sobre productos o resultados, recompensas y/o castigos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1eea46f5-c30b-44c4-9064-b45ef2b0fdba'::uuid, 'Gestión upstream', 'Un concepto y proceso KAIZEN™ mediante el cual, a través de la mejora continua, los defectos se eliminan cada vez más arriba en el proceso de producción, primero en la inspección, luego en la línea y luego en el desarrollo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('52c7999a-3f8f-49ed-bb87-70f0e6c9e9c1'::uuid, 'Gestión visual', 'La Gestión Visual es un conjunto de técnicas para crear un entorno de trabajo que integre la comunicación y el control visual en todo el entorno laboral. La filosofía de la Gestión Visual se basa en la idea de que «lo que se mide y se muestra, se hace». Se utilizan herramientas visuales sencillas para identificar el estado objetivo y cualquier desviación se corrige con medidas correctivas. También facilita la comprensión de los procesos implementados. Esta información puede referirse a los propios puestos de trabajo, a la empresa en su conjunto o al progreso de los equipos de trabajo en un proyecto. Ejemplos de Gestión Visible son las tarjetas Kanban, los tableros de sombras de herramientas, los guiones gráficos, etc.', '', NULL, NULL, false, NULL, false, false, NULL, NULL)
ON CONFLICT DO NOTHING;

INSERT INTO terminos (id, termino, definicion, campo_softland, estado_origen, nota_origen, revisado, nota_decision, es_nuevo, editado, eliminado_en, actualizado_en) VALUES
  ('4470fdd2-0fb4-4c91-96c5-a436704c274e'::uuid, 'GM ROI', 'Margen por Rotación.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('50fd7612-3aa2-4db8-84f4-66083f19a639'::uuid, 'GMROI', '(Gross Margin Return on Investment) Métrica que evalúa la rentabilidad del inventario. Se calcula como (Margen Bruto / Inventario Promedio) e indica cuántos dólares de margen bruto se generan por cada dólar invertido en inventario.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('26eeec1a-f5b9-445b-a90d-4acb2dc30a08'::uuid, 'Gobernanza de datos', 'Marco de políticas, estándares y procesos para gestionar los activos de datos de la empresa, garantizando que sean precisos, consistentes y seguros, consolidando la "única verdad".', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d0adcb58-5c3f-4c2e-9ad2-37bf22628ad9'::uuid, 'Granularidad', 'Nivel de detalle o atomicidad de los datos contenidos en una tabla. Una granularidad alta implica que el dato representa la transacción mínima (ej. el ítem de una factura), mientras que una granularidad baja representa datos agregados o resumidos (ej. el total de ventas mensual).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c65ca2b2-3c9d-49c4-84b8-bba8241e8e1e'::uuid, 'Grupo Compra', 'Reporte SIM – Dimensión Compras: Muestra la agrupación de marcas asignadas por comprador. Reporte SIM – Filtro Compra: Permite visualizar la informaciónen en base a la selección de uno o mas Grupos compra.', 'Grupo Compra', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, 'Se registran ambos campos técnicos porque varían según la empresa.', false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('a2812462-ca90-4752-ba9d-a1043dc636d9'::uuid, 'Grupo de usuarios', 'Un grupo de usuarios es un conjunto de empleados en la compañía para quienes se establecen, simultáneamente, los mismos derechos sobre cada una de las opciones de los módulos del sistema. ​', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f92e62a8-424e-427c-b4af-8ca7758ef77c'::uuid, 'Grupo Marca', 'Es la división por subgrupos que realiza Mayoreo de las marcas.', 'Grupo Marca', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('29f13494-d82e-4112-8b21-660e2b57c00e'::uuid, 'Grupos', 'La clasificación más general de productos. Una regla establece que debe haber un mínimo de 4 y un máximo de 7 grupos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4495cc46-cdea-435d-82c7-d64aeba2064a'::uuid, 'Grupos logísticos', ' Agrupación de artículos por familia para el proceso de almacenaje. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3ea74b7a-7d38-4a93-a2b8-c01fbcdb2430'::uuid, 'Gráfico de control', 'Un gráfico con límites de control superior e inferior dentro de los cuales una máquina o proceso se encuentra bajo control. Con frecuencia, una línea central, a medio camino entre ambos límites, ayuda a detectar tendencias hacia uno u otro. El trazado de mediciones críticas en el gráfico indica cuándo una máquina o proceso se ha descontrolado y debe ajustarse. Es una de las Siete Herramientas Básicas de la Calidad.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('dc0fce8d-1198-4c77-a19b-1fbbf83ab519'::uuid, 'Gráfico de radar', 'Un diagrama circular con diez rayos, uno para cada uno de los tres principios y siete conceptos de KAIZEN™. Se utiliza como herramienta de diagnóstico para medir, en una escala de cero (en el centro) a diez (en el borde), el grado de coherencia con los principios y conceptos de KAIZEN™ que exhibe una organización.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2d598cf8-a56c-4aba-b71f-02bda83c8fce'::uuid, 'GTIN (global trade item number)', 'Campo informativo u opcional para ingresar el Número global de artículo comercial.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d8aaf9df-463d-4b74-87ca-e64b2202433c'::uuid, 'Hablador', 'Hoja de papel bond blanco tamaño carta, que contiene información sobre el contenido de una paleta.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fc371003-0e8d-4a9d-8922-adec80f9fddd'::uuid, 'Hallazgo de auditoría', 'Es una conclusión resultante de un proceso de auditoría que identifica una desviación o brecha entre la condición actual de un proceso y el criterio o estándar esperado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1a2203b1-5018-44a7-a202-a1de180a8a51'::uuid, 'Hand held', 'Herramienta donde se registran pedidos y demás transacciones propias de preventa y ruteo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('cd5955df-e709-4cf2-8661-c53438da7529'::uuid, 'Hanedashi', 'Expulsión automática de piezas. Las piezas pueden insertarse manualmente en la máquina, pero al finalizar el ciclo, la pieza procesada se expulsa automáticamente para que el operador pueda simplemente insertar la nueva pieza y pasarla al siguiente proceso, reduciendo así el tiempo de ciclo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d972cc47-ac2b-4a20-a414-431c3cb3b166'::uuid, 'Hardware', 'Componentes físicos de un sistema, es decir, todo lo que se puede tocar: servidores, computadoras, impresoras, routers.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f85ebc8e-f5fd-45ab-b60c-55994f999ba1'::uuid, 'Header', 'es la sección superior de una página web que se encuentra en un lugar fijo y visible, generalmente en la parte de arriba del sitio. Es uno de los primeros elementos que los visitantes ven y, por lo tanto, es crucial para la navegación, el branding y la usabilidad.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8bed0f8c-263e-428f-939e-70d929f01152'::uuid, 'Help desk / mesa de ayuda', 'Área de soporte técnico que atiende a los usuarios cuando tienen problemas con sus sistemas o computadoras.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('78a45a97-7efd-475e-8c8e-0eb3c7320229'::uuid, 'Hexadecimal', 'es un sistema de codificación que se utiliza para representar los colores. Es la forma más común de definir los colores en la web, en CSS, HTML y en programas de diseño.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4aff6140-751f-4ea4-be47-12de9ad9bfc4'::uuid, 'Highligh', 'Barra de color llamativo que actúa como un cursor sobre una opción en un menú representada como texto. Normalmente responde a las teclas direccionales o al cursor del ratón.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('741ff552-de9e-443c-972d-6c6fa7272a71'::uuid, 'Homologación', 'Proceso para asegurar que una autoparte cumple con las especificaciones técnicas de un vehículo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9f909e1b-cd3b-4ba6-a90d-ed7a2211b8ba'::uuid, 'Horario', 'Horario de trabajo de los empleados, éste puede ser fijo o bien, rotativo, dependiendo de los turnos en que se trabaje y de la demanda del producto o servicio.', 'Horario', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:42:36.851Z'::timestamptz),
  ('b3c80b7b-36c3-4109-b605-aa0747033d9c'::uuid, 'Horas hombre (%)', 'Son los procesos del BPA con mayor cantidad de horas hombre hasta alcanzar el 80% de las horas de ejecución. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('cdda8b88-2a14-4ec8-9c22-c604902f4e0a'::uuid, 'Hot keys', 'Al español puede traducirse como "teclas rápidas". ​ Combinación de teclas que permiten ejecutar la función deseada, sin tener que utilizar el menú. ​', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('bfe738d8-52f7-4203-80e2-7e822e96a31e'::uuid, 'Hueso', 'Artículo Vigente que tiene inventario inicial y final durante el mes, sin ventas durante los últimos seis meses.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('dd05ae9e-44c4-4462-a1c3-4c4e6e9eeb4c'::uuid, 'I.V.A atrapado', 'Pérdida de valor del crédito fiscal (IVA retenido) debido a la devaluación de la moneda local, cuando los estados financieros se valoran en una moneda más fuerte como el dólar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1b02f54a-3080-458f-917e-8867e9ac48ac'::uuid, 'I.V.A.', '(Impuesto al Valor Agregado) Tributo que grava el valor añadido en cada etapa de la cadena de producción y comercialización de bienes y servicios.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('df4a48c7-6607-49ba-92b0-cc80888f89cd'::uuid, 'Icono', 'es un pequeño símbolo o imagen visual que se utiliza para representar una idea, un objeto, una acción o una función de manera rápida y universal. Los íconos son una forma de comunicación visual que trasciende el lenguaje, ya que su significado a menudo se comprende de manera intuitiva.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d178be34-dc5e-417b-9355-dfff06bc9dad'::uuid, 'ID de recepción', 'Un identificador único para la creación del documento de recepción.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8e103754-fa34-4c18-b95d-e3b36c99e698'::uuid, 'Identidad infografía', 'es una herramienta de comunicación visual que se usa para contar la historia o definir las características de un sujeto (marca, persona, concepto) de una manera gráfica, concisa y memorable.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('351514bb-ad91-4433-a45b-09ef4806ab38'::uuid, 'Identificación de ubicaciones', ' Código alfanumérico para definir las ubicaciones dentro del almacén. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('33b0d33d-1b51-496e-ac29-ec438c397995'::uuid, 'Implementación de políticas', 'El proceso de implementar las políticas de liderazgo de una organización directamente a través de los gerentes de línea e indirectamente a través de la integración y cooperación interfuncional.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('203ada12-595d-4ec1-a490-56e067a628d5'::uuid, 'Impuesto Sobre la Renta (ISLR)', 'Tributo que se paga al Estado sobre las ganancias o enriquecimientos netos obtenidos durante un período fiscal.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('db284fd6-6424-4de5-99fc-55244c2934b4'::uuid, 'Impuestos', 'Pagos obligatorios al gobierno, calculados sobre ingresos, ganancias o transacciones, cuya correcta gestión es una función clave del área de Control.', 'Impuesto', NULL, NULL, false, NULL, false, false, NULL, '2026-09-30T20:00:00.000Z'::timestamptz),
  ('09bb93d1-4140-40de-bea1-d433fc900ae8'::uuid, 'Inactivación de proveedores', 'Procedimiento de control para desactivar a un proveedor en el sistema, asegurando que no queden saldos pendientes y manteniendo la base de datos depurada.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('70cc4c6a-ded1-4600-bb21-b4fbc77ec9c9'::uuid, 'Inbound marketing', '(también conocido como marketing de atracción) es una metodología que se enfoca en atraer clientes potenciales de manera no intrusiva, a través de la creación de contenido de valor y experiencias que son relevantes y útiles para ellos. A diferencia del Outbound Marketing,', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a77bf089-5051-464f-980b-2ca54ee4a309'::uuid, 'Incidencia', 'Problema o error que ocurre en un sistema y que debe ser atendido.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5a49fe61-9a85-4275-b0a1-810483d9b6b1'::uuid, 'Incidencia (en Picking RF)', 'Genera una alerta de picking, solicitando el motivo de la incidencia y la cantidad de unidades alistadas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('15d36341-29fd-4011-8b3b-14e383c03861'::uuid, 'Inclinarse', 'En inglés, este término significa literalmente que no contiene grasa; es decir, es magro. Aplicado al contexto de la gestión, se refiere a una estrategia que busca reducir o eliminar el exceso o el desperdicio.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('279755b0-adca-4d04-9bca-279171c9df53'::uuid, 'Inclusión', 'El proceso de agregar nuevos artículos y proveedores al sistema de información de la compañía, asegurando su calidad, consistencia y alineación con los objetivos estratégicos de la empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('bbfc56b8-4711-43f6-bdb6-dc85366bb63a'::uuid, 'Incoterms', 'International Comercial Terms, (términos internacionales de comercio), son un conjunto de reglas internacionales, regidos por la Cámara de Comercio Internacional, que determinan el alcance de las cláusulas comerciales incluidas en el contrato de compraventa internacional.', 'Incoterms', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:42:40.188Z'::timestamptz),
  ('5537d68f-f723-4795-b794-019b29214bb0'::uuid, 'Indicador', ' Debe definirse al menos un (01) indicador por proceso y por actividad. Debe especificar qué miden, cuáles son las acciones que se toman en cada caso, quién es el responsable de obtener el indicador, quién(es) es el responsable(s) de ejecutar las acciones. ', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:37:26.956Z'::timestamptz),
  ('2b8f81d5-b864-407b-b2fe-47d72ba61eb5'::uuid, 'Inducción', 'Proceso de formación y acompañamiento inicial para nuevos colaboradores o aquellos que cambian de puesto.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('43688de0-472a-47c5-90dc-000bb921d946'::uuid, 'Infaltable', 'Producto que es fundamental tener disponible dentro de la oferta de la marca, independientemente de su volumen de ventas o su BDF. Es un producto que es clave para la estrategia comercial, porque es necesario para vender otros productos o porque el fabricante lo considera indispensable dentro de la marca.', 'INFALTABLE', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('39ffa8dc-bc6a-43c8-9ad8-f83bb074f39e'::uuid, 'Información', 'Conjunto de datos organizados que tienen un significado útil, por ejemplo: “Ana tiene 23 años y vive en Costa Rica”.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d7b28b13-dfa7-4d24-b241-f5f64ccc0eed'::uuid, 'Informe (report)', 'Documento digital con varias visualizaciones o gráficos sobre los datos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('bd49e79e-759d-4384-bb8c-b6a8501ae0aa'::uuid, 'Informe de conciliación bancaria', 'Documento formal que presenta el resultado del proceso de conciliación bancaria, detallando las partidas conciliadas y las pendientes, y que requiere aprobación.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0f9999a0-a767-4cb7-843a-33ca0315fa13'::uuid, 'Ingresados', 'Es un indicador de adquisición de talento que representa el número total de nuevos colaboradores que se han incorporado a la organización a través de todos los canales de reclutamiento (contrataciones externas, traslados internos de otras unidades de negocio, practicantes, etc.) durante un período específico de tiempo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b1dcc2a3-0eb1-4556-85b5-4df90ee4dba3'::uuid, 'Ingresos Mercantiles', '', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9b5b49ac-7ce2-4972-80a4-a4bae96bddbb'::uuid, 'Ingresos Mercantiles %', '', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c7c1614b-37f0-468e-a4fb-98e014ffbc2b'::uuid, 'Iniciativas', ' Son proyectos específicos que buscan introducir innovaciones, cambios o mejoras en el funcionamiento de la compañía o lograr objetivos específicos. Éstas se generan del proceso de planificación estratégica. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('88a1d98a-44f0-45e9-901d-09560e1f0e88'::uuid, 'Input comercial', 'Es el "override" o ajuste de juicio (comercial) sobre el estadístico', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ee16447a-4d2b-4aee-840d-c6af5e2114e8'::uuid, 'Instrucciones', ' Es un documento que contiene instrucciones detalladas que especifican exactamente qué pasos seguir para ejecutar algo específico. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1065afc3-15cf-461c-8503-25408b9e1986'::uuid, 'Instructivo', 'Documento que detalla paso a paso cómo ejecutar una tarea específica.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('395ce751-880c-4d3a-9da9-a8429c365304'::uuid, 'Instrumento', 'Medio físico o digital; de carácter comercial, de identidad o comunicacional; que lleve la Imagen Corporativa de alguna Unidad de Negocio. Ejemplo: Tarjeta de Presentación. Lámina de Presentación. Uniforme. Un instrumento debe regirse por las leyes y legislaciones que puedan estar relacionadas a su uso en algún país.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('cbdef073-c753-47ac-a5f9-3369dd1cd7ed'::uuid, 'Integración contable', 'El proceso de integración contable se basa en la relación entre los distintos módulos del sistema. De manera que, todas las transacciones generadas desde módulos auxiliares como Cuentas por Cobrar se reflejarán en la contabilidad de la compañía, la cual es manejada directamente por el módulo de Contabilidad General.', 'Integración Contable', NULL, NULL, false, NULL, false, false, NULL, '2026-10-03T10:46:09.068Z'::timestamptz),
  ('464060a1-fe3f-40e9-ad13-da22dfefc73c'::uuid, 'Inteligencia artificial (ia)', 'Tecnología que permite que las máquinas realicen tareas que normalmente requieren inteligencia humana, como reconocer imágenes o responder preguntas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('63b42134-bcc6-4b6b-8502-3136831c91cf'::uuid, 'Intelix', 'Proveedor de tecnología responsable del desarrollo, integración y despliegue de la solución tecnológica del proyecto.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fe4baef5-8a04-4b0a-8b90-2c7e0b57d5d1'::uuid, 'Interacción con el cliente', 'Conjunto de actividades que se realizan al inicio del contacto con el cliente y que se ejecutan según la planificación de ventas', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('de73a61a-fcc0-481c-a899-30bb66710c76'::uuid, 'Intereses', 'Silo Control: Costo financiero por el uso de dinero prestado, o el rendimiento generado por prestarlo.', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('35937657-9640-4a2d-97b9-78eddf1137be'::uuid, 'Intereses / Ganancia operativa', 'Ratio que indica la capacidad de la empresa para cubrir sus pagos de intereses con su ganancia operativa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('43d8ae39-2d9b-4805-bd98-9e93acc5a2a8'::uuid, 'Intereses sobre cesantías', 'En Colombia, compensación financiera que se paga anualmente al empleado sobre el valor acumulado de sus cesantías, como reconocimiento por el uso que hace la empresa de esos recursos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2b6079e7-9678-4cce-a2b3-38c8ebdab75e'::uuid, 'Interés de mora', 'Tasa de interés que el proveedor cobra debido al vencimiento de los documentos por pagar generados en las transacciones de compra.', 'Interés Mora', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:42:42.747Z'::timestamptz),
  ('5bd88f67-1138-4455-9c8f-78a370219935'::uuid, 'Inventario', 'Silo Control: Representa el valor de las mercancías disponibles para la venta. La gestión de inventario busca equilibrar la disponibilidad del producto con el costo de mantenerlo. Silo Logística: Registro detallado de las existencias de productos en un almacén, incluyendo cantidades, ubicaciones y estado. Reporte SIM – Indicador Compra: Sumatoria de la Columna Inventario en moneda local o dólar dividido entre el número de meses consultados (Se tomarán en cuenta los inventarios al cierre de mes y el último inventario registrado para el mes actual).', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 3 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('4831f25f-e9da-440e-9ad8-1327c41eeff6'::uuid, 'Inventario de seguridad', 'Cantidad extra, en meses, de mercancía almacenada para protegerse contra fluctuaciones inesperadas en la demanda o retrasos de proveedores, evitando así rupturas de stock y mejorando la satisfacción del cliente. Se calcula considerando la variabilidad del tiempo de entrega y ventas, esencial para la continuidad operativa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('de688085-12c9-4b3f-ae82-f7275c18c156'::uuid, 'Inventario físico', 'Conteo real y físico de todos los artículos existentes en bodega.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('48e63bc3-0160-4113-ac4a-3c0e714062f3'::uuid, 'Inventario inicial', 'Proceso para registrar el inventario en el sistema sin necesidad de documento de entrada, generando un ajuste de entrada.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e9e1ea5d-1147-45aa-a489-f7d608b42bce'::uuid, 'Inversiones', ' Se considera inversión la adquisición de mobiliario o activo fijo para la empresa.', 'Inversión', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:42:44.920Z'::timestamptz),
  ('51a513d6-9e4a-4af0-9fbe-17297c35d7cf'::uuid, 'Isotipo', 'Se refiere a la parte icónica y de mayor jerarquía del Logotipo. El infinito se refiere a una cantidad sin límite ni fin.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('97758713-2d22-483f-b374-b500a5e13eeb'::uuid, 'Iva atrapado', 'Suma de los montos de IVA (Impuesto al Valor Agregado) que la empresa ha pagado a sus proveedores, pero que aún no ha podido deducir del IVA que debe al fisco por sus propias ventas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5a261a82-4c07-40f3-a368-ebd7a0b824b4'::uuid, 'Jerarquía visual', 'es una herramienta de comunicación visual que se utiliza para contar la historia o definir las características de un sujeto (marca, persona, concepto) de una manera gráfica, concisa y memorable.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8c5d702e-287e-42f8-944c-65abf43a2fba'::uuid, 'Justo a tiempo (JIT)', 'Justo a Tiempo es un sistema que impulsa las piezas a través de la producción según la demanda del cliente, en lugar de impulsarlas según la demanda proyectada. Esta técnica puede implementarse con la ayuda de diferentes herramientas Lean, como Flujo Continuo, Heijunka, Kanban, Trabajo Estandarizado y Tiempo Takt. Los resultados del Justo a Tiempo incluyen el equilibrio de la línea, el flujo de una sola pieza y un inventario de material excedente mínimo o nulo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('14d66810-5769-4b23-8e36-a47c46998b59'::uuid, 'Kaizen', 'Término japonés que significa "cambio para mejorar". KAIZEN™ es un enfoque gradual y a largo plazo para lograr cambios pequeños e incrementales en los procesos con el fin de mejorar la eficiencia y la calidad. KAIZEN™ fue popularizado por Masaaki Imai en su libro "KAIZEN™: La clave del éxito competitivo de Japón".', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ae825b7a-ae33-4dfa-97cc-7a365f765878'::uuid, 'Kamishibai', 'Kamishibai es una forma de contar historias originaria de Japón. Las tarjetas Kamishibai se utilizan, en el contexto empresarial, como control visual para realizar auditorías de procesos. El resultado de la verificación se muestra visualmente (verde/rojo).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0a1cb318-40f3-4eed-8d45-0e85fc660063'::uuid, 'Kanban', 'Una herramienta de planificación de necesidades de materiales en el sistema de producción y control de inventario "Just-in-Time" desarrollado por Toyota. Kanban se considera a menudo un elemento central de la fabricación eficiente y probablemente el tipo de sistema de señalización pull más utilizado. Kanban significa una señal visual (tarjeta Kan, señal Ban). Gracias al reabastecimiento automático (mediante tarjetas que indican cuándo se necesitan más productos), se regula el flujo de mercancías con proveedores externos, dentro de la fábrica y con los clientes. Este sistema se denomina "Kanban".', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5826d8cf-24e1-402d-8aeb-7be8424085f9'::uuid, 'Kata', 'Kata significa rutina o patrón de comportamiento. El término Kata, en el ámbito KAIZEN™, se refiere a dos comportamientos: Kata de Mejora y Kata de Coaching. El Kata de Mejora es una metodología de cuatro pasos mediante la cual una organización mejora y se adapta. El Kata de Coaching es la rutina mediante la cual líderes y gerentes guían el proceso de mejora del Kata.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('31f89921-971d-4b2d-9908-1246fc37a810'::uuid, 'Kit', 'Es un conjunto de artículos o herramientas necesarias para un propósito específico, generalmente incluye todo lo necesario para completar una tarea o actividad. Los kits son prácticos y están diseñados para proporcionar una solución integral, requieren embalaje y a nivel de facturación se refleja en una sola línea con un código único.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e5af349d-9220-4362-83f5-2d73b6850dbd'::uuid, 'Kobetsu kaizen', 'La palabra Kobetsu proviene de Japón y significa "enfocado", y Kobetsu KAIZEN™ se refiere a un KAIZEN™ enfocado. Es una metodología estructurada de resolución de problemas que se utiliza para lograr diversos objetivos, como reducir defectos o errores, costos y plazos de entrega; aumentar la productividad o la seguridad en el puesto de trabajo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('33dcb9c9-d1c9-4e79-8dc4-f10db46538d3'::uuid, 'KPI', 'Acrónimo en inglés de indicadores clave, los indicadores clave de un proceso o actividad determinada.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8448d68d-df03-489c-b2c7-c5b6180303d8'::uuid, 'Lead', 'es una persona o una organización que ha mostrado interés en el producto o servicio de tu empresa. Es un contacto que, de alguna manera, ha interactuado con tu marca y, por lo tanto, tiene el potencial de convertirse en un cliente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('26dc13e4-d303-4add-8f9f-48a72c07a3dc'::uuid, 'Lead Time', 'Tiempo total transcurrido en días, entre que se genera una orden y el inventario se encuentra disponible para la venta.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e335e2d9-89b7-4b21-9a0b-a4b9153d7f9e'::uuid, 'Legal', 'Área responsable de la gestión de asuntos legales de la compañía, incluyendo contratos, litigios y cumplimiento normativo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9d2e0a88-9483-407e-b0d3-769c5c4e813e'::uuid, 'Legibilidad', 'es la cualidad de un texto que permite al lector leerlo y comprenderlo con facilidad y rapidez. Es la facilidad con la que un lector puede distinguir las letras, las palabras y las oraciones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b73e829a-c2cb-4cc2-98bc-d5eb8b8cbc6a'::uuid, 'Letra de cambio', 'Una letra de cambio es un documento que se genera cuando dos personas físicas o jurídicas se comprometen a tener relaciones financieras entre sí, de modo que una preste dinero o bien ofrezca bienes o servicios a crédito y la otra se comprometa formalmente a pagar por ellos en el período de tiempo establecido.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fa8b47bf-43f9-4de0-9a25-eb8dbb4ce7aa'::uuid, 'Libro de compra', 'Registro auxiliar obligatorio donde se asientan cronológicamente todas las facturas de compras de bienes y servicios, clave para el control de costos y la liquidación de IVA.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('784b061e-fb03-4696-91a5-5a6bd9b470ea'::uuid, 'Libro de venta', 'Registro auxiliar obligatorio donde se asientan cronológicamente todas las facturas de venta emitidas, fundamental para el cálculo y declaración de impuestos como el IVA.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d9e8a4fd-2e2d-4f1f-8176-e65158f4e0c4'::uuid, 'Libro diario', 'Registro contable principal donde se anotan todas las transacciones de la empresa en orden cronológico.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('16641aa3-e9aa-4107-a58d-e23c0d423e3c'::uuid, 'Libro mayor', 'Registro que agrupa y resume todas las transacciones por cuenta contable, mostrando el saldo de cada una y permitiendo el análisis de movimientos específicos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('72289b36-acf1-41f2-bfc8-27a30eefe0bd'::uuid, 'Licencia', 'Permiso formal para usar, hacer o poseer algo (ej. licencia de software), cuya gestión es importante para el control de gastos y el cumplimiento legal.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e7b33b6d-f3a2-4a16-ad91-f9d6fbcc4f11'::uuid, 'Liquidación', 'Cálculo y pago de todos los conceptos adeudados al empleado al momento de la terminación del contrato de trabajo. Incluye salarios pendientes, vacaciones no disfrutadas, prima de servicios y, de aplicarse, indemnizaciones.', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:37:45.761Z'::timestamptz),
  ('2be78423-f27e-460b-9e2d-b2dd402d8b71'::uuid, 'Liquidación de prestaciones sociales', 'Cálculo del monto total adeudado al empleado por conceptos de beneficios acumulados según la ley del país (cesantías, antigüedad, etc.) al finalizar la relación laboral.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ed49d15e-fefe-4656-9e7c-23b8e6a792e6'::uuid, 'Lista de precio', 'Muestra las listas de precio creadas en la compañia.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('93c2192e-5604-4318-b8f3-a44609ecb7af'::uuid, 'Lista de precios', 'Listado de bienes o servicios emitido por un proveedor, que muestra, entre otras cosas, los precios correspondientes a cada bien o servicio.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4fd1c2c8-5d42-459c-ab70-049cb844b243'::uuid, 'Lista de precios - base', 'Es el catálogo de precios maestro que sirve como eje de cálculo para otras listas dependientes. Se caracteriza porque las actualizaciones de precios se realizan directamente sobre ella, afectando automáticamente a las listas que están vinculadas mediante factores o porcentajes.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('387c398e-e97f-4cce-a288-c6b215ffc0ee'::uuid, 'Lista de precios - independiente', 'Es una lista única que se crea de forma autónoma para responder a criterios comerciales específicos o necesidades de un cliente/grupo particular. A diferencia de la lista base, las actualizaciones de precios se realizan de manera directa sobre ella, ya que no depende de cálculos o factores derivados de otra lista.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7ded5450-52c3-4435-9212-ebfdbd68dc9a'::uuid, 'Litigio', 'Disputa o controversia legal llevada ante un tribunal para su resolución.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d87efcbd-a496-4bd9-b624-190f0c9c8a92'::uuid, 'Llave primaria', 'Atributo único y obligatorio que identifica unívocamente a un registro dentro de una tabla. Su función es evitar la duplicidad y permitir la vinculación precisa entre diferentes conjuntos de datos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e3c041fb-ddb8-4088-8876-4961c91d0df0'::uuid, 'LLM (large language model)', 'Modelo de IA entrenado con grandes cantidades de texto para generar y entender lenguaje humano (ej. ChatGPT).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('203ac07f-1298-4f6f-b771-3830027938cf'::uuid, 'Localización', 'Ubicación dentro de la bodega, que permite localizar más fácilmente dónde se almacena cada artículo. Las localizaciones pueden ser áreas, estantes, niveles, etc.', 'Localización', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:38:01.502Z'::timestamptz),
  ('9a81b99a-5128-4a90-8c7a-60aa64eec9c6'::uuid, 'Lockers', 'Casilleros asignados a colaboradores para almacenamiento personal, sujetos a normas de uso y revisiones aleatorias.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f3ee3788-8cdb-4889-b7aa-c443228cc09b'::uuid, 'Logotipo', 'es un símbolo gráfico o una marca tipográfica que se utiliza para identificar una empresa, producto, organización o marca. Es la piedra angular de la identidad visual de una marca, ya que es la primera impresión que muchos consumidores tienen de una empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('112199b3-1592-4657-96cb-d8d75b32ed20'::uuid, 'Los menús de radio', ' Pantallas de menú para los usuarios y poder escoger tareas a realizar. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('69f0079c-fc32-471f-83af-f1937b4688eb'::uuid, 'Lote', 'Corresponde a una tanda particular de fabricación, identificada por un número, para controlar el momento en que fue producido, el período de cuarentena del artículo, la vida útil y la fecha de expiración del mismo.', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-05T13:38:51.750Z'::timestamptz),
  ('25301206-6cc3-4a60-9330-6b05c6533ef8'::uuid, 'Lote Múltiplo', 'En este campo se ingresa el multiplo de venta del artículo en el proveedor.', 'Lote Múltiplo', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('835e7ca0-d43c-4f37-b34a-357c6e52e848'::uuid, 'Límite de crédito', 'Se refiere al monto máximo de crédito que un cliente tiene disponible', 'Límite Crédito', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:38:06.574Z'::timestamptz),
  ('9f66929e-9676-428b-873b-b7f387d2e987'::uuid, 'Líneas de extracto bancario', 'Cada una de las transacciones (débitos o créditos) individuales que aparecen en un extracto bancario y que se cargan a Sage XRT para su conciliación.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('42970bc1-953c-401b-8458-7d6d4fcdd594'::uuid, 'Machine learning (aprendizaje automático)', 'Tipo de IA donde los sistemas “aprenden” de datos, como cuando Netflix recomienda películas según lo que viste.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('eb8430aa-22e6-4006-a2a0-b9912965c028'::uuid, 'Macroproceso', ' Es un conjunto de Procesos interrelacionados que gestiona el funcionamiento de una parte determinada del negocio. Representado por una caja en el BPA. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('00b39fc8-29bf-4a66-9a61-8307236c3139'::uuid, 'Macroproceso de planificación', ' Es un esfuerzo organizacional disciplinado y bien definido que apunta a definición de los planes estratégicos, operativos y presupuesto de una empresa, abarcando (según aplique) los niveles de empresa, de negocio, y funcionales, y asignando responsabilidades para su ejecución coordinada.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6fe03a4e-37dc-4582-8011-e1a950292c39'::uuid, 'Macroprocesos prioritarios', ' Macroprocesos ordenados por cantidad de horas hombre decreciente, que suman el 80% superior del total. Macroprocesos con riesgo a las personas,  legal, fiscal o que detienen la operación. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('654bc61b-5157-4e45-a7ec-d4497ea2778d'::uuid, 'Macroprocesos relacionados', ' Sirve para especificar aquellos macroprocesos que tienen relación alguna con el macroproceso desarrollado. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('16307ef0-ea94-4f0d-a55c-0ee9e70f650d'::uuid, 'Madurez de procesos', ' Escala establecida para definir la evolución de la madurez de procesos de una empresa. En la escala se establecen los pasos que deben ser completados para ir incrementando el valor del indicador.  ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e7ac4ff5-2eff-45df-b1bb-a5bb3a794dcd'::uuid, 'Magnitud Comercial', 'Valor numerico para unidad de medida comercial.', 'Magnitud Comercial', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('e73a283b-5905-41d2-917f-0678dbf7f1c3'::uuid, 'Mantenimiento preventivo', 'Actividades planificadas para garantizar el funcionamiento óptimo y seguro de equipos e instalaciones', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('47a8ff3a-93d3-4198-bd64-390252f65f2a'::uuid, 'Mantenimiento productivo total (TPM)', 'TPM es un enfoque holístico del mantenimiento que se centra en el mantenimiento proactivo y preventivo para maximizar el tiempo de funcionamiento de los equipos. TPM difumina la distinción entre mantenimiento y producción, poniendo un gran énfasis en capacitar a los operadores para que ayuden a mantener sus equipos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('bbee356f-1dfd-4325-8e89-a33211b6fb40'::uuid, 'Manual', ' Es un documento que presenta un compendio de reglas y estándares a seguir para el cumplimiento de unos lineamientos o algo en particular. Señala el procedimiento a seguir para lograr el trabajo de cualquier grupo que desempeña responsabilidades específicas. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('25333962-747f-4cea-9408-90be09753796'::uuid, 'Manual de marca', 'Es un documento fundamental que contiene las normas, reglas y directrices sobre cómo se debe aplicar la identidad visual y el mensaje de una marca.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('782c52a6-b200-4d2e-8b4f-ddc5d0bbce9a'::uuid, 'Mapa de objetivos', ' Es un gráfico (red) que define los objetivos de la empresa y las relaciones causales entre ellos, clasificados según cinco perspectivas básicas (BSC:  Balance Score Card). ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2f94faf2-f509-41d1-a9da-c587a607152b'::uuid, 'Mapa de procesos', 'Representación gráfica de los procesos de una organización y sus interrelaciones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4274c2f7-47d5-428b-91dd-5eac64fb3b3c'::uuid, 'Mapa de reconocimiento', ' La información contenida en este mapa es una recopilación de información existente en la Compañía que permite conocer el marco de acción a fin de mantener alineados los procesos de acuerdo con la razón de ser de la compañía.  Esto incluye  Misión, Visión, Valores, Oferta de Productos y Servicios, Competencia, entre otros. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('bf8583b8-c2b9-4d7b-ad36-8a20d0eb41cd'::uuid, 'MAPE', 'Promedio de errores absolutos porcentuales.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('45963a0d-d557-41da-91b4-383de61e01ed'::uuid, 'Mapeo del flujo de valor', 'Se crea una imagen visual del estado actual o cómo fluyen los materiales y la información desde los proveedores, pasando por la fabricación, hasta el cliente. Se miden el plazo total de entrega, los tiempos de ciclo del proceso y los tiempos de valor añadido. El estado futuro se crea con base en los objetivos deseados, las condiciones del mercado y la planificación estratégica del negocio.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('31d1da51-22d1-4d81-9e5c-85d3f5ac8bb4'::uuid, 'Maqueta', 'es un modelo a escala, un prototipo o una representación física o digital de un producto, una página web, un empaque o cualquier otro proyecto. Su propósito principal es visualizar una idea de forma tangible y permitir la exploración, la prueba y la comunicación antes de la producción final.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('199b6151-3a75-43c8-947a-de02a29f4159'::uuid, 'Marca', 'Se refiere a la cartera de marcas que comercializa la compañía sin importar el proveedor.', 'MARCA', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('7cf192de-073b-4068-bd7a-e6a6cd6321f1'::uuid, 'Marchamo', 'Etiqueta o sello que garantiza la integridad del producto durante su transporte o almacenamiento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4da7aa52-cfe3-4e7d-a58d-079747d456ba'::uuid, 'Margen', 'Indicador porcentual de la contribución sobre las ventas netas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('63d3b1b1-4d0a-4444-90dc-da82f401f7c8'::uuid, 'Margen con rebates', 'Silo Control: Es el margen de contribución después de considerar el efecto de los descuentos o bonificaciones (rebates) acordados con clientes o proveedores. Reporte SIM – Indicador Compra: Margen de contribución total sobre las ventas netas.', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('890f7aac-83da-4cc7-ab4c-79ecbb5550be'::uuid, 'Margen mínimo', 'Se refiere al valor mínimo de margen aceptado para el artículo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('31cd216f-3518-4e41-ac26-aee854f78690'::uuid, 'Margen neto', 'Indicador de rentabilidad final. Se calcula como (Utilidad Neta/Ventas Netas)×100. Muestra el porcentaje de cada dólar de venta que se convierte en ganancia neta.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('43723a6d-1ef6-4986-a99a-f49c58ea9286'::uuid, 'Margen total', 'Margen de beneficio final después de considerar todos los costos directos, rebates y otros descuentos', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('dbacd453-681c-4caf-8e30-2842e4716473'::uuid, 'Marketing de contenidos', 'La creación y distribución de contenido relevante (blogs, videos, podcasts, etc.) para atraer y retener a una audiencia.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f904ba40-0922-4faf-a71d-9bba5871b4c8'::uuid, 'Material', 'El componente o sustancia principal de la que está hecho un artículo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d263761c-c58f-4f3f-bc06-975d6bbe77d3'::uuid, 'Materiales en proceso', 'Estos son materiales y componentes sobre los que se efectúa un trabajo o que se encuentran esperando en la fábrica entre una operación y otra.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f9be7032-a9eb-40fd-b654-9f2b0ec7e09c'::uuid, 'Materias primas', 'Materiales como acero, harina, madera, telas u otros utilizados para elaborar productos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fd462e1b-7149-4c8c-b067-5be132f2d700'::uuid, 'Matriz de deuda financiera', 'Archivo o documento de control donde se registra y monitorea detalladamente toda la información de los préstamos y financiamientos de la empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e2a2c510-7926-45da-9705-9825fe03c89b'::uuid, 'Matriz de documentación', 'Tabla que organiza los documentos por tipo, área, responsable y estado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e9ea663c-4239-414c-a2df-ed642742f22b'::uuid, 'Matriz foda', ' Es una matriz de doble entrada en la cual se incluye los resultados de los análisis  de Fortalezas, Debilidades (Escrutinio Interno), Oportunidades y Amenazas (Análisis Externo). ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e1ae85ad-7ac8-4a0a-8ddd-8c5df533867f'::uuid, 'Mayorizar', 'Trasladar las transacciones contables del diario al mayor.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7387937d-40fc-4d3f-a6e3-0cbdc0a2cf5a'::uuid, 'MCG', 'Mayoreo Compras Global', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('25685a44-42b0-49a4-809c-75f26ac4a670'::uuid, 'Media estiba europea', 'Tipo de estiba que corresponde a la mitad del pallet europeo estándar (EUR/EPAL). Medidas: 80 × 60 cm. Nombre Internacional Oficial EPAL 6 / EPAL 7 / Display Pallet', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2deb8cbd-6a41-4f1d-abab-e114b60d1fc1'::uuid, 'Medida (measure)', 'Cálculo que se hace sobre los datos, como suma de ventas, promedio de edad o porcentaje de crecimiento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('371e3521-83ea-4633-b1c7-7ee1cf9d28a4'::uuid, 'Medio de pago', 'Muestra las herramienta o métodos de pago que utiliza la compañia.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2dea99c8-8cde-4640-bcae-d8c1dc37509d'::uuid, 'Medio de transporte', 'Cualquier vehículo (buque, aeronave, vagón ferroviario, etc.) utilizado para el transporte de personas o mercancías.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6a437518-d809-4e64-b5b3-af9a40bd83e4'::uuid, 'Mejora continua', 'Proceso sistemático y recurrente de evaluación y optimización de procedimientos, normas y sistemas para aumentar la eficiencia, seguridad y calidad de forma constante.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e51e4332-4e3a-411b-9fd6-c62ed14d33cc'::uuid, 'Meta', 'Silo Control: Valor objetivo a alcanzar, que en un entorno de control y Kaizen, a menudo se define como cero errores u operación bajo condiciones óptimas. Reporte SIM – Indicador Venta: Es el monto a alcanzar de la venta neta asignado por vendedor. Sumatoria de la columna Meta en moneda local y dólar. venta del cliente activo de los últimos 6 meses * meta del vendedor.', '', 'dudoso'::estado_origen_termino, 'Se fusionó el concepto genérico de control/Kaizen (valor objetivo, cero errores) con la fórmula específica de meta de venta por vendedor. No se contradicen, pero también podrían tratarse como homónimos.', false, NULL, false, false, NULL, '2026-10-02T01:38:13.200Z'::timestamptz),
  ('a2cdb2d1-66e2-4dcd-ac22-ca718ad28d5a'::uuid, 'Metadatos', 'Información estructurada que describe el contenido, autoría y contexto de un documento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('965644de-d300-45b2-8ea1-6dc47580201a'::uuid, 'Metodología de cambio', ' Es herramienta que nos permita manejar el proceso de cambio y la gestión de Procesos de Negocio, de forma eficiente y ordenada. La metodología consta de 5 fases:  Alineación, Diseño, Construcción, Implementación y Adopción. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('16fe83b5-c5ec-4fd6-818a-fe9abc5d05a7'::uuid, 'Milkrun', 'Un método de organización del transporte en ciclos estandarizados en el que un vehículo pasa por varios puntos de recogida/entrega con una frecuencia fija. Funciona como una línea de metro que cumple horarios fijos con frecuencias determinadas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('72d300e0-f652-4f9d-820e-2b95e38f3e38'::uuid, 'Miniatura', 'es una versión en tamaño reducido de una imagen, un video o un documento. Funciona como una vista previa que permite a los usuarios identificar rápidamente el contenido antes de hacer clic para verlo en su tamaño original.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fbebe421-180b-4c84-80d8-22c6f8d56d51'::uuid, 'Mizusumashi (araña de agua)', 'Una persona que gestiona toda la logística de transportar componentes, materias primas, etc., en pequeñas cantidades a las estaciones de trabajo para minimizar los inventarios de productos en proceso. Esto permite ubicar las máquinas más cerca y evita que el operador tenga que interrumpir su ciclo, minimizando así los costos de transporte. Los operarios de agua suelen ser trabajadores con experiencia. Saben dónde se almacenan las piezas o materias primas necesarias y prestan servicio en varias estaciones de trabajo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('87e13e39-c07e-4d2e-8645-4382dd48cfe2'::uuid, 'Mockup', 'es una representación visual realista de cómo se verá un producto o un diseño en su contexto final. No es el producto terminado, sino una vista previa de alta fidelidad que ayuda a visualizar y comunicar una idea de forma profesional.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3c9d2c50-b8a2-4ae7-96ad-ce337ceed630'::uuid, 'Modelado financiero mandatorio', 'Política de control que exige un análisis financiero riguroso (VPN, TIR) para todas las inversiones que superen un umbral definido, garantizando decisiones basadas en datos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('aa2c57fd-0f99-4dce-a4ab-21d9c5f3e3ad'::uuid, 'Modelo de datos', 'Estructura que organiza cómo se relacionan las tablas y datos en un análisis.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fe681876-2a14-42db-ab19-e9007a827d22'::uuid, 'Moneda alterna', 'Una segunda moneda utilizada en el sistema contable para registrar transacciones, permitiendo la reportería en diferentes divisas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7893c509-a892-4e32-9f51-f083d41bb2a9'::uuid, 'Moneda del documento', 'La divisa específica en la que se emite y registra una transacción o documento (ej. una factura en USD o EUR).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('271d15fc-ba22-498c-977d-67e811ddd36b'::uuid, 'Monitor de conciliaciones', 'Desarrollo a medida para monitorear el ciclo de vida de los recibos de cobro y anexos de depósito, desde su creación hasta su correcta aplicación en el ERP.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c7c4c80d-d9cc-42d0-a68c-4fc28fee3d9c'::uuid, 'Montos', 'Tipo de condición de pago en el que se definen manualmente los montos de cada pago.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('42bec33e-04aa-4189-affa-4ae279a9d522'::uuid, 'Motoparte', 'Son todos aquellos componentes que forman parte del sistema de una motocicleta.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3b5c8976-14c4-47c4-9bf7-0286c9e4a480'::uuid, 'Movilidad (Personal)', 'Silo Personal: Cambio de puesto o área de un colaborador dentro de la organización, que puede ser horizontal (rotación) o vertical (ascenso o descenso). Reporte SIM – Dimensión Personal: Cambio de puesto o área de un colaborador dentro de la organización, que puede ser horizontal (rotación) o vertical (ascenso o descenso), de acuerdo al esquema establecido.', '', 'homonimo'::estado_origen_termino, 'Se separó de un término homónimo compartido con: Movilidad (Transporte).', true, NULL, false, false, NULL, '2026-09-28T16:05:00.000Z'::timestamptz),
  ('11009e0a-52bf-480c-a628-0458e7da2c62'::uuid, 'Movimientos bancarios en espera', 'En Sage XRT, se refiere a las líneas del extracto bancario que han sido cargadas y están pendientes de ser conciliadas contra un movimiento interno.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6aa5c15c-e53c-4ee5-98b2-eefad8a4cebb'::uuid, 'Movimientos en bancos', 'Son todos aquellos movimientos o transacciones dentro de la cuenta bancaria que el banco ha reportado', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('bd161ab5-aae9-4443-972a-96dcbfce8f30'::uuid, 'Movimientos en libros', 'Son todos aquellos movimientos o transacciones dentro de la cuenta bancaria que se han registrado dentro de la empresa como parte de su funcionamiento cotidiano (información que se lleva en el módulo de Control Bancario de Softland).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('861d11ae-dea8-4d67-9da7-d909cdd2ddf7'::uuid, 'Muda', 'Palabra japonesa para desperdicio y un concepto clave en el TPS como uno de los tres tipos (muda, Mura [irregularidad o desigualdad] y Muri [tensión]) de desviación de la asignación óptima de recursos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('404a017b-4132-4ab0-a337-bdda6cc4ba54'::uuid, 'Muda walk', 'Un recorrido por el gemba para observar evidencia de lo que podrían ser diversos tipos de Muda. El objetivo de este recorrido es mostrar que el gemba está repleto de datos y oportunidades de mejora para quienes están entrenados para verlos. Los recorridos de muda no buscan generar oportunidades para culpar ni encontrar fallos. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('83483a13-3a30-4b27-a01a-5bf0f6466703'::uuid, 'Muelle', 'Hace referencia a la asignación de la ubicación destino de la mercadería alistada para una orden de expedición.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b6f1c6a8-f6f4-478d-b8c6-a97fa3b7d11f'::uuid, 'Multimodal', 'Es la articulación entre diferentes modos de transporte, a fin de realizar más rápida y eficazmente las operaciones de trasbordo de materiales y mercancías.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('71289ec9-3d91-4db9-ac8d-4b9a5bd0d265'::uuid, 'Multiplo de venta', 'Unidad de medida en la que se vende el artículo.', 'Múltiplo Venta', NULL, NULL, false, NULL, false, false, NULL, '2026-09-30T20:00:00.000Z'::timestamptz),
  ('2fcd5605-ae7c-4cdd-a4a4-294d7ecc9fff'::uuid, 'Método de actualización (inventario)', 'Define cómo se actualizará el inventario después del conteo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0715f5b8-e3fa-4e94-90ad-8cb41cfa00da'::uuid, 'Módulo de carga camión', 'Módulo del sistema eflow-WMS cuyo objetivo es certificar que se cargue lo que se alistó.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('972bc2a5-bf6d-476d-aecd-37dc0666b5f8'::uuid, 'Módulo de Control de Inventario (CI)', 'Es el corazón de las actividades de manufactura del sistema, ya que integra todos los movimientos transaccionales relacionados con consumos, ventas, ingresos, etc.. Permite a la empresa registrar y controlar los movimientos de mercadería, tanto interna como de importaciones, y maneja la información que relaciona a cada proveedor con los artículos, para el establecimiento de puntos de re-orden y pedidos. Este módulo tiene como objetivo principal el manejo de los artículos y las acciones que se presenten sobre su desempeño.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7edf53c0-a3c4-4cf4-98bb-0755765589e2'::uuid, 'Módulo de expediciones', 'Módulo del sistema eflow-WMS cuyo objetivo es facilitar los procesos de ejecución relacionados con la preparación de pedidos y el despacho.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3e6008f6-10e4-43d3-bd74-57bfdc32e638'::uuid, 'Módulo de recepciones', 'Parte vital de la cadena de abastecimiento, ya que es el inicio del proceso de trazabilidad de mercadería en el almacén.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fd7032c4-5deb-4858-9659-4cec34d24a38'::uuid, 'Módulo de seguridad', 'Opción del sistema eflow WMS donde se administran todos los usuarios y los menús a utilizar según los permisos correspondientes al perfil de trabajo, permitiendo brindar o restringir accesibilidad.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a626dd44-5e92-474e-ba6e-3ad9fd54f28c'::uuid, 'Módulo de toma física', 'Permite realizar conteos selectivos de forma versátil a un grupo específico o a la totalidad de los SKUs en inventario, con actualización en tiempo real.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d356850e-327c-4823-9960-448b8a2e838b'::uuid, 'Módulo eflow-wms', 'Un módulo del sistema que describe una serie de procedimientos para realizar ajustes de inventario, facilitando la capacitación del usuario en cada proceso dentro del CEDI.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c0abdd24-bed8-41a3-b9f3-e96380134084'::uuid, 'N.I.T (número de identificación tributaria)', 'Código único asignado por la autoridad fiscal para identificar a cada contribuyente. Indispensable para toda documentación legal y fiscal.', 'Contribuyente (RIF/NIT)', NULL, NULL, false, NULL, false, false, NULL, '2026-09-30T19:30:00.000Z'::timestamptz),
  ('fde6f994-cfe0-4443-8075-e213405cefe2'::uuid, 'Naturaleza', 'Origen o la relación de la marca del producto con la empresa, refleja la clasificacion establecida por la compañia: Propia, exclusiva o distribuida.', 'NATURALEZA', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('2fde72d0-dc75-4481-b69d-a5fcbbaeff2c'::uuid, 'Nicho de clientes', 'Refiere a un conjunto de clientes que se encuentran dentro de una combinación de Segmentos. Los nichos pueden ser usados para combinar estrategias, o realizar análisis comercial. Los nichos no están descritos específicamente, y su denominación queda a discreción de los usuarios de este documento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f0ae4996-e7c7-4b4f-83f4-1ad4649d3192'::uuid, 'Nivel', 'Muestra las jerarquías establecidas por la compañia que describen el puesto del colaborador dentro de la estructura organizacional (ej.: operativo, supervisor, gerencial, directivo).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c55ef00b-3f17-4cbf-b531-534ae742aef2'::uuid, 'Nivel de servicio', 'Es un indicador que mide la capacidad de una empresa para satisfacer las demandas de sus clientes. En términos más simples, es la probabilidad de que un cliente reciba el producto o servicio que necesita, en el momento que lo necesita y en la cantidad requerida.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('60ce0431-901f-4a94-bfc0-198872b4cfba'::uuid, 'Nivel organizacional', 'Jerarquía o estrato que ocupa un puesto dentro de la estructura organizacional (ej: operativo, supervisor, gerencial, directivo).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a8a5606e-c1ff-49a8-8908-00e2f11fe255'::uuid, 'Niveles de la arquitectura de procesos', ' Existen 3 niveles:  Comprensión, Evolución y Normalización. A) El nivel 1 de Comprensión donde se elabora el Mapa de Reconocimiento que será fuente de información para la elaboración del BPA. El BPA que nos permite tener una visión general de los procesos que operan en la empresa. B) El nivel 2 Evolución, inicia con el desarrollo de los macroprocesos al nivel de procesos o actividades. En este nivel se generan los cambios necesarios para la mejora continua de nuestros procesos. C) El nivel 3 Normalización, es el nivel donde desarrollamos a nivel de tarea nuestros macroprocesos, ya que en este nivel llegamos al máximo nivel de detalle de información donde se muestra quién hace qué en la operación. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('39ca2b0d-0cd1-43d4-919b-c762435ba5aa'::uuid, 'NLP (procesamiento del lenguaje natural)', 'Tecnología que permite que las computadoras entiendan y respondan en lenguaje humano (ej. Siri, ChatGPT).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a8e5ae9b-406d-42bb-8564-a5ada7dc9a29'::uuid, 'No conformidad', 'Desviación respecto a un requisito establecido en el proceso.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a7bc28e1-ce3c-43d6-bda9-ac9ac6755124'::uuid, 'No disponible para la venta (P2)', 'Determina que la mercancía no se ve disponible en los canales de venta.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('db653250-a2c3-4d16-b1e2-5ae8d7ffa9bc'::uuid, 'Nombre del asiento', 'Nombre o código identificador de cada asiento. ​ Este campo acepta caracteres alfanuméricos. ​ Debe ser un identificador único.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d8cfc057-de09-4fe5-aa78-57295a011fac'::uuid, 'Nombre del paquete', 'Es el nombre del paquete en uso en el que está ubicado un conjunto de asientos. ​ Normalmente está intrínsecamente relacionado con los tipos de asiento que contiene, a menos que esté orientado de cara al personal que lo opera. ​', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('242cbf9f-1bdd-42ee-92ee-940e8f71a7a2'::uuid, 'Norma', ' Documento que permite describir lineamientos establecidos por la Organización, que se definen para el cumplimiento de todos los Colaboradores o de un área en particular, así como los pasos a seguir para cumplirlas. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7c96bf44-a398-4491-aedc-a6979957f2ef'::uuid, 'Normalización', 'Proceso de elaboración, edición y aplicación de normas que simplifican y estandarizan actividades.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2d034385-53b2-42fc-a367-2c84c569f56d'::uuid, 'Nota de crédito', 'Documento fiscal que reduce el saldo de un cliente. Se utiliza para anular facturas, registrar devoluciones de mercancía o aplicar descuentos post-facturación.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('80e3e0cb-639b-40cc-9d1e-2e444c432819'::uuid, 'Nota de crédito u otro crédito', 'Para el funcionamiento del módulo de Cuentas por Cobrar, una nota de crédito u otro crédito son documentos que se emiten para hacer constar que un cliente ha realizado un abono a su saldo pendiente.Al emitir una nota de crédito se da conocimiento del monto que la empresa va a deducir de la cuenta que el cliente tiene pendiente. Es por esta razón que las notas de crédito y los otros créditos disminuyen el activo de la empresa, dado que producen una reducción en las cuentas por cobrar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('97246305-5558-40a3-beaf-449a6f5bf995'::uuid, 'Nota de débito', 'Documento fiscal que incrementa el saldo de un cliente, por ejemplo, para corregir un error en la facturación original o cobrar intereses de mora.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b5c022be-79e2-48a1-9481-1ad712f8d00a'::uuid, 'Nota de débito u otro débito', 'Para el funcionamiento del módulo de Cuentas por Cobrar, una nota de débito u otro débito son documentos que se emiten para hacer constar que un cliente le debe dinero a la empresa, por un monto determinado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1deafde3-b641-4e85-937e-7445d4e5e646'::uuid, 'Notificación de despido', 'Comunicación formal por escrito por parte del empleador al empleado, informando la decisión de terminar el contrato de trabajo. Debe ajustarse a los requisitos legales de cada país.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4f916722-8b46-415f-91d5-4d8059827ef2'::uuid, 'Nómina', 'Conjunto de procesos administrativos y financieros relacionados con el cálculo y pago de las remuneraciones, deducciones y aportes legales de los empleados.', 'Nómina', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:42:45.952Z'::timestamptz),
  ('dde95473-83f2-4a90-a193-4d5fb0627eec'::uuid, 'Número de revisión', ' La primera versión de un documento será identificada con el número 0. Luego las modificaciones que se realicen al mismo, serán registradas con el número correlativo siguiente. Ej. Rev.0, Rev. 1, Rev. 2. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('696217be-952c-497b-a2f7-5b5d3e6f48d8'::uuid, 'Número decimal', 'Tipo de dato que representa valores numéricos con precisión decimal. Es el estándar obligatorio para montos financieros, precios, tasas de cambio y medidas de peso o volumen.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('df6334a2-732d-48fd-9569-eaa08ef78ed2'::uuid, 'Número entero', 'Tipo de dato que representa valores numéricos sin componentes decimales, ya sean positivos o negativos. Se utiliza habitualmente para conteos de unidades, cantidades de artículos o IDs numéricos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b63b0bc8-9132-4a92-9946-f68b470a0570'::uuid, 'Objetivo', ' Establecer criterios que definan el propósito general del proceso, actividad o tarea. Debe describir de manera clara el “Porque” y el “Que”, centrándose en aquellos aspectos que lo hace único, debe ser entendible por todos. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL)
ON CONFLICT DO NOTHING;

INSERT INTO terminos (id, termino, definicion, campo_softland, estado_origen, nota_origen, revisado, nota_decision, es_nuevo, editado, eliminado_en, actualizado_en) VALUES
  ('8bbc8045-534a-444e-9182-b79740522f2e'::uuid, 'Obsolescencia', 'Estado en el que un documento ya no es vigente ni aplicable.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a6e5ffa2-1375-4795-9d2b-5fdf3189c88f'::uuid, 'OC', 'Orden de compra', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('51c67093-938d-466d-9304-d7a6e6feb924'::uuid, 'OC por recibir', 'Silo Control: (Órdenes de Compra por Recibir) Se refiere a los productos que ya han sido ordenados a un proveedor pero que aún no han ingresado físicamente al inventario de la empresa. Reporte SIM – Indicador Compra: Cantidad de OC en tránsito más backorder que no han sido recibidas por el almacén.', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('7c5be820-67eb-4cae-aee5-7472e456ef88'::uuid, 'Ofrecimiento de productos', 'Conjunto de actividades para impulsar productos, que incluye la presentación de promociones y la revisión del historial de artículos del cliente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ff98363f-b080-4832-ad65-5acbd8653c52'::uuid, 'OLA´s', ' “Operation Level Agreement”. Acuerdo Interno de Servicio, es el acuerdo formal que se realiza entre dos partes internas de la compañía para definir la entrega de un servicio. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f2b5bfcd-0316-4d6b-86fd-3f14a9620a04'::uuid, 'Omitir (en picking rf)', 'Ordena que la línea de picking se coloque al final de la secuencia.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('108089ed-9a8e-47ec-a36e-2c45a5d22242'::uuid, 'Opciones de segmento', 'Posibles nombres o campos que se le puede asignar a un Segmento, en una determinada línea de negocio. Por ejemplo, en Ferretería, un Tipo de Negocio es una Ferretería General. Un cliente puede aplicar para varios Opciones de un Segmento, y aplicaría dentro de los Nichos que aplican en la combinación de Segmentos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5de2451a-e107-4a8a-9c5d-15d3773d2ee9'::uuid, 'Orden de compra', 'Documento en el sistema que compromete a la empresa con un Tercero.', 'Orden Compra', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:42:47.074Z'::timestamptz),
  ('49f88bfd-59f5-47c8-8e72-1915f0928a70'::uuid, 'Orden de expedición', 'Documento generado por el ERP que indica los artículos y cantidades a preparar para despacho.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('cc94069a-a9be-49d9-928e-a14012570b62'::uuid, 'Orden de recepción', 'Documento que registra la entrada de mercadería al CEDI.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6d7749e5-0a6b-4319-94d9-76ee18e5bcd1'::uuid, 'Orden de ruta', 'Indica si la ruta de picking es lineal, zigzag o por fragilidad.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3aecde29-0e10-4273-be74-4d633310b05a'::uuid, 'Orden multinivel', 'Corresponde al orden en que se realizará el recorrido del almacenamiento, ya sea por nivel o por columna.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f75b11fd-6312-49cc-a239-bead1e8d4b2c'::uuid, 'Orden mínima', 'Cantidad mínima de pedido que acepta un proveedor. En el sistema, la orden mínima se establece en la moneda local del proveedor.', 'Orden Mínima', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('8960252d-2284-47ee-ada3-0927cbbfeae6'::uuid, 'Order plan streamline', 'Plan de compras generado por el software Streamline, basado en pronósticos de demanda, que se utiliza para estimar futuras salidas de efectivo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e1c09b09-15e6-4000-a408-449e0bdb429f'::uuid, 'Organigrama', 'Representación gráfica de la estructura organizacional de la empresa, que muestra los cargos, las relaciones jerárquicas, las líneas de reporte y las dependencias funcionales.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('18ee3b43-b6dc-46ee-a491-070865869011'::uuid, 'Origen', 'Reporte SIM – Dimensión Compras: Muestra los países que represntan el origen de la compra de mercancía del proveedor. Reporte SIM – Filtro Logística: Permite filtrar por uno o mas países el origen de la compra de mercancía del proveedor.', 'ORIGEN', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('8c05d3c8-cea0-4537-9f9e-e76ffa96360a'::uuid, 'Otro crédito', 'Documento interno que disminuye el saldo de una cuenta por cobrar (activo) para ajustar saldos a favor del cliente, sin ser un documento fiscal.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f0f43978-c412-406e-b69a-510a48ada645'::uuid, 'Outbound marketing', 'se refiere a cualquier estrategia en la que una empresa inicia el contacto y empuja su mensaje a una audiencia, sin que esta lo haya solicitado. La característica principal es que la comunicación va del negocio al consumidor, y no al revés.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8a70b61b-e229-4091-a499-90161c8ce90d'::uuid, 'Overfitting / Underfitting', 'Problemas en el entrenamiento de modelos: cuando aprenden demasiado de los datos de prueba (overfitting) o aprenden muy poco (underfitting).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('98d51ccf-1c1c-47d7-91f4-f66a804a99f8'::uuid, 'OyM (organización y métodos)', 'Área responsable de revisar, aprobar y divulgar normas dentro de la empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('09994c7c-0348-40fa-8c27-f54f62c411d5'::uuid, 'Packaging', 'Es el proceso de diseñar y producir el envoltorio, la caja, la botella o cualquier otro contenedor de un producto. Es el punto de contacto final entre la marca y el cliente en el punto de venta, y su papel va mucho más allá de simplemente proteger el producto.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d54144ed-a533-4b23-92a6-38d9deda8f61'::uuid, 'Pago', 'Proceso de liquidación de una obligación financiera con un proveedor o acreedor.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('11dc59ef-9e86-4bbf-87ea-760049204bcd'::uuid, 'Pago a proveedores', 'Proceso administrativo y financiero para saldar las deudas con proveedores por los bienes y servicios adquiridos, clave para la gestión de tesorería y relaciones comerciales.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2f6bb46b-7092-41ea-8d7b-7aa3fa38460f'::uuid, 'Pagos urgentes', 'Pagos que se procesan fuera del ciclo normal debido a una necesidad crítica del negocio. Deben ser excepcionales, estar debidamente justificados y aprobados por una Firma Autorizada para mantener el control.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('390ee84b-8b44-4fb3-8197-3546465a4259'::uuid, 'Palet', 'También conocido como pallet o tarima, es una plataforma rígida, generalmente de madera, plástico o metal, utilizada para apilar, almacenar, manipular y transportar mercancías de manera segura y eficiente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('dcb9d3dc-1214-4827-9d7f-921eb246c982'::uuid, 'Palet multi-artículo', 'Tipo de contenedor que permite agrupar múltiples artículos en una sola unidad de almacenamiento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('dea5968c-d713-4292-9eba-a388b98e84f4'::uuid, 'Paletizado', ' Cantidad de cajas que componen un pallet estándar. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9b60c14b-b38f-42d4-8ce1-9dbdc056001b'::uuid, 'Pantone', 'es una empresa mundialmente reconocida por su sistema de correspondencia de colores. En lugar de ser solo un modelo de color (como RGB o CMYK), Pantone es un estándar de comunicación universal que asegura que un color sea consistente en cualquier parte del mundo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0bdaac42-1ef4-4eb8-b348-0dc9715e234f'::uuid, 'Paquete recurrente', 'Cuando un paquete es recurrente, no borra los asientos que contiene cuando realiza el cierre. ​ Esto es útil cuando los asientos ​ de un paquete no varían mucho de un período a otro y significa más trabajo volverlos a digitar que modificar los datos ya insertados. ​', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a7a934d3-7253-48a4-94bf-7022512dbf6e'::uuid, 'Paquetes ', 'Los paquetes son unidades contables que contienen transacciones contables del mismo tipo o clasificación. El objetivo del uso de paquetes es agrupar todos los movimientos similares en una sola y única unidad mayor, de manera que se agilice su localización en el diario y su aplicación al mayor de la contabilidad.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d8116351-4736-4aee-80b0-819dfa254343'::uuid, 'Parámetro', 'Valor configurable que define el comportamiento de un módulo o proceso.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8cde9fdc-429d-442a-b923-ac4f75a51d03'::uuid, 'Parámetros del módulo', 'Valores que pueden ser cambiados, modificados o ajustados según la preferencia o necesidad del usuario para adaptar el sistema a sus requerimientos. Definen aspectos generales como el formato de las cifras decimales, métodos de costeo, texto de clasificaciones, costo de ingresos especiales, unidades de medida, conteos cíclicos y capas de costo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0c9f2e0d-8e83-424b-abe0-66fd040bc404'::uuid, 'Pasante', 'Estudiante que realiza prácticas profesionales en la empresa bajo un programa estructurado y supervisado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5977f266-55f9-415a-875a-46c8fef5a449'::uuid, 'Pasantes', 'Representa el número total de personas que se encuentran realizando una práctica profesional o pasantía en la organización en un momento específico en el tiempo (una fecha de corte).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('490bb07f-79cd-4228-8732-eb6a7ba50e8b'::uuid, 'Pasivos', 'Obligaciones presentes de la empresa, surgidas a raíz de sucesos pasados, para cuya cancelación la entidad espera desprenderse de recursos económicos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e878c4b4-5132-4c86-9917-d139b43cf6fb'::uuid, 'Paso', ' Es una acción realizada que expresa el mínimo nivel de ejecución. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ddd9b24f-dc91-41a2-8c8f-e6b4f85ca788'::uuid, 'Pasos', ' Escala establecida para medir la madurez.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('91af15b0-b2dd-46b0-a7e1-981961a6a1fe'::uuid, 'Patente', 'Derecho exclusivo concedido sobre una invención, que constituye un activo intangible valioso para la empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('29cf40f7-9b42-40b1-8fa5-8ab9443d333e'::uuid, 'PDA', 'Se refiere a los dispositivos móviles o "Hand Helds" que utiliza el asesor para registrar pedidos y otras transacciones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5e3ec8b9-177a-42d8-9570-ad4ae4c5e796'::uuid, 'Pedido', 'El pedido es un documento que la empresa elabora a partir de una orden de compra emitida por un cliente en la que se solicita cierta cantidad de artículos.  ', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:42:50.746Z'::timestamptz),
  ('2c5a6835-d961-45e0-92ef-b060f0e996fd'::uuid, 'Pedido especial', 'Cualquier solicitud de producto que se encuentra fuera del surtido regular de la compañía, ya sea en términos de especificaciones especiales del producto, aplicabilidad, comercialización o cualquier otra característica, pero está disponible dentro del catálogo de productos que ofrecen nuestros proveedores.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d9f609d5-c875-46ff-a4c3-9100aef8bb84'::uuid, 'Pedidos', 'Documentos que reservan artículos para que no puedan ser utilizados en otras transacciones. Se crean a partir de las existencias disponibles en el inventario.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('792c66a9-3bc1-4e55-b16d-b099540235a2'::uuid, 'Perfil', 'Conjunto de permisos que definen las acciones que un usuario puede realizar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d382369a-d4b5-4b33-9e67-004ac51e13ef'::uuid, 'Perfil (de recurso)', 'La capacidad física con la que contará el recurso. Incluye abreviatura, descripción, nivel máximo de almacenaje, nivel máximo de picking y capacidad de contenedores.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3e4a71ab-7ff3-4ec4-9143-ba1e5a0d7788'::uuid, 'Perfil de trabajo', ' Funciones que va a cumplir el operario dentro del CEDI. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9492d2f9-4000-49d7-9b35-09ebc099f4da'::uuid, 'Perfil de usuario', 'Conjunto de permisos asignados a un usuario para acceder a funciones específicas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c6b7238f-029f-4145-86d4-d7107811e1c9'::uuid, 'Perfil del cargo', 'Descripción detallada de las características, competencias, experiencia y formación requeridas para desempeñar un puesto de trabajo de manera exitosa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('986b8974-80ef-452e-ae2d-862982a7d39f'::uuid, 'Periodo de recuperación', 'El tiempo necesario para que los flujos de efectivo de una inversión igualen el costo inicial de la misma. Es una medida simple del riesgo y la liquidez de un proyecto.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('036915da-2710-4a83-9a3e-09dd5274f046'::uuid, 'Permiso laboral', 'Autorización concedida al empleado para ausentarse de su trabajo por un tiempo determinado, con o sin goce de salario, por motivos personales, médicos o legales (licencia por luto, licencia por maternidad/paternidad, permisos remunerados).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('75c987e5-1a7f-453a-9ffc-5654139be6e8'::uuid, 'Permisos', 'Autorizaciones que habilitan o restringen funciones dentro del sistema.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('835c0200-8ead-4715-928c-fbf72662354b'::uuid, 'Permisos por pantalla', 'Configuración que habilita o restringe botones específicos en cada módulo del sistema.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('71423c1e-7ca0-4f62-8514-6eb4d763c82a'::uuid, 'Peso visual', 'es un concepto fundamental que se refiere a la capacidad de un elemento (como una imagen, un texto o un color) para atraer la atención del espectador. Cuanto mayor sea el peso visual de un elemento, más prominente se sentirá y más rápidamente captará la mirada.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f41365fd-b2d4-4dff-b09f-6838d8153817'::uuid, 'Pestaña', ' Es parte del documento BizAgi, representa otra página del documento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('20d3b8b8-4e37-4228-baa0-a849dd85a054'::uuid, 'PI', 'Proforma', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('233c4fbb-ece8-457b-a91e-ba9b546a5cda'::uuid, 'Picking', 'Proceso de selección y preparación de artículos desde su ubicación de almacenaje hasta el área de despacho.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1859ef70-ee73-43d1-a5ee-f699a6ba44ff'::uuid, 'Picking a piso', ' Son tarimas que se encuentran en el primer nivel de alisto, y que se utilizan para el proceso de picking. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b06e4660-fb61-42fe-aa1a-eb30e3a2ba87'::uuid, 'Picking automático', 'Asignación automática de tareas de picking a los recursos disponibles.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('79b71198-6665-4491-ba0c-a4e7d2045da7'::uuid, 'Picking inverso', 'Proceso de devolución de artículos desde el muelle de expedición hacia zonas de almacenaje.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('94a0d616-c29c-4635-8f82-6ff0fe299de8'::uuid, 'Piloto', 'Despliegue controlado de un sprint a un grupo representativo de usuarios reales, previo al despliegue masivo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('65f7cd76-eeca-43c6-8045-0fa03558bad3'::uuid, 'Pixel', 'es la unidad más pequeña de una imagen digital.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('aefa1af2-63f9-42c9-97e4-ac2bcd84815a'::uuid, 'Placa', 'Identificador del vehículo utilizado en el proceso de carga.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ddf37ba6-30c5-462b-b426-79017c99af5f'::uuid, 'Plan (PE)', 'Valor meta establecido en el Plan Estratégico de la compañía, que sirve como guía a largo plazo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e94a32b6-4c21-4533-ba27-6a5070bf7e84'::uuid, 'Plan de beneficios', 'Conjunto de compensaciones no salariales que ofrece la empresa para atraer, motivar y retener talento (seguro médico privado, planes de pensiones complementarios, bonos, vales de comida, etc.).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('50915e46-2856-4246-abd8-23c90dfdf613'::uuid, 'Plan de Contribución', 'Valor esperado de contribución según lo establecido en el plan estratégico', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('11f2ab29-cdf2-4190-895c-a73160f39156'::uuid, 'Plan de control', ' Documento donde se detallan las características del macroproceso (o tarea) y las reglas específicas para estas, así como el método de validación, las posibles fallas que se pueden presentar y las acciones a ser realizadas en caso de que éstas se presenten. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('921791b1-f03f-4ad1-bba2-519c2abafdfb'::uuid, 'Plan de demanda', 'Conocido también como Final Forecast. Es el pronóstico resultante de enriquecer el pronóstico estadístico base con el input comercial (conocimiento del mercado, promociones, lanzamientos, proyectos, información de clientes). Representa la visión consensuada y única de la demanda que la organización adopta como plan oficial.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5bc02c47-0033-43ec-8af0-ea6afd16b680'::uuid, 'Plan de Margen', 'Valor esperado de Margen según lo establecido en el plan estratégico', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6e5763a4-1716-4b2c-9c0c-8a7dcad5d67b'::uuid, 'Plan de Venta', 'Valor esperado de Venta según lo establecido en el plan estratégico', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('20abed27-9706-46f4-9502-7f44d5a239ac'::uuid, 'Plan estratégico', ' Es el plan de evolución del negocio, donde están todos los planes para alcanzar los objetivos propuestos por la organización. De aquí salen las distintas iniciativas y proyectos. Estos planes tienen una vigencia que oscila entre 1 y 5 años (por lo general,  3 años).  ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('892976eb-737d-49c6-a07e-7f2ab59704f7'::uuid, 'Plan integrado de negocio (IBP)', 'Proceso de planificación que alinea las áreas de ventas, operaciones, cadena de suministro y finanzas bajo una "única versión de la verdad" para la toma de decisiones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('46e31a25-e525-4f6c-b9d5-f465a490826c'::uuid, 'Plan operativo', ' Los planes operativos tienen como sujeto a una función. Son planes a 1 año y están alineados con el plan estratégico a través de los objetivos establecidos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f54eb08d-8305-4ff3-ac86-f25beba1d1b5'::uuid, 'Plan semestral', 'Presupuesto táctico ajustado periódicamente que sirve de puente entre el plan estratégico anual y la operación diaria del negocio.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b92af578-7367-4854-8245-8d18ec973491'::uuid, 'Planificación de la venta', 'La programación de actividades que se divide en periódica, diaria y de la llamada, donde se revisan documentos y se prepara la propuesta para el cliente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d5e805de-2f37-4da7-aa3c-0c5ec369481f'::uuid, 'Planificación financiera', 'Área responsable de elaborar presupuestos, pronósticos y análisis para guiar la toma de decisiones estratégicas y operativas de la empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4b8d0a6f-f524-4094-973a-fd44743a0e41'::uuid, 'Planificador de cobranza', 'Reporte que sirve de guía para planificar la gestión de cobranza, mostrando por rutas los documentos que están próximos a vencer en un rango de fecha', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ce8f8079-d4c8-4d6a-9cb0-f5922dc0da5b'::uuid, 'Plantillas o modelos de transacciones contables', 'Formato que se le dará a un determinado transacción contable, debe estar asociado a un evento contable. Permite el manejo de operadores especiales y de la información contenida en las variables del evento de tal manera que automáticamente construye las cuentas y calcula los montos que van a los débitos y a los créditos de cada línea de la transacción contable.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('234eaa50-306e-4e1e-bc07-cbd93a7795d9'::uuid, 'Plaza', 'Se refiere a la cantidad de personas que pueden trabajar en un mismo puesto simultáneamente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2fc70601-e38a-4677-8bac-7c402c89262c'::uuid, 'PO', 'Purchase Order (en español: Orden de Compra)', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f025e34f-775d-46df-91fa-bfd49786478e'::uuid, 'Poder', 'Documento legal que autoriza a una persona a actuar en nombre de otra o de una empresa para actos específicos (firmar contratos, realizar trámites, etc.).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7f652dbf-eef9-4666-b349-9fbbecdbd0c3'::uuid, 'Política', 'Lineamientos generales que regulan el comportamiento y decisiones dentro de la organización.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e5d2c84c-7765-438b-bf70-763c919f9839'::uuid, 'Política de garantía', 'Las condiciones establecidas por el proveedor para asegurar la calidad y el buen funcionamiento de un artículo, dentro de un período de tiempo específico, y que rigen las devoluciones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ce66dbe5-ac3c-4e30-beb0-6d6e49bbe740'::uuid, 'Porcentaje ajuste costo', 'Porcentaje para calcular el costo estimado para artículos de proveedores extranjeros. Este porcentaje se utiliza cuando no se conocen los costos y el artículo tiene que ser ingresado al inventario.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d3b29032-77be-46ae-b1f8-ba95e0e516c8'::uuid, 'Porcentaje descuento', 'Porcentaje por rebajar, igual para cada línea de la orden de compra. Es un descuento otorgado por el proveedor sobre la orden de compra en general.', 'Porcentaje Descuento', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:38:22.819Z'::timestamptz),
  ('901f1993-b3d4-4dd5-9e9f-4a3676f291b1'::uuid, 'Portafolio', 'Agrupación de marcas que permite a los equipos comerciales y de ventas dedicarse exclusivamente a un grupo de marcas, asegurando una vista integral de punta a punta.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('258bae8a-8418-4832-afce-a0db718a40f1'::uuid, 'Portafolio de trabajo', 'Es una colección organizada y seleccionada de los mejores trabajos de un individuo o una empresa. Sirve como una herramienta de presentación para demostrar habilidades, experiencia y estilo a clientes potenciales, empleadores o colaboradores.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8af6f8c4-3e71-4565-b805-fd8250f85ce7'::uuid, 'Portal de imprenta digital', 'Plataforma web donde se almacenan y pueden ser consultados todos los documentos fiscales electrónicos emitidos por la compañía.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2b30f754-dbb1-4601-8407-735ee6fccf41'::uuid, 'Portal de pedidos', '', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('25d5af81-0ca8-46c7-ba3e-a35c8fdaeadf'::uuid, 'Portal web bancario', 'Plataforma en línea proporcionada por un banco para que los clientes realicen transacciones, consultas y gestionen sus productos financieros.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ac01395e-3f1c-4634-bbc6-44c075364150'::uuid, 'Power query', 'Herramienta de Power BI para transformar y limpiar datos antes de analizarlos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ef01f19a-acd1-4dda-82e8-7f6202a2fcb4'::uuid, 'PPP', 'Es una medida de la densidad de píxeles en una imagen digital y se utiliza principalmente para pantallas y monitores.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('84b26c9e-33c2-40d0-a96a-95c36d305be0'::uuid, 'PPTO', 'Abreviatura de Presupuesto. Se refiere al valor original estimado o asignado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('da6cec11-13bb-433c-84c9-2d0e8cb09888'::uuid, 'Preaviso', 'Notificación anticipada que debe dar cualquiera de las partes (empleador o empleado) para poner fin al contrato de trabajo. El tiempo de antelación requerido está estipulado en la ley laboral de cada país.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9436162f-6019-49ec-bb6a-1a6029b6f74d'::uuid, 'Precio', 'El valor monetario de adquisición de un producto o servicio ofrecido por un proveedor. También se le llama "precio de compra".', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a42ddfad-fb07-48df-88e7-faba85b0c70a'::uuid, 'Precio base', 'El valor monetario estándar que ofrece el proveedor en sus productos o servicios a todos sus clientes, sin ningún tipo de descuento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('afb51585-cd15-4862-8833-cfb1b344cd99'::uuid, 'Precio de Venta', 'Este es un indicador clave que te dice a qué precio se están vendiendo tus productos o servicios en promedio, una vez que se han considerado todos los descuentos y promociones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2df671f7-3fc9-4f77-835e-84be0d0d4572'::uuid, 'Precio de venta mayoreo', 'Es el precio de venta base definido para un producto y constituye el punto de partida para la fijación de los precios de los clientes.
El precio de venta mayoreo debe establecerse por encima del costo del producto, evitando márgenes negativos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8ddae5b8-16f6-49f7-9d6b-8f6798f51198'::uuid, 'Precio del Cliente - "Su Precio"', 'Es el precio final al que accede cada cliente después de aplicar el descuento correspondiente sobre el Precio de Venta Mayoreo.
Dicho descuento es exclusivo para cada cliente y se determina mediante variables comerciales previamente definidas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('da33c177-78c4-4d04-af93-5017004e20dc'::uuid, 'Precio neto', 'El resultado de aplicar todos los descuentos ofrecidos por el proveedor al precio base de un producto.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8d0eeb71-6dad-49e8-b020-902b457ce577'::uuid, 'Presupuesto', 'Estimación financiera detallada de los ingresos y gastos esperados durante un período de tiempo futuro. Es una herramienta clave de planificación y control.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('226eaebb-f428-4198-aaf3-9914bebf0e55'::uuid, 'Presupuesto bruto', 'Sumatoria de la Columna Presupuesto de venta bruta en moneda local o dólar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ba7f2ed3-abda-44b8-ab5b-1b472fb12f51'::uuid, 'Presupuesto Cartera', 'Valor presupuestado de deuda por cobrar', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('deec0cae-a38c-4451-ab2f-ab82a7129c46'::uuid, 'Presupuesto Compras', 'Monto total de la mercancía que la empresa planea adquirir en un período determinado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0eab8f58-43a4-4376-bef7-f9bfcc639dd4'::uuid, 'Presupuesto Cuentas por pagar', 'Monto total de las deudas que la empresa espera tener con sus proveedores.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5c5f9972-a390-463b-8850-bb7fcbbc18c0'::uuid, 'Presupuesto de contribución', 'Sumatoria de la utilidad.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9f1d620b-e587-4e46-9acf-0754059a5292'::uuid, 'Presupuesto de inventario', 'Presupuesto de inventario mensual necesario para alcanzar un Retorno de la Inversión (ROI) en Margen Bruto (GMROI) deseado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('081f7bc8-03b3-453a-951b-ecacd1ef9953'::uuid, 'Presupuesto neto', 'Sumatoria de la Columna Presupuesto de venta neta en moneda local o dólar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c450cf42-b50a-4a10-9ee1-9ff113dc49da'::uuid, 'Pricing', 'se refiere a la estrategia que utiliza una empresa para determinar el precio de sus productos o servicios. Es un proceso crucial que va más allá de simplemente cubrir los costos, ya que busca maximizar la rentabilidad y el valor percibido por el cliente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d4228403-55e0-49bd-b5a0-9cc9a46fbfe6'::uuid, 'Prima de servicios', 'Prestación social en Colombia equivalente a un salario mensual por año, pagadera en dos mitades (semestres). En Venezuela existe una figura similar llamada "Bono Vacacional" que, aunque asociado a las vacaciones, cumple una función de ingreso adicional.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4377ac19-c199-4c27-8706-0e977da947dd'::uuid, 'Principal', 'Monto de la deuda incurrida por el cliente sin tomar en cuenta los intereses', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9a7a3645-cbad-427e-ad31-06477e2dfcec'::uuid, 'Prioridad', 'Otorga un ordenamiento a la atención de acciones en eflow WMS.', 'Prioridad', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:42:55.941Z'::timestamptz),
  ('6345a403-0755-4cd6-8206-fe3eff78cd7a'::uuid, 'Prioridad de atención de la orden', 'Un dato utilizado como referencia para el manejo operativo y la priorización de tareas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('81d7239a-95e7-4647-acfe-deceef2d5b41'::uuid, 'PROB (Problema)', 'Tareas relacionadas con una orden de expedición con faltante de inventario, creadas pero en situación de PROB para no ser atendidas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('823103f1-1745-4683-802f-ab9e5d964bf1'::uuid, 'Procedimiento', 'Secuencia de pasos detallados que indican cómo ejecutar un proceso, incluyendo responsables y acciones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('adcd2c9b-76ba-4703-bd32-f336fd99df42'::uuid, 'Procedimiento de pagos por TXT', 'Método para ejecutar pagos masivos mediante la carga de un archivo de texto plano (.txt) en la plataforma del banco, optimizando el proceso de pagos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('be05b4d1-6db7-47f9-8714-dcd59c624eeb'::uuid, 'Proceso', ' Es un conjunto de tareas que tienen una secuencia lógica que toman una o más entradas y generan un producto o servicio. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8d892886-55c2-443c-8b87-787063d15f27'::uuid, 'Proceso central', 'Actividad clave o conjunto de actividades que deben realizarse de manera ejemplar para garantizar la competitividad continua de una empresa porque agrega valor primario a un producto.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1dd259c1-1b5e-4306-a490-6486171b6f46'::uuid, 'Proceso de diferencial cambiario', 'Rutina ejecutada en el ERP para calcular, reconocer y contabilizar las ganancias o pérdidas por diferencias en el tipo de cambio de documentos en moneda extranjera.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1720286e-7d16-4b09-810c-8784cd1047c6'::uuid, 'Proceso embebido', ' Funcionalidad de BizAgi. Los procesos embebidos son aquellos que comparten la misma información o datos del proceso padre. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('92b4d2c0-f5d9-49a2-b604-fcf7136d887d'::uuid, 'Proceso en RF (toma física)', 'Pasos para ejecutar una toma física usando el menú de inventario en la Terminal de Radio Frecuencia (HH).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4ac7e0b1-80e6-400a-b17a-b9b15c9f3324'::uuid, 'Proceso reusable', ' 1. Se consideran procesos reusables aquellos macroprocesos del BPA que son comunes entre la “Cadena de Valor” y “Soporte. Para estos casos, se define que estos procesos serán diagramados en la “Cadena de Valor” y reutilizados en la parte de “Soporte”. 2. Funcionalidad disponible en Bizagi que indica que el proceso contiene un conjunto de actividades que son independientes del proceso padre, el cual es el proceso que los llama.  ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('baeaf1a8-e7b9-442a-aa98-51213fb260d3'::uuid, 'Producto regular', 'Se refiere a un grupo de artículos que se les da entrada como un sólo SKU, almacenados en una misma ubicación y se factura con un sólo código. Se origina cuando un Kit se mantiene en el tiempo y deja de cumplir una función promocional.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b148b208-f81c-4d84-a406-772df7c1a4a6'::uuid, 'Productos terminados', 'Estos son artículos terminados que se tienen en inventario y que se encuentran listos para ser embarcados a un cliente de acuerdo a un pedido en una planta de producción. En todos estos tipos de inventario participan artículos, los cuales se encuentran en distintos estados como se mencionó anteriormente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('18c70a89-ccfd-44f8-800a-68e6efb4de2e'::uuid, 'Promedio pedido diario', 'Esta fórmula calcula el promedio de pedidos que se crean cada día laboral en un período específico. Es un indicador clave de la actividad comercial y la demanda diaria que enfrenta la compañía', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('eea4d50d-c417-45cb-9608-b794a894828b'::uuid, 'Promoción', 'Reconocimiento al desempeño o antigüedad que puede incluir un aumento de responsabilidades, remuneración o ambos, no necesariamente implica un cambio de nivel jerárquico.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ac1e9498-95d1-4a64-ad47-468f0acaa2ca'::uuid, 'Promoción Asociativa', 'Se pueden asociar las premisas generales a un grupo de artículos de diferentes marcas, donde se cumplan las premisas entre todos los artículos asociados a esta promoción.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('af0b7cbf-4e2d-4290-a10a-7180f2dcbbda'::uuid, 'Promoción Liquidación', 'Son promociones donde se otorga un descuento adicional a aquellos artículos que ya no formarán parte del inventario para la venta.', '', 'sinetiqueta'::estado_origen_termino, 'Esta fila no tenía Etiqueta Principal en el archivo original y no es duplicado de nada; no se pudo inferir con confianza el silo correcto.', false, NULL, false, false, NULL, NULL),
  ('7bfd0f30-eee9-4125-b447-166f6aaf0c38'::uuid, 'Promoción Volumen', 'Son promociones basadas en descuentos por volumen de compra definidos por montos', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e53f8a1b-b42b-4b8f-a84f-58fd53b52182'::uuid, 'Pronóstico con restricciones', 'Es el pronóstico "aterrizado" a la realidad de la empresa. Es el volumen que la compañía realmente puede servir dadas sus limitaciones de dinero, espacio o suministro.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9642531c-1e0f-4ea3-a147-f1bc89b39439'::uuid, 'Pronóstico de demanda', 'Estimación futura del volumen de productos requeridos, basada en datos históricos y factores externos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f0aff911-b4f9-47c2-873c-035682feeecb'::uuid, 'Pronóstico estadístico base', 'Es el pronóstico generado automáticamente por un modelo matemático, a partir únicamente del comportamiento histórico de la demanda, sin intervención humana ni juicio comercial.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7f536a81-9d75-40ea-91b7-26d091667c72'::uuid, 'Pronóstico sin restricciones', 'Representa la demanda "pura" del mercado, lo que el cliente querría comprar si no hubiera límites de inventario.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0144ff95-5a0f-4b35-ace6-95f4a60c53ef'::uuid, 'Propiedad', 'Es un atributo o característica específica que describe a un cliente o a su comportamiento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1200e264-b71d-4962-952f-5681923cd536'::uuid, 'Proporción', 'es la relación de tamaño entre dos o más elementos de una composición. Se trata de cómo los elementos se comparan entre sí en términos de tamaño, cantidad o grado. La proporción es un principio fundamental que los diseñadores usan para crear armonía, equilibrio y un sentido de orden en cualquier pieza visual, desde un logo hasta una página web.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('77c1b8c0-e952-4be8-9a5e-df4406d82fda'::uuid, 'Propuesta de valor', 'La promesa que una empresa le hace a su cliente de entregarle un beneficio o una experiencia única.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('744ffabb-c047-4cf7-887f-6c9cc236af9b'::uuid, 'Prospección', 'Una actividad cuyo objetivo es validar si un prospecto cumple con un perfil determinado para convertirse en un cliente potencial.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('467f3301-3710-44df-9a0b-1c90e765ca83'::uuid, 'Proveedor activo', 'Cartera de proveedores activos de la compañía.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('36ed4900-51da-475d-a7d2-d198403bc654'::uuid, 'Proveedor Administrativo', 'Persona o empresa que suministra los bienes o servicios necesarios para el proceso productivo de otra empresa, o las mercancías que esta necesita para su actividad comercial. Es el proveedor que factura y se utiliza en la gestión administrativa, campo legal con NIT y nombre de registro.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e09bc304-5146-49ae-b1ea-0952da8a029e'::uuid, 'Proveedor agrupación', 'Corresponde al proveedor con el que se mantiene la relación comercial y que aglomera los vehículos de facturación asociados a él.', 'Proveedor Agrupación', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('55368c1b-e83d-482b-bafa-72b3cff511e8'::uuid, 'Proveedor Dummy', 'Registro genérico y temporal de proveedor en el ERP utilizado para presupuestar, planificar compras o registrar transacciones iniciales cuando la entidad proveedora real aún no ha sido identificada o registrada formalmente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6d5cd030-7c15-45d7-8d1b-80f8d895a426'::uuid, 'Proyecciones de flujo de caja', 'Estimación futura de las entradas y salidas de efectivo. Es una herramienta estratégica clave para anticipar necesidades de liquidez, planificar inversiones y gestionar la capacidad de pago.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('87592ff3-0d8b-4ad9-87a4-1f42b9a3da40'::uuid, 'Proyección (proy)', 'Estimación ajustada periódicamente sobre un valor presupuestado, que refleja la expectativa más actualizada de lo que se espera alcanzar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a09f322a-f2c3-4137-b193-eaa0e576916f'::uuid, 'Prueba psicotécnica', 'Herramienta utilizada en selección de personal para evaluar habilidades cognitivas, aptitudes y rasgos de personalidad de los candidatos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4532da78-69ef-4289-807d-609516b22731'::uuid, 'Publicación', 'Distribución oficial de un documento para su uso operativo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('cb7cca2b-6e5b-4a35-9497-ce87658167cb'::uuid, 'Puesto', 'Ocupación del empleado en la compañía, según los puestos definidos por la estructura organizacional de la misma.', 'Puesto', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:42:58.244Z'::timestamptz),
  ('9dc598ef-a55a-496c-b049-a86e36f4f52e'::uuid, 'Puesto de apartado', 'Ubicación en el almacén para un ítem en específico. Cada ubicación debe indicar: pasillo, rack y puesto. Estos puestos contienen mercancía fuera de su empaque original.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4bdc6792-b55c-4165-a7f7-89fe61e447b7'::uuid, 'Puesto de aéreo', 'Puesto dentro del almacén para un ítem en específico que comprende una paleta completa. Los aéreos contienen empaques originales y están identificados con un “hablador”. Su ubicación indica pasillo, rack y puesto.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ab6c42a9-8545-4a2e-bb42-2a105858181d'::uuid, 'Punto de re-orden', 'Se refiere al nivel de existencias en el que se hace un nuevo pedido al proveedor. Siempre será mayor al nivel de existencia mínima y debe considerar los consumos durante el período de reabastecimiento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a4224f06-5e35-4311-ae5b-2b477e76dc93'::uuid, 'Purga de datos', 'Proceso en que se eliminan todos los datos almacenados hasta cierta fecha límite. Este proceso no es reversible.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9a0bf99c-ca66-4fd6-87ae-9816c514bf31'::uuid, 'Push money', 'es una estrategia de promoción de ventas en la que un fabricante o distribuidor le paga una comisión o incentivo económico directamente al personal de ventas de un minorista. El objetivo es motivar a estos vendedores a hacer un esfuerzo adicional para "empujar" la venta de un producto o línea de productos en particular.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9fe9a4e9-e215-481d-960e-5ec085093f0a'::uuid, 'QDC', 'El concepto de QCD (Calidad, Costo, Entrega) se enfatiza principalmente en proporcionar productos y servicios a los clientes con mejor calidad, precios asequibles y a tiempo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e9c7000f-334e-47ec-ae95-efb5db0a2865'::uuid, 'Rama de negocio', 'Clasificación de una compañía de Mayoreo dependiendo del tipo de mercancía que comercializa. Dentro de los presentes se encuentre Ferretería, Autopartes y Quincallería. Corporativo representa la división que brinda soporte de este tipo a las áreas comerciales.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c61e584b-547e-412b-b8b7-6d16798c6be5'::uuid, 'Ranking', 'Reporte SIM – Dimensión Compras: Muestra la clasificacion de los artículos del surtido regular segun la categoría de colores: “Verde”, “Amarillo”, “Naranja” y “Rojo”. Estas categorías reflejan el comportamiento de los artículos en los últimos doce meses, basándose en tres indicadores específicos: contribución, clientes activados y rotación de inventario. Reporte SIM – Dimensión Ventas: Es una clasificación ordenada de elementos (como personas, productos o empresas) basada en un criterio o métrica específica. Es una herramienta para comparar y evaluar el rendimiento o la importancia de algo dentro de un grupo.', '', 'dudoso'::estado_origen_termino, 'Compras usa una metodología propia (semáforo de colores según contribución, clientes activados y rotación); Ventas tiene una definición genérica de “ranking”. Se asumió que Ventas usa el concepto general y Compras una implementación específica.', false, NULL, false, false, NULL, NULL),
  ('176e36a4-47b6-4707-9632-46b7039999eb'::uuid, 'Razón social', 'Nombre oficial y legal bajo el cual una persona natural o jurídica es constituida y registrada ante las autoridades competente.', 'Nombre / Razón Social', NULL, NULL, false, NULL, false, false, NULL, '2026-09-30T19:30:00.000Z'::timestamptz),
  ('1cd929b3-9d98-4feb-93fc-3c48ba0e1064'::uuid, 'Reabastecimiento', 'Lapso que tarda el proveedor en hacer llegar el pedido al cliente desde la emisión de la orden de compra hasta la recepción de la mercadería. Se debe definir en días.', 'Reabastecimiento', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('d52be40b-6939-41d4-a93f-c52027dcfc9f'::uuid, 'Rebate global', 'Silo Control: Descuento o bonificación que un proveedor otorga retroactivamente por alcanzar un volumen de compra determinado durante un período. Reporte SIM – Indicador Control: Suma total de los descuentos recibidos por las comercializadoras.', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('01cb4769-1e28-4b69-bac9-5d4dc6a3fb14'::uuid, 'Rebate Global %', 'Ratio que muestra el porcentaje del rebate global con respecto al monto total facturado por las comercializadoras', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3454d6a4-19e8-4e78-a931-0360242538f8'::uuid, 'Recaudación', 'Suma total de los ingresos en efectivo recibidos por la compañía', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('35fb9800-845b-4c24-8310-0b9411fb5f3a'::uuid, 'Recepción', 'Eprac: Proceso de recibo de artículos en el CEDI, ya sea por primera vez o reintegrados por una razón comercial. Silo Logística: Proceso de ingreso de mercancías al CEDI, incluye descarga, revisión documental y registro en el WMS.', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('22456395-ad0c-4d83-aa88-b1c7492345d7'::uuid, 'Recepción (en RF)', 'La segunda pantalla utilizada en la Terminal de Radio Frecuencia para el ingreso de mercadería.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('bb44a91e-dadd-44b7-8401-73418178db4f'::uuid, 'Recibo', 'El recibo es un documento que se emite para constar que se recibió dinero en efectivo del cliente, para abonar o cancelar el monto que adeuda a la empresa.Este documento disminuye la cuenta por cobrar, de manera que se produce un pago a un monto por cobrar pendiente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c9a9cce0-396e-45cc-a045-5ca431e6f434'::uuid, 'Recibo de cobro', 'Documento que evidencia la recepción de un pago por parte de un cliente, detallando el monto y las facturas que se están cancelando.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('00692473-839e-4b7f-9a60-6fd43a9da966'::uuid, 'Recibo de nomina', 'Documento que detalla el desglose del salario devengado, las deducciones aplicadas y el neto a pagar a cada empleado en un período determinado. Sinónimo de "Recibo de Nómina" o "Desprendible de Pago".', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7dbf5121-e23c-4ef4-bf7a-73ae3f86a874'::uuid, 'Recibos de cobranza', 'Un submenú en el Módulo de Cobranzas que permite crear, imprimir y gestionar los recibos de cobro de un cliente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0e1f5bb6-1624-439d-9a5a-35bc0ed5475f'::uuid, 'Reclamo', 'Solicitud formal ante discrepancias en la recepción (faltantes, exceso, daño).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2319cfea-0ab5-45c1-8434-dda2ebf87a2c'::uuid, 'Reclamo por error en el despacho', 'El producto y las cantidades facturadas son iguales a las solicitadas por el cliente, pero físicamente hubo un error de código.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5941f130-5946-4ec3-b30f-44e4f9e60fde'::uuid, 'Reclamo por error en el precio facturado', 'En la factura se evidencia un precio distinto al ofrecido al cliente por parte del vendedor.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d0a56bd5-b31d-4c67-8af0-4848d7f79712'::uuid, 'Reclamo por error en pedido', 'Pedido mal ingresado por el vendedor (error de código, error de precio y sobrantes facturados)', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3d541bab-2998-4367-9137-e10f2b0d6c70'::uuid, 'Reclamo por producto dañado', 'El producto llegó en mal estado o hay evidencias de un daño físico. No incluye problemas en el funcionamiento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('928c744e-d4e4-4591-ab1a-570dccf32e11'::uuid, 'Reclamo por sobrantes no facturados', 'El cliente recibe artículos adicionales no indicados en la factura.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4fa16655-4c81-41dd-bd5d-f4810f5784bd'::uuid, 'Reclutamiento', 'Conjunto de actividades para atraer candidatos potencialmente calificados para ocupar una vacante dentro de la organización.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8e4fa96c-0888-4ea2-8902-182bca746aa8'::uuid, 'Reconocimiento por años de servicio', 'Mecanismo mediante el cual la empresa reconoce la antigüedad de sus colaboradores (ej: 5, 10, 15 años).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7438ba06-a922-4565-8c5e-c4cbca49ec64'::uuid, 'Reconteo', 'Conteo sucesivo al segundo conteo de artículos. El segundo y primer conteo se comparan para validar que no existan diferencias, si no hay diferencias entre A y B, pero si hay diferencias con Teórico, el Coordinador de Control de Inventario toma la decisión de crear un Ticket de Auditoría. En caso de haber diferencias entre A y B se realiza el conteo de Libro de control (3er Conteo).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8adc218b-6062-4456-9fe2-c9a985f17ba5'::uuid, 'Recurso', 'Equipo físico o rol operativo (ej. montacargas, alistador) vinculado a tareas en el sistema.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('49faca4e-b4db-4d41-9309-423271211bc2'::uuid, 'Recíproco', 'Dos artículos son alternos mutuamente, se pueden sustituir entre ambos, en las dos direcciones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4a6412f7-0ab0-4c58-9821-699e6d7b1c09'::uuid, 'Red neuronal artificial (RNA)', 'Modelo matemático inspirado en el cerebro humano que ayuda a que las máquinas aprendan y reconozcan patrones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c001a96c-bbdb-44d9-9c6d-e43a43f7c2d6'::uuid, 'Redención', 'Aplicación efectiva de una promoción sobre un pedido o línea; representa el uso o "consumo" del beneficio por parte del cliente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b28a7bdd-47ee-4106-84ae-5942aaccbef9'::uuid, 'Redes', 'Infraestructura que conecta computadoras y dispositivos entre sí para que compartan información (ej. la red de la oficina o internet).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e4cdd2e6-d91a-4d2d-9a79-e4af1629256c'::uuid, 'Redes sociales', 'plataformas digitales que permiten la creación de perfiles, la interacción entre usuarios y la difusión de contenido en línea.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6098d463-ba39-40f5-aacb-5c9801bed788'::uuid, 'Redondeo', 'Factor del tiempo por el cual se redondearán las cantidades a la unidad siguiente si son mayores.', 'REDONDEO', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('c05854b8-9a22-4eca-8371-e34c8494e1e4'::uuid, 'Referencia', 'Detalle o descripción de un movimiento contable. En la generación de asientos la referencia corresponde a la aplicación definida al documento', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('26c8a648-0585-4aec-aaf2-613af8509951'::uuid, 'Referencia del artículo', 'Un identificador único asignado a un artículo para su seguimiento y gestión en el sistema de la empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('61ea4579-714b-4024-9ced-6e9fcc0831d2'::uuid, 'Regalía', 'Es un artículo o muestra gratis que la empresa entrega a sus clientes como obsequio', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4c38ff86-f09a-43e8-87b1-f8f9ee15cb4c'::uuid, 'Registros', ' Formatos y /o Reportes que evidencian que el proceso documentado se ha ejecutado. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b84da35a-cb32-4872-bfa4-42f9ec4a2c10'::uuid, 'Región', 'Silo Ventas / Reporte SIM – Dimensión Ventas: Porción del país que agrupa un conjunto de coordinaciones geográficamente cercanas que componen el territorio de ventas. Reporte SIM – Filtro Venta: Ubicación geográfica del cliente.', 'Región de Venta / Region', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 3 filas originales.', true, NULL, false, false, NULL, '2026-09-30T19:30:00.000Z'::timestamptz),
  ('f8a49357-efff-46c6-9346-c7431c2d0f7d'::uuid, 'Regla de cálculo', 'Declaración formal que define o restringe un aspecto del negocio y que se traduce en una lógica de cálculo o filtro dentro de un tablero(ej. la metodología para el cálculo del margen operativo bruto).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9100ddb7-e768-4573-a44e-987717f03a83'::uuid, 'Regla del ochenta y veinte', 'Se refiere al principio de Pareto que establece que para muchos eventos aproximadamente el 80% de los efectos provienen del 20% de las causas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fb470077-1ba9-436e-a827-a572bd4fa557'::uuid, 'Reglas', ' Todos aquellos patrones, normas, estándares, especificaciones u otros documentos que le soportan y/o complementan. Debe describir las condiciones específicas para que la tarea se pueda llevar a cabo. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e061750b-071a-4041-a239-60f01f2aa900'::uuid, 'Reglas del cargo y abono', 'Las cinco cuentas básicas de la contabilidad son: activo, pasivo, capital, ingresos y gastos. Las transacciones que se llevan a cabo en una compañía afectan alguna de las cuentas mencionadas. Para aumentar o disminuir estas cuentas la contabilidad ha establecido dos reglas muy sencillas: las reglas del Cargo y el Abono. Un Cargo, Débito o Debe representa un aumento en una cuenta de activo o una disminución en una cuenta de pasivo o capital.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('33fe7281-7800-4600-8e8b-bffbd7d2dbbb'::uuid, 'Reglones Facturados', 'Reporte SIM – Indicador Compra: Sumatoria de la cantidad de renglones facturados. Reporte SIM – Indicador Venta: Esta fórmula representa el número total de artículos o líneas de detalle que se han facturado en un período de tiempo específico.', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('3205d947-4b83-4783-85df-b241dff36fca'::uuid, 'Reglones Pedidos', 'Reporte SIM – Indicador Compra: Sumatoria de la cantidad de renglones pedidos. Reporte SIM – Indicador Venta: Esta fórmula calcula el número total de líneas de detalle en todos los pedidos que se han recibido en un período de tiempo determinado.', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('ccc1e004-b6a0-4cd3-8c3d-e1fbb1830194'::uuid, 'Reingeniería de procesos', 'Rediseño radical de procesos para lograr mejoras significativas en rendimiento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('78e3d926-ac02-4bb2-9e33-037f5ea3ce87'::uuid, 'Reintegro', 'Proceso mediante el cual se devuelve a la caja chica el dinero otorgado por los vales. El detalle de su ejecución se presenta en la sección "Reintegro de Caja Chica" en la página 77.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('42f7b526-e47c-4975-8152-567192aca839'::uuid, 'Relacionados', 'Artículos que, aunque no son sustitutos directos, se venden a menudo junto con el artículo principal. Esto permite a una empresa mayorista promocionar productos complementarios y aumentar el volumen de ventas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8c203f3b-94ff-4c21-9ca7-3e5290e120a1'::uuid, 'Relación de depósitos', 'Una opción para realizar depósitos de pagos en efectivo y/o cheques en un mismo banco', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('51ff99bf-96a3-4d0e-a459-efba0f9d6c51'::uuid, 'Remisión', 'Una remisión es un documento que se genera y envía a un cliente, en el cual se hace constar las cantidades y precios de los artículos enviados. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('34457931-4769-412a-b07a-3610bef1392c'::uuid, 'Renglones', 'Se refiere a la cantidad de artículos diferentes incluidos en una transacción', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b8b31d29-c55a-4ff6-81f9-c915469b9801'::uuid, 'Renuncia voluntaria', 'Decisión unilateral del empleado de dar por terminada la relación laboral.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('bf370d51-dd16-4ac1-8d6b-c047be4dcb4f'::uuid, 'Reparaciones fuera de garantía', 'El cliente solicita la reparación del artículo. Los costos asociados a la reparación serán cubiertos por el cliente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e8bc8672-faea-4f4c-b003-82e9db5f9b02'::uuid, 'Reporte', 'Documento estático o dinámico derivado de un conjunto de datos, diseñado para la lectura humana. A diferencia de una base de datos, el reporte presenta la información ya procesada, filtrada y resumida bajo un formato visual específico. Su estructura no es apta para el procesamiento automatizado, sino para la interpretación directa de resultados.', '', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:43:01.279Z'::timestamptz),
  ('3ed7891f-c51a-4e60-aefa-949498db36c7'::uuid, 'Representantes legales', 'Individuos con la autoridad legal para actuar y obligar a la empresa en actos jurídicos y financieros de alta importancia.', '', NULL, NULL, false, NULL, false, false, NULL, NULL)
ON CONFLICT DO NOTHING;

INSERT INTO terminos (id, termino, definicion, campo_softland, estado_origen, nota_origen, revisado, nota_decision, es_nuevo, editado, eliminado_en, actualizado_en) VALUES
  ('d21296c8-d92e-448a-b7eb-0decd5a845f1'::uuid, 'Repuesto remanufacturado', 'son piezas usadas que se someten a un proceso industrial de restauración completo, que incluye el desmontaje, limpieza exhaustiva, reemplazo de componentes desgastados y pruebas rigurosas para que cumplan o superen el rendimiento de una pieza nueva.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c7b14be5-72bb-453e-9b07-3b5ddece6d1c'::uuid, 'Resolución', 'se refiere a la cantidad de detalle y nitidez en una imagen, un video o una pantalla. Es una medida que determina la calidad visual y la claridad de un archivo o dispositivo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0999c5f9-f065-4b38-b52d-bebb9c0bdb18'::uuid, 'Responsable aprobación', ' Rol encargado de aprobar el documento elaborado, previo a su divulgación y publicación. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a3bd97af-f903-4835-8a0f-dcaa977875e4'::uuid, 'Responsable comercial', ' Autoridad estratégica de un Área Funcional. Define, prioriza y designa los recursos para llevar a cabo iniciativas estratégicas, las cuales se vuelven proyectos de desarrollo para Mayoreo. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d7edcc43-5950-4003-8035-5ddff611d98b'::uuid, 'Responsable de métodos', ' Especialista de Procesos de un área funcional. Documenta, normaliza procesos, y los optimiza para que sea implementado con un sistema o proyecto.  ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6b6729dd-5c30-4884-b755-ad7729a3d770'::uuid, 'Responsable revisión', ' Rol encargado de revisar el documento elaborado, previo a su divulgación y publicación. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f657a545-3055-44a4-bcef-769ae331923f'::uuid, 'Responsable técnico', ' Especialista de Sistemas y Tecnologías de un área funcional. Gerencia los proyectos de desarrollo, y provee al Responsable Comercial información sobre la viabilidad económica y tecnológica de una iniciativa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c03de426-62cb-437c-a6ad-08dd0f156ec0'::uuid, 'Responsable última actualización', ' Persona que elabora y/o actualiza el documento. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9738d588-b4a8-4d91-b870-bc7f37bf39cb'::uuid, 'Resumen de ventas', 'Muestra el total del pedido y la cantidad de renglones vendidos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fee8e98b-8827-480e-9217-03edc7d76d28'::uuid, 'Resurtido de artículos', 'Método de abastecimiento o compra de artículos con el propósito de mantener un inventario disponible que satisfaga la demanda de nuestros clientes y que cumpla con el nivel de rentabilidad establecido por la compañía.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('af9a1522-e9d2-4db5-bff7-1ded4351aa43'::uuid, 'Retenciones', 'Módulo de la aplicación para registrar retenciones de Impuesto al Valor Agregado (I.V.A.) a un cliente', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a845c892-2d44-4509-8f92-367759176960'::uuid, 'Retención', 'Dinero que se retiene de los proveedores cuando realiza una transacción de compra de materias primas o suministros y debe ser entregado a una entidad determinada.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c1024cc8-d271-412a-9f1f-a606e4b3408c'::uuid, 'Retención ISLR', 'Monto que el pagador retiene y entera al fisco como un adelanto del Impuesto Sobre la Renta del beneficiario del pago.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e6bcdac0-f460-48c5-b4c6-d3de4894e040'::uuid, 'Retención IVA', 'Mecanismo por el cual el comprador retiene una porción del IVA de una transacción y la paga directamente a la autoridad tributaria en nombre del vendedor.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fc501c86-3082-42f5-a5d7-232e24214d21'::uuid, 'Retención municipal', 'Impuesto sobre ingresos brutos que es retenido y pagado a la municipalidad correspondiente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d69b0fd1-471b-404f-992a-00b79a626d66'::uuid, 'Retroalimentación para el desarrollo', 'Espacio formal entre colaborador y supervisor para discutir desempeño, actitudes y acordar planes de mejora', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a4391511-8111-405c-9ef5-578ff17dba18'::uuid, 'Revisión', 'Evaluación técnica y de contenido antes de la aprobación de un documento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5892d213-2486-45c9-af21-89a8c9301de4'::uuid, 'Revisión de precio', 'Es un proceso estratégico y continuo que se realiza para evaluar y ajustar el valor monetario de los productos o servicios. A diferencia de la fijación de precios inicial, que se hace al incluir un nuevo producto, la revisión de precios se lleva a cabo de forma periódica o en respuesta a cambios en el entorno de negocio.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('457fd5a7-7d7f-463e-bb8c-4c7bf90dbf7b'::uuid, 'Revisión de precio masiva', 'Un proceso que se realiza para actualizar masivamente el precio o la contribución de ventas de todos los artículos del surtido, con o sin existencia.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('97c6438a-6917-46e1-a9fa-6863a30c9375'::uuid, 'Revisoría', 'Área encargada de validar el cumplimiento de normas y detectar oportunidades de mejora.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a42f1f35-c5c8-45c4-93df-96976d63c76d'::uuid, 'RF', 'Radiofrecuencia; tecnología utilizada para ejecutar tareas logísticas mediante dispositivos móviles.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('67f1d3ba-0273-43b4-9d92-7ca7b0807605'::uuid, 'RGB', 'es un modelo de color que se utiliza para representar los colores en las pantallas digitales. El acrónimo RGB significa: R = Rojo (Red), G = Verde (Green), B = Azul (Blue)', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('856c5137-c8a9-437c-8d2a-42c9418306ad'::uuid, 'Riesgo', ' Son aquellos procesos que representan riesgo a la persona, riesgo fiscal, legal o que puedan detener la operación. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6c2fa11c-375a-4a91-ba45-72dd7529d50a'::uuid, 'Riesgos operativos y financieros', 'Son los riesgos que se buscan identificar y minimizar para asegurar una correcta ejecución y validación de los ajustes de precio.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('080c7109-9e3a-44a1-ac47-e9de0ad7b455'::uuid, 'ROA (return on assets)', 'Retorno sobre los Activos. Indica la eficiencia con la que la empresa utiliza sus activos para generar ganancias. Se calcula como Utilidad Neta/Total de Activos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('10932cad-5b4f-4a4b-8fd7-846a14d30827'::uuid, 'ROI', 'es una métrica clave que se utiliza para evaluar la eficiencia y la rentabilidad de una inversión. Es una forma de medir el beneficio que se obtiene de una inversión en relación con su costo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0c96848c-a0f5-4420-869a-0fe278f9806f'::uuid, 'Rollback', 'Plan de reversión que permite regresar a la versión anterior del sistema ante un fallo crítico en producción.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a38a51f1-05a2-49ae-9b5e-1c237025bdc3'::uuid, 'Rotación', 'Silo Control: Métrica que mide la eficiencia con la que se gestiona un activo, como el inventario. La rotación de inventario se calcula como. Reporte SIM – Indicador Compra: Rotación anual de inventario. Cantidad de veces que la compañía vende y reemplaza el inventario en el año.', 'ROTACION', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('a9602108-5f1c-4c06-b5d6-655068e72bdf'::uuid, 'Rotación de puestos', 'Proceso de trasladar a los empleados de uno a otro puesto para conseguir mayor variedad en las actividades y la oportunidad de aprender nuevas habilidades.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('069bfcdb-9242-4219-a8ca-9eca0e6f8932'::uuid, 'Rotación General %', 'Es el indicador fundamental de Recursos Humanos que mide la tasa de renovación de la plantilla en un período determinado. Expresa, en forma de porcentaje, la proporción de colaboradores que salieron de la empresa en relación con el número total promedio de colaboradores que tuvo la organización en ese mismo lapso de tiempo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('02f26556-cbf5-4a0f-b71e-28aafef81640'::uuid, 'Rotación Indeseada', 'Es un indicador de calidad (KPI) que mide específicamente la pérdida de talento de alto valor y desempeño que la organización preferiría retener.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('baedb644-22b1-49c5-91a2-8cc02d41b153'::uuid, 'Rotación Indeseada %', 'Es un indicador de riesgo de talento (KPI) que mide la proporción de colaboradores de alto desempeño que la empresa ha perdido en relación con el total de talento de alto desempeño que poseía.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('252779d7-9211-41c1-9d7b-88c60a2f4651'::uuid, 'Ruta de visita', 'Una opción de filtro para seleccionar la ruta de visita del cliente en la aplicación.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('cdaa1bd5-d57e-4d79-8779-023885aeaf37'::uuid, 'Rutas', 'Planificación de visitas a los clientes de acuerdo a la ubicación, distancia o condiciones de los clientes, que intenta lograr el máximo aprovechamiento del tiempo de los asesores de ventas', 'Ruta', NULL, NULL, false, NULL, false, false, NULL, '2026-09-30T19:30:00.000Z'::timestamptz),
  ('df07c0bf-0cb9-4528-adb0-92debc45e731'::uuid, 'Rutas de picking', 'Permite agrupar las diferentes secuencias de picking creadas en el almacén, indicando la ruta que deben seguir los preparadores de pedidos en las zonas de picking.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('91fbfea8-a0c8-4b02-b665-3b9e2b97c548'::uuid, 'Régimen vacacional', 'Cada conjunto de contribuciones vacacionales distinto utilizado para calcular el número de días de vacaciones que corresponden a los empleados de la empresa por su trabajo. Un grupo particular de empleados pertenece a un régimen vacacional determinado cuando a todos los empleados del grupo se les calcula la cantidad de días de vacaciones a las que tienen derecho de la misma manera, distinta de la forma en que se calcula a los empleados de otros regímenes vacacionales.', 'Regimen Vacacional', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:38:25.352Z'::timestamptz),
  ('3171b596-e350-42d9-94e8-971e476909c2'::uuid, 'S&OP (Sales & Operations Planning)', 'En español, Planificación de Ventas y Operaciones. Proceso de gestión mensual y multifuncional que alinea la demanda con la capacidad de suministro, integrando las áreas comercial, operaciones, finanzas y dirección, para tomar una decisión única y consensuada sobre el plan del negocio.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d5d73ae5-f724-4db2-99bf-3b66ce8f7b5a'::uuid, 'S.D.S (sincronizador)', 'Aplicación que se utiliza para la transmisión de datos entre la aplicación móvil de ventas AFV y el ERP de la compañía.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('019f9bcd-b3bb-4a94-9e41-fcebff22a961'::uuid, 'Sage XRT', 'Sistema de software especializado utilizado para la gestión de tesorería y la conciliación bancaria.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7150f0cd-4a23-4301-9c3d-bd0c7778c48a'::uuid, 'Salario', 'Retribución en dinero o su equivalente pagado por el empleador al empleado en función del cargo que éste ejerce y de los servicios que presta.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('88b0b7ca-42d8-44a3-8b27-78f57dada430'::uuid, 'Salario base', 'Remuneración fija que recibe un empleado, excluyendo complementos, bonos, horas extras y otros beneficios en especie.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2b45e1ea-32c8-4d27-aeac-47c707210c51'::uuid, 'Salario diario integrado', 'Es el cálculo del salario que devenga el empleado diariamente, según los conceptos tipo base, beneficio, deducción y anticipo asociados a la nómina a la que pertenece. Su cálculo involucra una proporción diaria que es la proporción de aporte del concepto al salario diario integrado del empleado.', 'Salario Diario Integrado', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:38:28.899Z'::timestamptz),
  ('48848ff4-5636-4660-b9f1-089d2568d05d'::uuid, 'Salario integral', 'Modalidad salarial en Colombia y Venezuela que incorpora en una sola suma el valor del salario, las prestaciones sociales y los recargos por trabajo nocturno, extra y dominical, simplificando el cálculo de aportes parafiscales.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e429df0b-36de-4035-bdb3-68fc6d7fe913'::uuid, 'Saldo', 'El valor neto de una cuenta en un momento dado, resultado de sumar todos los débitos y restar todos los créditos (o viceversa).', 'Saldo', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:43:03.841Z'::timestamptz),
  ('4f75c460-ea43-4e8e-b34b-8c42b9269527'::uuid, 'Saldo a favor', 'Monto disponible en la cuenta de un cliente o proveedor que puede ser aplicado a deudas futuras o devuelto.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('99e07992-4e99-427b-b53f-5daed7bee852'::uuid, 'Saldo de proveedores', 'El saldo de proveedores representa las deudas pendientes de pago por concepto de compra a crédito de bienes o servicios. El saldo aumenta por compras o servicios contratados a crédito por la empresa. Las facturas, recibos y otros hacen aumentar la cuenta. Este saldo disminuye por pagos parciales o totales de las deudas, por descuentos obtenidos o por devoluciones de mercadería. Los pagos hechos por transferencia electrónica o cheque disminuyen la cuenta.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('20574940-ef3a-4801-8e44-ea564ce66e09'::uuid, 'Saldo deudor', 'Importe que un cliente debe a la empresa, representando una cuenta por cobrar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ab7a75da-ad32-4af5-9057-25a02ee7754f'::uuid, 'Saldo en bancos', 'El saldo de efectivo disponible en una cuenta bancaria según el extracto emitido por la entidad financiera en una fecha específica.', 'Saldo según Bancos', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:43:05.015Z'::timestamptz),
  ('de79a7c0-8737-4cc3-aa81-ac2339dc5e0a'::uuid, 'Saldo en libros', 'El saldo de efectivo de una cuenta bancaria según los registros contables internos de la empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6d4ac37a-add0-4666-af29-e02dd112c489'::uuid, 'Saldo normal', 'Indica si una cuenta es de débito o de crédito, determinando de qué lado de la ecuación se encuentra, el lado contrario al definido será utilizado cuando el saldo sea negativo. ​', 'Saldo Normal', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:43:06.158Z'::timestamptz),
  ('81a51a04-efd4-481b-9b23-b241b65fb3fb'::uuid, 'Salidas', ' Todo aquello que se genera cuando se realiza el macroproceso, proceso, la actividad o la tarea. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e181c7cc-29aa-4e95-8141-be486823be9c'::uuid, 'Sangrado', 'Es un término técnico que se refiere a una extensión de una imagen, color o gráfico que se extiende más allá del borde de la página final.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5066244a-9070-420e-81bf-1fbe0ddc9028'::uuid, 'Saturación', 's una de las tres propiedades principales del color, junto con el matiz (el color en sí, como rojo o azul) y la luminosidad (el brillo o la oscuridad).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('16270b31-0aad-4066-af64-7e6c014104af'::uuid, 'SDCA (estandarizar, hacer, verificar, actuar)', 'Un refinamiento del ciclo PDCA orientado a la estabilización de los procesos de producción antes de realizar intentos de mejora.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('57d0da50-d78d-4090-9abd-44a74a04531f'::uuid, 'Secuencias de picking', 'Corresponde al número consecutivo para la secuencia según el ordenamiento lógico general en el almacén.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2c4b02da-15a7-4281-aa69-5a800c020ccc'::uuid, 'Segmentación (slicer)', 'Filtro visual que permite seleccionar valores directamente en un informe (ej. elegir país en un gráfico).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('714929b1-aebe-420e-8a90-692a354bc5f9'::uuid, 'Segmentación de mercado', 'El proceso de dividir un mercado amplio en subgrupos más pequeños (segmentos) con características, necesidades o comportamientos similares.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ff5f0a8f-3c39-44a1-a9b1-0458a3c7d0a8'::uuid, 'Segmento de clientes', 'Es una clasificación que se le da a un conjunto de clientes, basados en una definición o elemento que comparten los mismos. Un cliente puede pertenecer a diferentes segmentos. El presente documento enuncia y describe los Segmentos que están definidos para Mayoreo. Un Segmento puede tener una subclasificación, si la necesidad comercial de una línea de negocio (ferretería, repuestos, quincalla) lo amerita.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e173b004-ed64-452b-93a2-7c3389882f32'::uuid, 'Segregación de funciones (sod)', 'Principio de control interno que busca prevenir fraudes y errores al dividir las responsabilidades de una transacción (autorización, registro, custodia) entre diferentes personas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e934cb41-0318-4f40-9e77-a1276aa38a9d'::uuid, 'Seguridad informática', 'Conjunto de medidas para proteger la información y los sistemas contra accesos no autorizados o ataques.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5b43060c-b730-43a6-8bd3-0068ba5b6da1'::uuid, 'Seguro', 'El monto pagado sobre el valor de la mercancía para cubrir los posibles daños que sufra durante su transporte.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c56da89b-a376-4427-b858-902854c31954'::uuid, 'Seguro de carga', 'El monto pagado sobre el valor de la mercancía para cubrir los posibles daños materiales que sufran las mercancías durante su transporte.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fed3236b-5cbd-4135-b605-e69babb06c9a'::uuid, 'Selección de personal', 'Fase del proceso de contratación que sigue al reclutamiento, donde se evalúan y elige entre los candidatos al más idóneo para el puesto.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2c39bbe5-240b-4d40-9f62-492eb46ae14b'::uuid, 'Semi-neto', 'Resultado de la empresa antes del impuesto sobre las utilidades. Refleja el desempeño operativo y financiero previo al impacto fiscal.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('20f9d46f-9496-4a37-a5a0-aef1d3e18555'::uuid, 'Semidirigido', 'Método de almacenaje donde el sistema sugiere una ubicación destino para el artículo trasladado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('afaaa296-f644-4195-91d7-0a17154cd45d'::uuid, 'Semineto', 'Utilidad antes de ISLR', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ce7548a6-df5e-42ec-b319-3806d7282e89'::uuid, 'Servidores', 'Computadoras de gran capacidad que ofrecen servicios a otros dispositivos, por ejemplo el servidor que guarda los correos o archivos compartidos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('54a33a25-c745-479f-b1c3-ba627aa637c9'::uuid, 'Sesgo', 'Tendencia sistemática al sobrepronóstico o subpronóstico', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1996c917-a8e4-4e99-b054-639c4d9b38d2'::uuid, 'Shojinka', 'Shojinka significa "línea de mano de obra flexible" y la capacidad de ajustar la línea para satisfacer los requisitos de producción con cualquier número de trabajadores y cambios en la demanda. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a52482cb-ff4e-4483-a854-456704e1b862'::uuid, 'Silo', 'Muestra las divisiones de la compañía a nivel macro en relación a sus procesos funcionales: Compra, Ventas, Logistica, Control, Mercadeo, Personal, Sistemas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('144e2195-0a48-429e-a4cd-79fee80d39c0'::uuid, 'SIP', 'Sistema de Información de Personal. Sistema o repositorio digital centralizado donde se gestiona y almacena toda la información laboral de los colaboradores (expedientes, evaluaciones, reconocimientos, etc.).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1791d892-b194-4555-bcaa-e03ddd81ef8c'::uuid, 'Sistema armonizado', 'Es una nomenclatura internacional y polivalente de productos que ha sido elaborada por la Organización Mundial de Aduanas (OMA).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8feb4cb2-4aad-4907-9ab0-b6aed6da3df7'::uuid, 'Sistema contra incendio', 'Conjunto de equipos y protocolos (alarmas, extintores, hidrantes, etc.) para prevenir y combatir incendios.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e7492691-6072-4feb-9b51-6d566bc6042e'::uuid, 'Sistema de alisto de mercadería', 'Una parte vital de la cadena de abastecimiento que implica la administración de recursos, zonas de acceso y algoritmos de extracción de artículos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2cb21705-9af5-4a42-a167-9cf5d4b7e452'::uuid, 'Sistema de producción Toyota (tps)', 'Una metodología fruto de más de 50 años de KAIZEN™ en Toyota. TPS se basa en la nivelación, con los pilares de apoyo de Justo a Tiempo y Jidoka.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('41091523-3253-4fd7-b83a-db5886b0ad05'::uuid, 'Sistema de reportes', 'Plataforma centralizada para la compilación y consulta de reportes de las diferentes áreas de la compañía.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2ba4a1d9-91cd-47b2-8b54-2b66ea9973eb'::uuid, 'Sistema de sugerencias kaizen', 'El Sistema de Sugerencias KAIZEN™ es parte esencial de un KAIZEN™ orientado al individuo. Su diseño se planifica, implementa y comunica cuidadosamente. Se presta especial atención a la capacidad de respuesta de la alta dirección y al desarrollo de un sistema de retroalimentación, reconocimiento y recompensas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9057d4ee-f655-4b55-b0a6-5f8118e68d6b'::uuid, 'Situación de trabajo', 'Estado actual de una acción: disponible (DISP), atendida (ATEN), terminada (TERM), problema (PROB), anulada (ANUL).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7fdaf5c0-4fa4-4a8f-9576-3ae2967c3909'::uuid, 'SKU', 'Stock Keeping Unit (en español: Unidad de Mantenimiento de Inventario). Es un identificador único que se asigna a cada producto o variante de producto dentro de un inventario.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('79a29291-7ef4-4c12-86fe-531df77276bf'::uuid, 'SKU activados', 'Silo Ventas: Códigos de productos que están actualmente disponibles para la venta en el inventario. Reporte SIM – Indicador Venta: SKU con ventas mayores que cero.', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('c3e24b9c-2bd1-4fc4-a55e-f48be04058e6'::uuid, 'SKU activados %', 'La proporción de productos o referencias (SKU) que han sido activados o puestos a la venta en un período determinado, en relación con el total de artículos disponibles en el inventario', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8ef2955f-79ff-423c-a3da-208f222da23e'::uuid, 'SLA´s', ' “Service Level Agreement”.  Acuerdo de servicio, es el acuerdo formal que se realiza entre dos partes (la compañía y el cliente) para definir la entrega de un servicio. Los SLA´s se negocian con el fin de asegurar que el Macroproceso / Proceso se ejecute en los tiempos en que es requerido, eliminan retrabajo, inconformidades o no entendimientos entre las partes que interactúan dentro de un Macroproceso / proceso. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5ebe4eaf-9346-4ed8-8604-3aa57aec8c58'::uuid, 'SMAPE', 'Silo Logística: Variante simétrica del MAPE para reducir distorsiones.', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('e253ac7f-8474-46b6-bcfa-76ba8e30044c'::uuid, 'Sobrantes', 'El cliente recibe artículos adicionales no indicados en la factura.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('dff5dbdf-7bae-403d-b91a-140e9b1437f7'::uuid, 'Sobre giro bancario', 'Exceder el crédito más allá de las posibilidades de pago del deudor.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c264cc12-7a44-4236-8e7b-29dcffe765c0'::uuid, 'Sobre inventario', 'Exceso de inventario proyectado que contempla lo que se encuentra en almacén, las órdenes de compra en tránsito, el pronóstico de venta durante los días de anticipación y lo requerido para un ciclo de pedido', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6526b818-0470-4ff7-b26e-f90478900bcb'::uuid, 'Sobreinventario', 'Es la situación en la que se almacena una cantidad de productos superior a la demanda real o proyectada durante un período determinado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7c422c16-f5b4-41d0-a7b3-3d1fc078f3dc'::uuid, 'Software', 'Programas y aplicaciones que se instalan o se usan en los dispositivos, como Word, Excel o un sistema de facturación.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2e4e3059-f525-43c3-80f7-e344bc29b1a2'::uuid, 'Solapamiento', 'Coincidencia entre dos o más promociones sobre el mismo SKU, audiencia, canal y vigencia.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f4d81610-e298-44d7-9073-07a2f8e1dd07'::uuid, 'Solicitud de cancelación de pedido por parte del cliente', 'El cliente desea cancelar el pedido, previo a la entrega y ya está facturado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2240bfcf-6b5b-4cfe-9bc7-a8d519f9f5a8'::uuid, 'Solicitud de compra', 'Documento interno de la empresa, en el que los departamentos y funcionarios hacen sus requisiciones de materiales al encargado de compras.', 'Solicitud de Compra', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:43:07.588Z'::timestamptz),
  ('5434056d-1a08-45c5-bc3b-9e45c7077530'::uuid, 'Solicitud de reclamos y observaciones', 'Procedimiento para levantar un reclamo sobre una orden de recepción.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('261e142e-d769-4018-b13d-ac2dd81678a5'::uuid, 'Solicitud de reparación', 'Solicito la reparación del artículo. Los costos asociados a la reparación serán cubiertos por el cliente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('980a5d45-bd32-423b-83eb-50a2b4b51c54'::uuid, 'SPI', 'Sistema de Nomina', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('34d0d6de-e29b-495b-b263-d21bea4770e4'::uuid, 'Sprint', 'Entrega parcial del proyecto, con alcance delimitado, que permite la validación progresiva de funcionalidades y la reducción del riesgo global del proyecto.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2b406ca5-792c-45ed-b4c9-9f825fe0aeb9'::uuid, 'Stakeholder (parte interesada)', 'Persona o grupo que tiene interés o se ve afectado por el proceso.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('dd6e9c86-f0d6-4976-a69e-32bf6d4653b5'::uuid, 'Status bar', 'Espacio ubicado en la parte inferior de una ventana cuya función es informar y brindar asistencia rápida sobre las opciones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('41cf3794-1642-47d7-b466-28602faaa24c'::uuid, 'Stock de seguridad', 'Cantidad mínima que debe existir en el inventario, para asegurarse que no se produzcan faltantes en el momento requerido.', 'STOCK DE SEGURIDAD', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('fa757d8e-dd8a-4f61-b6ab-9cb2cbbd13f1'::uuid, 'Streamline', 'Silo Logística: Plataforma de la cadena de suministro diseñada para optimizar los procesos S & OP actuales.', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('4eddd612-e921-49aa-b4ce-c1540976cc8d'::uuid, 'Sub-Categorías', 'Reporte SIM – Dimensión Compras: Una división más específica dentro de una categoría. Reporte SIM – Filtro Compra: Permite filtrar por una o mas divisiones específicas dentro de una categoría.', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('697736ac-1a9a-4a0a-8d79-b408a0fcafbe'::uuid, 'Sub-subtipo', 'Ofrece un detalle más específico para registrar la transacción de inventario.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('77f4b86f-86c0-4aa9-98cd-db5f53faef75'::uuid, 'Subcategorías', 'Una división más específica dentro de una categoría. Cada categoría debe contener un rango de 10 a 30 subcategorías. Al igual que las categorías, sus nombres deben ser descritos en singular, en mayúsculas y sin acento.', 'Nombr Sub Categoría', NULL, NULL, false, NULL, false, false, NULL, '2026-09-30T19:30:00.000Z'::timestamptz),
  ('2df81113-36e6-4328-8e52-c6f36a711690'::uuid, 'Subproceso', 'División específica dentro de un proceso mayor que cumple una función determinada.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ab58f521-3580-463c-a423-12b1783bb590'::uuid, 'Subtipo de transacción', 'Establece una clasificación según el tipo de transacción que se haya elegido y determina el estado del inventario afectado (disponible, cuarentena, reservado o vencido).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7b4711b1-75f6-43d9-8183-9aec39fd2dee'::uuid, 'Sucesión', 'Silo Personal: Proceso planificado de identificación, evaluación y desarrollo de talento interno para asegurar la cobertura futura de posiciones críticas o clave dentro de la organización. Reporte SIM – Indicador Personal: Es un proceso estratégico mediante el cual una organización identifica y prepara a colaboradores clave con el potencial (N) y el desempeño (M/P) necesario para ocupar posiciones críticas en el futuro, asegurando así la continuidad del liderazgo y la operación del negocio.', '', 'fusionado'::estado_origen_termino, 'Fusionado a partir de 2 filas originales.', true, NULL, false, false, NULL, '2026-09-28T16:00:00.000Z'::timestamptz),
  ('041c8239-2716-40f5-a246-4e86b9cff44c'::uuid, 'Sucesión %', 'Es un indicador crítico de robustez del talento que mide el grado de preparación de una organización para llenar sus posiciones de liderazgo críticas desde dentro.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('42e972b0-9a7b-4aec-93b4-c663bc40bfca'::uuid, 'Sucesión N3', 'Es un indicador de gestión del talento que identifica específicamente a los colaboradores con el más alto desempeño (M5) que se encuentran en una etapa intermedia de desarrollo (Nivel de Potencial 3) y que ocupan posiciones de mediano rango (Paso {4,5}), constituyendo la cantera principal para posiciones críticas de liderazgo en el largo plazo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('612dbd3b-6fe9-4b93-9d2f-86d695763fbd'::uuid, 'Sucesión N3 %', 'Es un indicador de profundidad del bench de talento que mide la proporción de posiciones de nivel senior (≥3) para las cuales la empresa ha identificado candidatos internos de alto desempeño y alto potencial (M5, N≥3) que, si bien no están listos para una promoción inmediata, constituyen la cantera de futuros líderes para esas posiciones críticas en el mediano y largo plazo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('07a48ef6-57f3-4775-bb23-62b229838a2f'::uuid, 'Sucursal', ' Divisiones que se realizan a nivel de compañía para separar los documentos e inventarios en subpartes más pequeñas. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('404d183c-af0b-4fb9-a32c-4ceaf24ecde5'::uuid, 'Supervisor', 'Líder operativo que no solo gestiona tareas, sino que también se enfoca en el desarrollo y el bienestar de su equipo para lograr los mejores resultados.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c6fac623-e13f-437f-b2cf-e865297a6e3a'::uuid, 'Supervisor Colaboradores', 'es un profesional encargado de guiar, coordinar y evaluar el trabajo de un equipo de colaboradores para asegurar el cumplimiento de los objetivos operativos y mantener estándares de calidad, productividad y clima laboral.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8af202d1-87c0-4f5b-9036-82b3d7f6adea'::uuid, 'Surtido Activo', 'Surtido regular con inventario (incluye descontinuados).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3ab7bcf9-2e51-422c-b1f6-7a655a3090da'::uuid, 'Surtido Comercial', 'Se refiere a todos los articulos exceptuando los articulos de Mercadeo, Servicios Generales y Taller.', 'SURTIDO COMERCIAL', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('d3d631ec-ee1f-402f-aab6-13401de6258a'::uuid, 'Surtido no regular', 'Se refiere a la variedad de productos que no forman parte de la planificación regular de reposición, incluyendo los combos y los Kits. Los tipos de artículos de este surtido incluye: Nuevos (N), Ocasionales (L), de Temporada (T), Pedido Especial (P) y Complementarios (J), los cuales se reponen en determinadas épocas del año o bajo solicitud específica de un cliente. Además, se consideran productos Descontinuados (E), Suspendidos (Z), así como Mercadeo y Suministros (S), que no están incluidos en el proceso de reposición.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1abba21b-63e6-4c4a-9910-70a51fa94299'::uuid, 'Surtido regular', 'Se refiere al surtido comercial a excepción de Pedido Especial, Temporada (Ocasional), Nuevos y Descontinuados. Estos  son: Básicos (B, D, F), Complementarios (H, K, M).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('78cf0901-6155-42b8-a23e-27d20ba307f7'::uuid, 'Surtido vigente', 'Hace referencia al surtido regular menos Descontinuados.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0322d9de-7862-439b-a78f-328a988c460f'::uuid, 'Sustitución', 'El proceso de reemplazo de un artículo existente por uno nuevo en el portafolio de productos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('371225f8-e022-4688-8db6-2e197b108037'::uuid, 'Sustituto', 'Un artículo que puede reemplazar a otro en caso de que este no esté disponible, manteniendo características y funcionalidad similares para satisfacer la demanda del cliente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('325eb394-b130-4c74-9bc1-5aae21082b7c'::uuid, 'Súper usuario', ' Persona con perfil de administrador capacitada en las funcionalidades del sistema eflow WMS. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3326f43c-e43c-42ab-934a-641dd88dc5b3'::uuid, 'T.E.F (transferencia electrónica de fondos)', 'Operación que registra el movimiento electrónico de dinero entre cuentas bancarias.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0a000ef5-f710-4608-b489-95a32d6f1578'::uuid, 'Tabla de Dimensiones', 'Estructura que contiene los atributos descriptivos de un proceso de negocio. Se utiliza para segmentar, filtrar y categorizar los datos (ej. Dimensión Geográfica, Dimensión Tiempo, Dimensión Producto).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6b1bc498-8c49-4068-9560-6e5a035893d5'::uuid, 'Tabla de Hechos', 'Tabla central de un modelo de datos que almacena las métricas cuantitativas o medidas de un proceso de negocio (ej. cantidades vendidas, montos facturados), las cuales son susceptibles de ser agregadas o calculadas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e231b9cf-29ee-4eea-8f10-c5177d500b16'::uuid, 'Tabla Plana', 'Estructura de datos bidimensional (filas y columnas) que carece de relaciones jerárquicas complejas, celdas combinadas, subtotales o formatos de presentación humana, siendo el formato óptimo para el procesamiento automatizado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('721e35d7-7367-4681-91ba-3f58fc6dd79c'::uuid, 'Tarea', ' Conjunto de pasos simples interrelacionados para lograr un objetivo. En este nivel se identifica “quién hace qué” (un agente, un tiempo, múltiples pasos). ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('dbcb06fe-e449-40f7-9532-58c4d8c301a3'::uuid, 'Target', 'También conocido como "público objetivo", se refiere al grupo de personas a las que se dirigen los productos o servicios de una empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e4309837-bb68-462c-9be0-378293dc4019'::uuid, 'Tasa de conversión', 'es una métrica clave que mide el porcentaje de usuarios que completan una acción deseada en un sitio web, un anuncio o una campaña. Es una forma de evaluar la efectividad de una estrategia.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6d2a8e10-fe4c-448c-917a-c5a3daa4f0fe'::uuid, 'Tasa impositiva', 'Es el porcentaje (%) de impuestos que corresponde pagar al fisco por algo que la ley manda.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c9d1b478-dc12-4ebb-a043-5fff729219e0'::uuid, 'Tecnología', ' Especificar si para llevar a cabo la Tarea se utiliza un sistema automatizado específico o se usa determinada herramienta. Puede también usarse como el conjunto de Software y Hardware que utiliza un proceso para llevar a cabo sus objetivos.  ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c0618a4a-4e73-4c62-ae71-428188e3d152'::uuid, 'Temporal', 'Estado del empleado que indica si el mismo trabaja fijo o por temporada.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('00dc4458-9419-47a7-a5b2-0b2a3b47105c'::uuid, 'Terceros', 'Personas o empresas subcontratadas para servicios específicos (limpieza, etiquetado, etc.).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('613f5862-3ed2-4f20-ade9-c440ccedd7ad'::uuid, 'TERM (terminada)', 'Tareas que ya fueron atendidas en la RF y se realizó un proceso sobre las mismas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6a65040a-25f1-44b9-a595-6d74425aecc4'::uuid, 'Terminación de contrato', 'Conclusión de la relación laboral, que puede darse por diversas causas: mutuo acuerdo, renuncia voluntaria, despido, expiración del término pactado, entre otras.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5f23cb83-ef3c-44bf-8af2-7b321416b0fa'::uuid, 'Terminales de radio frecuencia (rf)', ' Equipos también llamados “Hand Held (HH)”, son computadores móviles, capaces de ejecutar un sistema informático y de comunicarse mediante protocolos WIFI o Bluetooth, hacia el servidor central. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('48864aed-d824-4ef7-9795-df0ac6bc1fff'::uuid, 'Terminales desktop', ' Equipos de cómputo tipo PC, para la ejecución del sistema eflow WMS. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a37fdd19-4089-40b7-9e43-16846e79a599'::uuid, 'Terminar el palet (en picking rf)', 'Indica que no se alistarán más artículos en el contenedor, pero aún no se ubicará en el destino asignado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ddb42d92-addd-465f-b8fa-d8798305b1e0'::uuid, 'Ticket de auditoría', 'Conteo de artículos que se generan por criterio del Coordinador de Control de Inventario. Este conteo incluye aéreos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6ad7be9b-3426-4d81-aac1-cc60be45b191'::uuid, 'Tiempo takt', 'El tiempo Takt, un elemento vital para equilibrar los flujos de producción de piezas individuales, se calcula dividiendo la demanda diaria total de los clientes en unidades completadas (televisores, automóviles, abrelatas y similares) por el número total de minutos o segundos de producción trabajados en un período de veinticuatro horas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6e702e79-7fd0-48b5-ba12-20e664220179'::uuid, 'Tipo', 'Este campo ubicado en la pestaña de Clasificaciones de la ventana articulos, indica si el articulo se encuentra disponible para la venta o no disponible para la venta, colocando P1 o P2 respectivamente.', 'Tipo', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('629be99e-7eaa-4abe-a141-95412f8b5cf1'::uuid, 'Tipo Codigo de Barra', 'Campo en la ventana de artículo donde se especifica si el codigo de barras es genérico.', 'Tipo Codigo de Barra', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T14:05:00.000Z'::timestamptz),
  ('18e2ecc7-01d9-49bd-8ef3-1f3e8a204d54'::uuid, 'Tipo de artículo', 'Se refiere a la clasificación de los productos en categorías, subcategorías y familias para organizar el surtido.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('264823e9-dfda-4a88-b0c4-90f695ac85ec'::uuid, 'Tipo de asiento', 'Distingue el presente asiento de entre un conjunto de tipos de asiento que el usuario puede definir. ​', 'Tipo de Asiento', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:43:16.424Z'::timestamptz),
  ('dfe56a6e-7106-47bb-bf4c-100185c40cf9'::uuid, 'Tipo de cambio', 'Tasa a la que una moneda puede ser cambiada por otra. Su fluctuación genera riesgo cambiario.', 'Tipo Cambio', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:43:24.496Z'::timestamptz),
  ('293085ac-402d-429e-9ca8-870fec95dea1'::uuid, 'Tipo de carga', 'Modalidad de despacho de los artículos: por palet completo, único o múltiple.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('979d4728-f5ea-46dc-9471-ac3f09498a8a'::uuid, 'Tipo de contabilidad', 'Determina si la transacción contable se manejará solo en la contabilidad Fiscal, en la Corporativa o en Ambas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('cb97e6c5-3944-4fda-9b24-d594e1849f14'::uuid, 'Tipo de cuenta', 'Define si la cuenta es de Balance de Situación o de Estado de Resultados. ​', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8565d76f-c016-47ae-bded-91436403bccc'::uuid, 'Tipo de dato', 'Atributo que indica al sistema la naturaleza de la información contenida en un campo (ej. Integer para números enteros, Decimal para valores monetarios, String para texto y Date para cronología).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('10788374-99fb-4ffb-8bfb-3a7813f8abfc'::uuid, 'Tipo de estiba', 'Clasificación que define la forma en que se organizan, apilan y aseguran las mercancías o cargas sobre una unidad de transporte (pallet, contenedor, bodega de buque, camión, etc.), según criterios como la naturaleza del producto, su resistencia, forma, peso y condiciones de manipulación. Busca garantizar la estabilidad de la carga, optimizar el espacio disponible y prevenir daños durante el almacenamiento o el transporte.', 'Tipo de Estiba', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('5bdaa8dd-d10a-446f-b999-7b1975bf19e1'::uuid, 'Tipo de Pick', 'Silo Compras: Se refiere a cómo se debe preparar un pedido antes de su envío: pieza, inner, caja, tarima, kg, rollo. Silo Logística: Define desde cuál nivel de empaque se realiza el picking (preparación de pedidos) en el almacén para despacho al cliente. Los valores aplicables son: unidad, inner, caja, tarima.', 'Otros - Tipo de Pick', 'dudoso'::estado_origen_termino, 'Compras y Logística listan valores distintos (Compras agrega kg y rollo; Logística usa “unidad” en vez de “pieza”). Se fusionó asumiendo que es el mismo campo operativo visto desde dos áreas.', false, NULL, false, false, NULL, '2026-09-30T20:00:00.000Z'::timestamptz),
  ('5d96c2cc-4617-4b49-8068-3f2e9e13b461'::uuid, 'Tipo de Producto', 'Campo en la ventana de artículo donde se especifica si el producto es terminado, kit, de servicio, entre otros.', 'Tipo de Producto', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('e5183cc3-7824-4305-a32f-354352d5454f'::uuid, 'Tipo de recepción', 'Clasificación de la orden según su origen: RECERP, RECLIB, RECTRA, etc.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c84cb905-2f59-4f59-a84e-d236e795236c'::uuid, 'Tipo de tarea', 'Clasificación de acciones operativas (ej. picking, carga, recepción).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e85b69d6-3fa2-418d-a801-661a9988febb'::uuid, 'Tipo de transacción', 'Es un campo específico en la estructura de la facturación electrónica en Costa Rica, que se utiliza para definir la naturaleza de la operación para efectos fiscales y de declaraciones.', 'Tipo de transacción', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('9795572c-0c9f-4f49-b7a0-d0e3f8e78d61'::uuid, 'Tipo de transacción contable', 'Define transacciones contables que involucran el mismo tipo de transacción. Por ejemplo, cheques, planilla, vacaciones, cesantía, etc.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e73b53ac-c63d-460c-9523-609cb86efe05'::uuid, 'Tipografía', 'es el arte y la técnica de diseñar y organizar el texto para hacerlo legible, atractivo y significativo. Va más allá de elegir una fuente bonita; se trata de usar el tipo de letra para comunicar la personalidad de una marca, crear jerarquía visual y guiar la mirada del lector.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('76726aa3-83cd-4406-a13f-ebca190b4ed0'::uuid, 'Tipos de artículos', 'Incluyen Co-producto, Desecho, Fantasma, Kit, Laboral, Mat. Empaque, Materia Prima, Otros, Proceso, Refacción, Reproceso, Semielaborado, Servicio, Subproducto y Terminado. Los artículos con tipo Proceso, Laboral, Servicio, Fantasma, Kit, Reproceso y Otros no se incluirán en reportes de existencias ya que no tienen existencias en inventario.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('c2e11444-fe54-4c3a-bd8c-92233254f353'::uuid, 'Tipos de trabajo', 'Un filtro para observar la cantidad de tareas asignadas para un tipo de trabajo específico.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d0d381a3-011d-4d50-9eee-6d25cac79f33'::uuid, 'Tipos de transacciones contables', 'Los tipos de transacción contable corresponden a clasificaciones de las transacciones contables generados por tipos de movimiento. Por ejemplo, las transacciones contables pueden clasificarse si corresponden a generación de cheques, aunque estos cheques se hagan para cualquier transacción.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e23d656f-8c3e-4366-bbaf-190025163170'::uuid, 'Tipos de transacción', 'Incluyen Consumo - Dev., Ensamble, Físico, Producción y Traspaso.', 'Tipo Transacción', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:43:30.982Z'::timestamptz),
  ('e18046eb-d216-491c-bd6b-6a74407f3a23'::uuid, 'Tipos de unidad de transporte', 'Incluyen los diferentes tipos Cabezal, Camiones repartidores, Furgón.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('654c1872-b5d2-40ad-bb14-4ecee6f6217c'::uuid, 'Tir (tasa interna de retorno)', 'La tasa de descuento que hace que el VPN de un proyecto sea igual a cero. Representa la rentabilidad intrínseca del proyecto. Una inversión es viable si su TIR es mayor que el costo de capital.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2c93e8f5-c147-4522-bee5-7cfabdf6a517'::uuid, 'Titulo', 'es un elemento de texto breve que se utiliza para presentar, resumir o dar un nombre a un contenido, como un artículo, un anuncio, un video, un libro o una página web.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ab749864-d037-418c-8dfc-435580556cce'::uuid, 'Titulo de cobertura', 'Instrumento financiero (como un forward o una opción) utilizado para mitigar el riesgo de fluctuaciones adversas en tipos de cambio o tasas de interés.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a26be7ef-360f-4975-b63a-01a6644724f8'::uuid, 'Tolerancia', 'Margen de tiempo permitido para la entrada y la salida del empleado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e375d010-fd7d-49f0-9ca5-abfdb66f3b63'::uuid, 'Toma física', 'Proceso de conteo manual de inventario para validar cantidades reales versus sistema.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6e4b9778-1bf3-4002-b261-fbf42a3cd5a5'::uuid, 'Toma física de auditoría', 'Aplica para controles de auditoría en el almacén.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('55d70e88-30fc-4180-b911-c8260ca7a4b3'::uuid, 'Toma física de muestreo', 'Aplica a tomas físicas que no requieren actualización de inventario, utilizadas para analizar el inventario físico y teórico.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fc1a8706-9e83-4752-b54e-d8effedaea30'::uuid, 'Toma física dirigida (ubicación – artículo)', 'Un tipo de Toma Física donde es necesario indicar el o los artículos que se desean contar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('05c5c140-fef3-4c12-b634-a1811b4d2d50'::uuid, 'Toma física dirigida (ubicación)', 'Un tipo de Toma Física donde es necesario indicar la o las ubicaciones que se desean contar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3f32b16d-b478-4618-8b65-dcb6609da984'::uuid, 'Toma física libre', 'Un tipo de Toma Física donde no es necesario restringir la toma por ubicaciones o artículos, pero se puede restringir a un usuario específico.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3cc129a8-7ec5-46bb-b045-5bf23a43e3cf'::uuid, 'Toolbar', 'Barra con iconos que forma una especie de submenú gráfico de fácil utilización, pues las opciones se aplican al activar un icono posicionando el cursor del ratón y presionando el botón izquierdo. ​', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e7ea765d-97d7-4634-b47b-cac473ab16f1'::uuid, 'Trabajo automático', 'Procedimiento para iniciar la atención de tareas en RF, donde eflow-WMS asigna tareas a los recursos disponibles.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2d58e261-8012-434b-a6d5-f700ba9fb79b'::uuid, 'Transacción', 'Una transacción u operación es cualquier evento (o suceso) o condición, cuyo reconocimiento se expresa en forma de un asiento en los registros de la contabilidad. ​ Expuesta en cantidades monetarias, una transacción u operación, tal como la concibe un contador, se encuentra formada por una igualdad entre créditos y débitos; los primeros representando el origen y los segundos la identificación y la disposición inmediatas. ​ ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a28bc089-0eb5-4d76-bd29-12a4992c7c71'::uuid, 'Transacción contable', 'Análisis en un diario de los efectos de una transacción en las cuentas contables, usualmente acompañado por una explicación. En algunos países el concepto de transacción contable se define por términos tales como: póliza, boucher, etc.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('391fe4d0-e459-45cb-9d7e-56472fa751a0'::uuid, 'Transacción de inventario', 'Operaciones que deben realizarse para mover artículos del inventario, ya sea ingreso, salida o traslados de una bodega a otra o dentro de la misma bodega. Al ser aplicadas, registran un asiento contable en el módulo de Contabilidad General.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6dd12e2c-8e01-4999-ad7e-45a1bca4cbad'::uuid, 'Transferencia de stock', 'Movimiento de inventario entre ubicaciones dentro del almacén.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('70f77e1a-9787-4f39-a82c-9a8c36ee9253'::uuid, 'Transferencia electrónica de fondos', 'Una transferencia electrónica de fondos (T.E.F.) es una transacción que permite al cliente pagar documentos pendientes por medio de un depósito electrónico del monto parcial o total del documento a una cuenta bancaria de la compañía. Para poder generar una T.E.F. es preciso que tanto el cliente como la compañía tengan cuentas bancarias en la misma entidad financiera.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b38e2a7f-582e-4c3f-88aa-a4bbe64925c4'::uuid, 'Transportista', 'Conductor de vehículos que realiza entregas o recolecciones de mercancía.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2351ce25-b4aa-43a6-9da7-dc63a17d5588'::uuid, 'Trazabilidad', 'Silo Procesos: Capacidad de seguir el historial, aplicación y cumplimiento de una norma o proceso. Silo Logística: Registro digital completo de cada pedido desde recepción hasta entrega final.', '', 'dudoso'::estado_origen_termino, 'Silo Procesos define un concepto general de cumplimiento normativo; Silo Logística describe específicamente el registro digital de pedidos en el CEDI. Se fusionó como concepto general + su aplicación en Logística.', false, NULL, false, false, NULL, NULL),
  ('c93c4600-d7bf-4590-886f-757f38e615e4'::uuid, 'Turno', 'Horario asignado a un recurso para operar en el sistema.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4043ee9d-a16b-457b-9c5f-e81bbcb1afdd'::uuid, 'Turno de trabajo', 'Período de horas durante el cual el empleado debe prestar sus servicios. Pueden existir turnos diurnos, nocturnos, rotativos o mixtos, cada uno con regulaciones específicas sobre recargos', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('03fcd378-880c-4476-8d8c-410f7f939db9'::uuid, 'UAT (User Acceptance Testing)', 'Validación del producto con usuarios reales antes del despliegue a producción.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('28c22366-7950-4c53-8b25-baf908e71265'::uuid, 'Ubicación de referencia', ' Para cada referencia de artículo se puede gestionar un punto dentro de una zona almacenaje que funcione como eje de gravedad en los algoritmos de búsqueda de ubicación. El algoritmo de ubicación trata de colocar el producto lo más cercano posible a esta ubicación de referencia. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('514eb4f7-56fd-4cbb-8c81-3ee13438eb13'::uuid, 'Ubicación libre', 'Funcionalidad que permite trasladar artículos de un palet a otra ubicación sin restricciones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e4ee354c-5f5c-45ea-8431-8ef8f003560f'::uuid, 'Ubicar el palet (en picking rf)', 'Indica que no se alistarán más artículos en el palet y este se ubicará en el destino asignado.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2afbcd91-311d-4d7f-b100-57ebb1684950'::uuid, 'Unidad almacenamiento', 'Unidad de medida en la que se almacenan los artículos en la bodega y con base en la cual se realizan las transacciones de inventario.', 'Almacenamiento', NULL, NULL, false, NULL, false, false, NULL, '2026-09-30T19:30:00.000Z'::timestamptz),
  ('393b0f55-08ce-4d63-b3b5-fd39156ce464'::uuid, 'Unidad de detalle', 'Establece el número de unidades elementales del artículo que componen la unidad de almacenamiento. Existe un factor de conversión entre estas dos unidades.', 'Detalle', NULL, NULL, false, NULL, false, false, NULL, '2026-09-30T19:30:00.000Z'::timestamptz),
  ('e6c315bd-69d8-47a0-8d71-b4ab47fc0b67'::uuid, 'Unidad de negocio', 'División de una empresa que opera de forma semiautónoma, con su propio mercado, clientes y estrategia, pero integrada en la estructura corporativa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('39ac923f-bfcd-4f71-b969-261d3f1a0593'::uuid, 'Unidad de transporte', 'Vehículo o equipo utilizado para realizar la carga de pedidos; puede ser cabezal, furgón, etc.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('b77bed1c-168c-4b07-b731-88002527e3c5'::uuid, 'Unidad Medida C', 'Campo UDF donde se indica la unidad de medida para Magnitud Comercial. Ej: Kg, m, m2, m3', 'Unidad_Medida_C', NULL, NULL, false, NULL, false, false, NULL, '2026-09-30T19:30:00.000Z'::timestamptz),
  ('6594335b-3a50-487f-8899-361e86c6e1f7'::uuid, 'Unidad medida compra', 'Unidad de medida para solicitar a los proveedores las materias primas o suministros.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('e0dbd68f-aff5-44de-8ff4-651335f1699e'::uuid, 'Unidades de distribución', 'Función para llevar el control de hasta ocho presentaciones diferentes que maneja cada artículo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('3818befa-bd67-48a3-bb6c-ea5a8001f76f'::uuid, 'Unidades de medida', 'Patrón en el que se miden los artículos del inventario, según el fin que se necesite considerar  almacenamiento, detalle o venta.', 'Unidad de Medida', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:43:42.833Z'::timestamptz),
  ('1375b3e7-717b-417c-a20a-7a72a4f15982'::uuid, 'Unidades de transporte', 'Unidades que se crean en el módulo de catálogos y se configuran para realizar el proceso de carga de camión.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('2c317644-5539-4ba8-bc27-6d7151007ee9'::uuid, 'Unidades en inventario', 'La cantidad de unidades teóricas de un artículo', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9b832008-8b58-4016-b716-f08e6da13959'::uuid, 'Usuario', 'Persona con acceso al sistema, configurada con nombre, clave y permisos.', 'Usuario', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:47:42.986Z'::timestamptz),
  ('b0b19564-212b-4549-912d-262634e249d4'::uuid, 'Vacaciones', 'Período de descanso al que tiene derecho el empleado, después de cada año de trabajo, que es exigido por la legislación laboral del país, o inclusive por convenciones colectivas con sindicatos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('aebf0e13-48cd-4ec4-8635-0ef01c9778ce'::uuid, 'Vacaciones adicionales', 'Período de descanso al que tiene derecho el empleado, después de cierto periodo de trabajo definido por políticas propias de la empresa que las otorga como un incentivo a los empleados. No es exigido por la legislación laboral del país.', 'Vacaciones adicionales', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:47:45.879Z'::timestamptz),
  ('7b203557-e87c-48cf-8160-619fc2f803a9'::uuid, 'Vacante', 'Puesto de trabajo que se encuentra disponible para ser ocupado, ya sea por una nueva creación o porque la persona que lo ocupaba lo dejó libre.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('8a87022f-31b1-4504-b089-dc78b81e0d27'::uuid, 'Vale', 'Comprobante de entrega de efectivo, para la realización de compras o gastos según el concepto definido.', 'Vale', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:47:48.342Z'::timestamptz),
  ('ce76ed35-9cfe-4d56-b841-bc9faeaee146'::uuid, 'Validación', 'Confirmación de que el conteo fue realizado correctamente y coincide con el sistema.', '', NULL, NULL, false, NULL, false, false, NULL, NULL)
ON CONFLICT DO NOTHING;

INSERT INTO terminos (id, termino, definicion, campo_softland, estado_origen, nota_origen, revisado, nota_decision, es_nuevo, editado, eliminado_en, actualizado_en) VALUES
  ('38bc65b5-56a1-4bff-9ae7-b4b842891b62'::uuid, 'Validación de carga', 'Confirmación de que los artículos alistados han sido efectivamente cargados en el vehículo.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('956685dd-1a2e-411f-a6e1-bdad3fb73896'::uuid, 'Validación general', 'Proceso en RF para registrar artículos recibidos, incluyendo lote y fecha de vencimiento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('69f989f3-e848-4083-8dd7-013ac74d4a11'::uuid, 'Validación general (en rf)', 'Una de las dos pantallas utilizadas en la Terminal de Radio Frecuencia para el ingreso de mercadería.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1d4c950f-1612-428d-a537-e61b4a668b74'::uuid, 'Valores organizacionales', 'Principios fundamentales y creencias que guían el comportamiento y la toma de decisiones dentro de una empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fda4ffce-abca-40d8-96bd-b5cca68d2341'::uuid, 'Variable decisión', 'Para las fórmulas que se configuran como tablas, la variable de decisión es el criterio para escoger el rango adecuado.', 'Variable de decisión', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:38:35.241Z'::timestamptz),
  ('7a261012-2ffb-4e4e-aaa5-a8e219f24218'::uuid, 'Variación de precios', 'El incremento o la disminución del precio de un bien o servicio, ofrecido por un proveedor y notificado mediante una lista de precios.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a61e8b16-4566-495d-904e-5791f67c4378'::uuid, 'Vector', 'es un tipo de imagen digital que se crea a partir de puntos, líneas, curvas y formas geométricas, en lugar de píxeles. A diferencia de las imágenes rasterizadas (como JPG o PNG), que se basan en una cuadrícula de píxeles, las imágenes vectoriales se construyen con fórmulas matemáticas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('57033a94-22e4-456e-8861-e21e0f63ce1f'::uuid, 'Vehículo eléctrico', 'Es un medio de transporte que funciona con uno o más motores eléctricos, alimentados por la energía almacenada en baterías recargables o, en algunos casos, por una fuente de electricidad externa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('145f178a-0cfa-4239-8920-8377de6718df'::uuid, 'Vehículo híbrido', 'es aquel que utiliza dos fuentes de energía distintas para su propulsión: un motor de combustión interna (generalmente de gasolina) y uno o más motores eléctricos alimentados por una batería', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('ea3b2fb9-f85f-4954-b408-e1b410cb2a87'::uuid, 'Vehículo liviano/pasajeros', 'Son aquellos que transportan en esencia personas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('fe3f8acd-3ee3-45b3-a732-dc60eb0d0d2e'::uuid, 'Vehículo pesado', 'Vehículo de motor con un peso superior a las 3.5 toneladas, utilizado para el transporte de mercancías o personas', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('83365f02-180f-41b2-9b84-64caa69599fa'::uuid, 'Vencimiento', 'Estado que presentan los artículos que utilizan lotes cuando su vida útil ya ha expirado, es decir, cuando se ha sobrepasado la fecha definida como vencimiento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1ed8ae2a-ad38-4c8f-9928-4e1b952c1a0a'::uuid, 'Venta Bruta', 'Es la sumatoria de la venta excluyendo las bonificaciones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('387daf71-7103-49c5-bd88-4beb24a5bc44'::uuid, 'Venta Neta', 'Es la sumatoria de la Columna Venta en moneda local o dólar.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('caa9ded0-f931-4aeb-b70f-753d2eda05e8'::uuid, 'Ventas', 'Corresponde a las ventas netas presupuestadas, calculadas como facturación bruta menos devoluciones, descuentos y bonificaciones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1e7cbfe5-db38-48bc-9800-915a46827151'::uuid, 'Ventas del día', 'Opción para consultar las ventas realizadas en el día, mostrando datos como la moneda, la fecha, el total de pedidos, renglones, bruto, IVA y neto.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('31469c99-8f49-421d-8373-1a341d8b5963'::uuid, 'Versión', 'Número que indica cambios o actualizaciones en un documento.', 'Versión', NULL, NULL, false, NULL, false, false, NULL, '2026-10-02T01:48:00.313Z'::timestamptz),
  ('45111102-9fc7-4b15-a862-760d8e7f2470'::uuid, 'Vigencia', 'Periodo durante el cual el documento es válido y aplicable.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('bed27e34-f3c5-4254-aec1-05363d92e873'::uuid, 'Vigilancia', 'Servicio de seguridad encargado del control de acceso y permanencia en las instalaciones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4e59a1ae-d67c-413a-bcff-9ddaff5ec92f'::uuid, 'Visión / misión / valores', 'Elementos que definen la razón de ser, objetivos y principios rectores de la empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a00e81c5-2648-44c3-b75e-f0c4e7b9f5c8'::uuid, 'Visión por computadora', 'Tecnología que permite a las computadoras interpretar imágenes y videos (ej. reconocimiento facial).', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('24b8efef-8341-4dac-babd-0f7fa2aeabdc'::uuid, 'Visualización', 'Representación gráfica de la información, como gráficos de barras, líneas o mapas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('21f197bc-6e06-4efb-9879-21754d095abf'::uuid, 'Viáticos', 'Gastos incurridos por un empleado durante un viaje de negocios (hospedaje, comidas, transporte), que son reembolsados por la empresa.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('498d787d-69eb-46a8-ae00-28f51af29545'::uuid, 'Vpn (valor presente neto)', 'Método para evaluar la rentabilidad de una inversión calculando el valor actual de todos los flujos de caja futuros que generará el proyecto. Un VPN positivo indica que el proyecto crea valor.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4bbd5a69-9f33-4d72-80a6-09a6c0eac31c'::uuid, 'WACC', '(Costo Promedio Ponderado de Capital) La tasa de costo promedio de todas las fuentes de financiamiento de una empresa. Es la tasa mínima de retorno que una empresa debe generar en sus inversiones.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('13fcc93d-07d6-4c38-bd0c-e6cc60f49ea1'::uuid, 'Warusa-kagen', 'Un término en TQC que se refiere a aspectos que aún no son problemas, pero que aún no están del todo bien. Suelen ser el punto de partida de las actividades de mejora, ya que, si no se atienden, pueden convertirse en problemas graves.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('d7196ad6-855d-42ab-8231-d3db25147019'::uuid, 'Wildcard', 'Carácter que sirve de comodín, por convención se utilizan "?" ​ para cualquier carácter y "*" para cualquier tira de caracteres.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9baad0db-bf94-41c8-9cca-277e4bfcf9f6'::uuid, 'Wizard', 'Asistente para las funciones de Excel, que presenta una ventana amigable donde usted puede definir los parámetros fácilmente.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('6d6c8348-ca27-46de-b42f-19df46c6e775'::uuid, 'WMS', 'Sistema de gestión de almacenes', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('78412d7d-b371-4b92-818d-62b43cbe9bd8'::uuid, 'Workflow', 'Flujo de trabajo automatizado que define la secuencia de tareas y responsables.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('07178582-ebdb-4bc3-b38b-c06f95ee65e2'::uuid, 'Yokoten', 'Yokoten es una palabra japonesa que significa "implementación horizontal" y se refiere a la práctica de aplicar los buenos resultados de KAIZEN™ de un área a otras. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f5a3ad08-8158-4e3f-836c-e43ecec65a27'::uuid, 'Zona', 'División geográfica o territorial usada como criterio de segmentación de audiencia.', 'Zona', NULL, NULL, false, NULL, false, false, NULL, '2026-09-25T13:37:33.000Z'::timestamptz),
  ('d69a3e74-99b4-4b67-9999-1e48de379e54'::uuid, 'Zona de almacenaje', ' Es una división que se realiza dentro del sistema WMS para partir el área total del CEDI en subpartes más pequeñas. Para lograr mejor control sobre la ubicación de la mercadería. Cada artículo se configura para tener una zona de almacenaje principal, y una o varias zonas de extensión en caso de que la zona principal este totalmente llena. ', 'Zona de Almacen', NULL, NULL, false, NULL, false, false, NULL, '2026-09-30T19:30:00.000Z'::timestamptz),
  ('3f65a5e6-1a71-426b-b6b7-b55f6f3752cc'::uuid, 'Zona de trabajo', 'Área del almacén donde un recurso puede ejecutar tareas.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('88e9ffd0-b273-4038-a96e-f194c3b78d8d'::uuid, 'Zona de trabajo de preparación', 'Corresponde a un espacio de trabajo preparación delimita un espacio de trabajo al que se asocian ciertos recursos de preparación. Los recursos que trabajan en estas zonas son: carretillas eléctricas, carretillas manuales, etc.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('27e7a6c8-a609-454b-929d-3cc1e1f88066'::uuid, 'Zonas', 'Área geográfica donde se encuentran ubicados un conjunto de clientes asignados a un determinado Representante de Ventas. Esta zona debe estar localizada en un área que facilite su adecuada y rentable cobertura quedando bien definidos los límites geográficos para facilitar la tarea de valoración y control.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('f29b9826-21fc-481a-9460-7f10c0b88724'::uuid, 'Zonas cola de preparación', 'Permiten fragmentar el trabajo de preparación de una orden de expedición en tantos grupos como zonas colas de preparación existan', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('1b219451-7b80-40d0-9db1-e2414ae55681'::uuid, 'Zonas de operación', 'Áreas designadas y señalizadas para la circulación o operación segura de vehículos y equipos.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('0ea844e0-82c9-4318-b410-2a4029c35ae0'::uuid, 'Zonas de picking', ' Son divisiones del almacén que se realizan en eflow WMS para distribuir el trabajo de los alistadores de mercadería hacia un cliente final. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('9abdbd49-94dc-4585-a027-d00da9d1f391'::uuid, 'Zonas de trabajo recursos', ' Son divisiones del almacén que se realiza en eflow WMS para distribuir el trabajo de los recursos (Montacargas, carretillas hidráulicas, carretillas manuales) en el almacén. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('803d0ce7-88b6-42f4-8e06-ffcc85aaca11'::uuid, 'Árbol de surtido', 'Un sistema de clasificación que organiza los productos en grupos, categorías y subcategorías, con el objetivo de facilitar la toma de decisiones para el resurtido y la inversión eficiente del presupuesto de compra.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('4af62927-ccf6-4300-85df-1c1fc2f9f45a'::uuid, 'Área', 'Dimension que refleja las divisiones principales de la organización.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('5d89ad3f-6494-4554-9d43-a6f34a92fa21'::uuid, 'Área funcional', ' Área estratégica de algún responsable comercial. En el presente, se manejan  Sistemas, Personal, Control, Mercadeo, Logística, Ventas y Compras. ', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('7d5602d0-c33d-4137-93cc-7f001453fabd'::uuid, 'Índice ', 'Sistema de organización documental por departamento, área, proceso y nombre del documento.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('a96dffcb-fa2c-4ee3-a19e-e4ea9afc0023'::uuid, 'Órdenes de expedición', 'Documentos de salida enviados desde el ERP a eflow WMS que muestran el detalle de un pedido para la generación de acciones y finalizan en el despacho.', '', NULL, NULL, false, NULL, false, false, NULL, NULL),
  ('125cd9fb-c7c6-4a4b-806b-3ca5bc9ec218'::uuid, 'Órdenes en tránsito', 'Órdenes de compra que ya han sido registradas en el ERP pero cuya mercancía aún no ha sido recibida y/o facturada. Se usan para proyectar futuros pagos en el flujo de caja.', '', NULL, NULL, false, NULL, false, false, NULL, NULL)
ON CONFLICT DO NOTHING;

