INSERT INTO definicion_fragmentos (termino_id, orden, contexto, texto) VALUES
  ('54dd51b5-de9c-47a7-ac8f-db288aa0d235'::uuid, 0, 'Reporte SIM – Dimensión Compras', 'Dimensión que muestra el código y descripción de los articulos de la compañía.'),
  ('54dd51b5-de9c-47a7-ac8f-db288aa0d235'::uuid, 1, 'Reporte SIM – Filtro Compra', 'Permite seleccionar el código y descripción de uno o varios artículos en específico.'),
  ('978bbf94-9f13-42c2-b58c-ecaba813d23f'::uuid, 0, 'Reporte SIM – Dimensión Compras', 'Refleja la clasificación de los artículos de acuerdo a la nomenclatura BDF.'),
  ('978bbf94-9f13-42c2-b58c-ecaba813d23f'::uuid, 1, 'Reporte SIM – Filtro Compra', 'Permite seleccionar una o mas clasificaciones BDF de articulos.'),
  ('f6dfaec7-a1ed-440e-ae23-9d2fb12f04c2'::uuid, 0, 'Softland', 'Instalaciones físicas donde se almacenan las materias primas, los productos terminados y los suministros relacionados con la empresa. La definición de privilegios por usuario para cada bodega se realiza en el módulo de Administración del Sistema.'),
  ('f6dfaec7-a1ed-440e-ae23-9d2fb12f04c2'::uuid, 1, 'Reporte SIM – Dimensión Ventas', 'Muestra las bodegas que conforman los almacenes de las compañías.'),
  ('63d3eb0a-0cfe-46d0-9755-ae2b044003d4'::uuid, 0, 'Silo Sistemas', 'Unidad mínima de información que compone un registro. En una estructura de datos, corresponde a las columnas y representa un atributo específico (ej. Fecha, Monto, SKU).'),
  ('63d3eb0a-0cfe-46d0-9755-ae2b044003d4'::uuid, 1, 'Silo Sistemas', 'Columna creada a partir de una fórmula para mostrar información derivada de los datos originales.'),
  ('74da4cc1-da25-4776-930a-4f5fe6cb584f'::uuid, 0, 'Silo Control', 'El valor total de las deudas que los clientes tienen con la empresa en una fecha determinada. Su análisis por antigüedad de saldos es fundamental para gestionar el riesgo de incobrabilidad.'),
  ('74da4cc1-da25-4776-930a-4f5fe6cb584f'::uuid, 1, 'Reporte SIM – Indicador Venta', 'Sumatoria del total de las Cuentas por Cobrar, es decir el monto total de dinero que los clientes le deben a la compañía.'),
  ('672bb14a-6d84-48da-bb59-1f4a1f582315'::uuid, 0, 'Reporte SIM – Dimensión Compras', 'Muestra las categorias creadas para segmentar los artículos.'),
  ('672bb14a-6d84-48da-bb59-1f4a1f582315'::uuid, 1, 'Reporte SIM – Dimensión Ventas', 'Una categoría es una clasificación o grupo que se utiliza para agrupar elementos que comparten características o propiedades comunes.'),
  ('672bb14a-6d84-48da-bb59-1f4a1f582315'::uuid, 2, 'Reporte SIM – Filtro Compra', 'Permite seleccionar una o mas categorias especificas de los articulos.'),
  ('672bb14a-6d84-48da-bb59-1f4a1f582315'::uuid, 3, 'Silo Compras', 'Una clasificación dentro de un grupo, donde cada grupo debe contener un rango de 10 a 30 categorías. Los nombres de categorías deben ser descritos en singular, en mayúsculas y sin acento, y no deben llevar conectores. Es la clasificación más general de un producto.'),
  ('54c95665-119b-4a6d-a401-7a7f3d1abc29'::uuid, 0, 'Reporte SIM – Filtro Venta', 'Permite seleccionar una o mas categorias de clientes.'),
  ('54c95665-119b-4a6d-a401-7a7f3d1abc29'::uuid, 1, 'Reporte SIM – Dimensión Ventas', 'Muestra la clasificación que se utiliza para agrupar a los clientes de la compañía.'),
  ('2da438cf-e4ff-42ab-9d96-330753c41554'::uuid, 0, 'Silo Ventas', 'Persona natural o jurídica, debidamente registrada que realiza transacciones sobre los bienes comercializados.'),
  ('2da438cf-e4ff-42ab-9d96-330753c41554'::uuid, 1, 'Reporte SIM – Dimensión Ventas', 'Muestra los clientes que adquieren los productos y servicios de la organización.'),
  ('705656df-3e02-4d5d-b5e3-03ab5c140722'::uuid, 0, 'Silo Personal', 'Persona que trabaja en la empresa y está sujeta a sus normas y políticas.'),
  ('705656df-3e02-4d5d-b5e3-03ab5c140722'::uuid, 1, 'Reporte SIM – Dimensión Personal', 'Refleja a todas las personas que presta sus servicios para la compañía, contribuyendo al logro de sus objetivos y metas.'),
  ('99f2e0b3-21cf-4ecc-bae8-092d688c8631'::uuid, 0, 'Silo Compras / Silo Mercadeo', 'Se refiere a una oferta que agrupa varios productos, a menudo a un precio reducido, para incentivar la compra. Los productos en un combo no necesariamente se utilizan juntos, pero se venden como un paquete promocional.'),
  ('f22bccba-178e-4b14-885d-4446ab180ab0'::uuid, 0, 'Silo Control', 'Resultado de restar el costo de la mercancía vendida (CMV) a las ventas netas. Refleja el ingreso disponible para cubrir gastos operativos y generar utilidad.'),
  ('f22bccba-178e-4b14-885d-4446ab180ab0'::uuid, 1, 'Reporte SIM – Indicador Compra', 'Esta fórmula calcula la ganancia inicial de la compañía. Simplemente, resta el costo directo de lo que vendiste (el costo de venta) de los ingresos totales que generaste (la venta neta).'),
  ('33a985f1-dd16-4c84-af75-bd3a3b0f086c'::uuid, 0, 'Eprac', 'Corresponde al flujo directo de mercancía a través de una instalación, de muelle de recepción al muelle de expedición, eliminando la necesidad de almacenamiento y alisto.'),
  ('33a985f1-dd16-4c84-af75-bd3a3b0f086c'::uuid, 1, 'Silo Logística', 'Transferencia directa de mercancías de un transporte a otro, sin almacenar en el almacén.'),
  ('59a49b15-f234-491f-8349-493ae498b8fc'::uuid, 0, 'Softland', 'Unidad funcional de la empresa, en la cual se agrupan las actividades que son semejantes y están relacionadas lógicamente entre sí. El departamento representa la estructura formal de la organización tal como aparecería en un organigrama.'),
  ('59a49b15-f234-491f-8349-493ae498b8fc'::uuid, 1, 'Reporte SIM – Dimensión Personal', 'Muestra las sub divisiones que existen dentreo de las areas de la compañia.'),
  ('1195ac80-39fd-41c1-8311-170a69b12bea'::uuid, 0, 'Silo Ventas', 'proceso en el que un cliente devuelve un producto a un vendedor o empresa. Esto puede suceder por varias razones, como que el producto esté defectuoso, sea del tamaño o color incorrecto, o simplemente no cumpla con las expectativas del cliente.'),
  ('1195ac80-39fd-41c1-8311-170a69b12bea'::uuid, 1, 'Reporte SIM – Indicador Venta', 'Suma de la venta multiplicando por -1, se aplica para todos los documentos con estado “D”.'),
  ('1cc466a1-9c72-42f0-bc69-16a0385799b6'::uuid, 0, 'Silo Control', 'Métrica que mide el porcentaje de productos devueltos en relación con el total de ventas. Se calcula como (Valor de Devoluciones / Ventas Totales) x 100. Es un indicador de la calidad del producto y la satisfacción del cliente.'),
  ('1cc466a1-9c72-42f0-bc69-16a0385799b6'::uuid, 1, 'Reporte SIM – Indicador Venta', 'El porcentaje de productos vendidos que son devueltos por los clientes.'),
  ('7fcee247-f184-482b-95e2-12052d652da6'::uuid, 0, 'Silo Control', 'Métrica de cadena de suministro que mide el porcentaje de la demanda de un cliente que se satisface con el inventario disponible de forma inmediata.'),
  ('7fcee247-f184-482b-95e2-12052d652da6'::uuid, 1, 'Silo Logística', 'La tasa de cumplimiento o nivel de servicio, es un indicador que mide el porcentaje de pedidos de clientes que se entregan completos y a tiempo.'),
  ('7fcee247-f184-482b-95e2-12052d652da6'::uuid, 2, 'Reporte SIM – Indicador Compra', 'Mercancía recibida entre mercancía solicitada.'),
  ('c3e39344-e626-4774-a756-9c4bd7ecd480'::uuid, 0, 'Silo Control', 'Beneficio generado por las operaciones principales del negocio, antes de deducir intereses e impuestos. Mide la eficiencia y rentabilidad del core business.'),
  ('c3e39344-e626-4774-a756-9c4bd7ecd480'::uuid, 1, 'Reporte SIM – Indicador Control', 'Suma de las ganancias obtenidas de las operaciones principales de la empresa.'),
  ('66f28f69-670c-4ba9-9c68-bc3cd0c4056a'::uuid, 0, 'Silo Control', 'Costos incurridos en las actividades principales del negocio, excluyendo el costo de la mercancía vendida (CMV), intereses e impuestos.'),
  ('66f28f69-670c-4ba9-9c68-bc3cd0c4056a'::uuid, 1, 'Reporte SIM – Indicador Control', 'Suma total de los gastos incurridos en las operaciones cotidianas de la empresa.'),
  ('c65ca2b2-3c9d-49c4-84b8-bba8241e8e1e'::uuid, 0, 'Reporte SIM – Dimensión Compras', 'Muestra la agrupación de marcas asignadas por comprador.'),
  ('c65ca2b2-3c9d-49c4-84b8-bba8241e8e1e'::uuid, 1, 'Reporte SIM – Filtro Compra', 'Permite visualizar la informaciónen en base a la selección de uno o mas Grupos compra.'),
  ('de73a61a-fcc0-481c-a899-30bb66710c76'::uuid, 0, 'Silo Control', 'Costo financiero por el uso de dinero prestado, o el rendimiento generado por prestarlo.'),
  ('5bd88f67-1138-4455-9c8f-78a370219935'::uuid, 0, 'Silo Control', 'Representa el valor de las mercancías disponibles para la venta. La gestión de inventario busca equilibrar la disponibilidad del producto con el costo de mantenerlo.'),
  ('5bd88f67-1138-4455-9c8f-78a370219935'::uuid, 1, 'Silo Logística', 'Registro detallado de las existencias de productos en un almacén, incluyendo cantidades, ubicaciones y estado.'),
  ('5bd88f67-1138-4455-9c8f-78a370219935'::uuid, 2, 'Reporte SIM – Indicador Compra', 'Sumatoria de la Columna Inventario en moneda local o dólar dividido entre el número de meses consultados (Se tomarán en cuenta los inventarios al cierre de mes y el último inventario registrado para el mes actual).'),
  ('63d3b1b1-4d0a-4444-90dc-da82f401f7c8'::uuid, 0, 'Silo Control', 'Es el margen de contribución después de considerar el efecto de los descuentos o bonificaciones (rebates) acordados con clientes o proveedores.'),
  ('63d3b1b1-4d0a-4444-90dc-da82f401f7c8'::uuid, 1, 'Reporte SIM – Indicador Compra', 'Margen de contribución total sobre las ventas netas.'),
  ('e51e4332-4e3a-411b-9fd6-c62ed14d33cc'::uuid, 0, 'Silo Control', 'Valor objetivo a alcanzar, que en un entorno de control y Kaizen, a menudo se define como cero errores u operación bajo condiciones óptimas.'),
  ('e51e4332-4e3a-411b-9fd6-c62ed14d33cc'::uuid, 1, 'Reporte SIM – Indicador Venta', 'Es el monto a alcanzar de la venta neta asignado por vendedor. Sumatoria de la columna Meta en moneda local y dólar. venta del cliente activo de los últimos 6 meses * meta del vendedor.'),
  ('3b5c8976-14c4-47c4-9bf7-0286c9e4a480'::uuid, 0, 'Silo Personal', 'Cambio de puesto o área de un colaborador dentro de la organización, que puede ser horizontal (rotación) o vertical (ascenso o descenso).'),
  ('3b5c8976-14c4-47c4-9bf7-0286c9e4a480'::uuid, 1, 'Reporte SIM – Dimensión Personal', 'Cambio de puesto o área de un colaborador dentro de la organización, que puede ser horizontal (rotación) o vertical (ascenso o descenso), de acuerdo al esquema establecido.'),
  ('51c67093-938d-466d-9304-d7a6e6feb924'::uuid, 0, 'Silo Control', '(Órdenes de Compra por Recibir) Se refiere a los productos que ya han sido ordenados a un proveedor pero que aún no han ingresado físicamente al inventario de la empresa.'),
  ('51c67093-938d-466d-9304-d7a6e6feb924'::uuid, 1, 'Reporte SIM – Indicador Compra', 'Cantidad de OC en tránsito más backorder que no han sido recibidas por el almacén.'),
  ('18ee3b43-b6dc-46ee-a491-070865869011'::uuid, 0, 'Reporte SIM – Dimensión Compras', 'Muestra los países que represntan el origen de la compra de mercancía del proveedor.'),
  ('18ee3b43-b6dc-46ee-a491-070865869011'::uuid, 1, 'Reporte SIM – Filtro Logística', 'Permite filtrar por uno o mas países el origen de la compra de mercancía del proveedor.'),
  ('c61e584b-547e-412b-b8b7-6d16798c6be5'::uuid, 0, 'Reporte SIM – Dimensión Compras', 'Muestra la clasificacion de los artículos del surtido regular segun la categoría de colores: “Verde”, “Amarillo”, “Naranja” y “Rojo”. Estas categorías reflejan el comportamiento de los artículos en los últimos doce meses, basándose en tres indicadores específicos: contribución, clientes activados y rotación de inventario.'),
  ('c61e584b-547e-412b-b8b7-6d16798c6be5'::uuid, 1, 'Reporte SIM – Dimensión Ventas', 'Es una clasificación ordenada de elementos (como personas, productos o empresas) basada en un criterio o métrica específica. Es una herramienta para comparar y evaluar el rendimiento o la importancia de algo dentro de un grupo.'),
  ('d52be40b-6939-41d4-a93f-c52027dcfc9f'::uuid, 0, 'Silo Control', 'Descuento o bonificación que un proveedor otorga retroactivamente por alcanzar un volumen de compra determinado durante un período.'),
  ('d52be40b-6939-41d4-a93f-c52027dcfc9f'::uuid, 1, 'Reporte SIM – Indicador Control', 'Suma total de los descuentos recibidos por las comercializadoras.'),
  ('35fb9800-845b-4c24-8310-0b9411fb5f3a'::uuid, 0, 'Eprac', 'Proceso de recibo de artículos en el CEDI, ya sea por primera vez o reintegrados por una razón comercial.'),
  ('35fb9800-845b-4c24-8310-0b9411fb5f3a'::uuid, 1, 'Silo Logística', 'Proceso de ingreso de mercancías al CEDI, incluye descarga, revisión documental y registro en el WMS.'),
  ('b84da35a-cb32-4872-bfa4-42f9ec4a2c10'::uuid, 0, 'Silo Ventas / Reporte SIM – Dimensión Ventas', 'Porción del país que agrupa un conjunto de coordinaciones geográficamente cercanas que componen el territorio de ventas.'),
  ('b84da35a-cb32-4872-bfa4-42f9ec4a2c10'::uuid, 1, 'Reporte SIM – Filtro Venta', 'Ubicación geográfica del cliente.'),
  ('33fe7281-7800-4600-8e8b-bffbd7d2dbbb'::uuid, 0, 'Reporte SIM – Indicador Compra', 'Sumatoria de la cantidad de renglones facturados.'),
  ('33fe7281-7800-4600-8e8b-bffbd7d2dbbb'::uuid, 1, 'Reporte SIM – Indicador Venta', 'Esta fórmula representa el número total de artículos o líneas de detalle que se han facturado en un período de tiempo específico.'),
  ('3205d947-4b83-4783-85df-b241dff36fca'::uuid, 0, 'Reporte SIM – Indicador Compra', 'Sumatoria de la cantidad de renglones pedidos.'),
  ('3205d947-4b83-4783-85df-b241dff36fca'::uuid, 1, 'Reporte SIM – Indicador Venta', 'Esta fórmula calcula el número total de líneas de detalle en todos los pedidos que se han recibido en un período de tiempo determinado.'),
  ('a38a51f1-05a2-49ae-9b5e-1c237025bdc3'::uuid, 0, 'Silo Control', 'Métrica que mide la eficiencia con la que se gestiona un activo, como el inventario. La rotación de inventario se calcula como.'),
  ('a38a51f1-05a2-49ae-9b5e-1c237025bdc3'::uuid, 1, 'Reporte SIM – Indicador Compra', 'Rotación anual de inventario. Cantidad de veces que la compañía vende y reemplaza el inventario en el año.'),
  ('79a29291-7ef4-4c12-86fe-531df77276bf'::uuid, 0, 'Silo Ventas', 'Códigos de productos que están actualmente disponibles para la venta en el inventario.'),
  ('79a29291-7ef4-4c12-86fe-531df77276bf'::uuid, 1, 'Reporte SIM – Indicador Venta', 'SKU con ventas mayores que cero.'),
  ('5ebe4eaf-9346-4ed8-8604-3aa57aec8c58'::uuid, 0, 'Silo Logística', 'Variante simétrica del MAPE para reducir distorsiones.'),
  ('fa757d8e-dd8a-4f61-b6ab-9cb2cbbd13f1'::uuid, 0, 'Silo Logística', 'Plataforma de la cadena de suministro diseñada para optimizar los procesos S & OP actuales.'),
  ('4eddd612-e921-49aa-b4ce-c1540976cc8d'::uuid, 0, 'Reporte SIM – Dimensión Compras', 'Una división más específica dentro de una categoría.'),
  ('4eddd612-e921-49aa-b4ce-c1540976cc8d'::uuid, 1, 'Reporte SIM – Filtro Compra', 'Permite filtrar por una o mas divisiones específicas dentro de una categoría.'),
  ('7b4711b1-75f6-43d9-8183-9aec39fd2dee'::uuid, 0, 'Silo Personal', 'Proceso planificado de identificación, evaluación y desarrollo de talento interno para asegurar la cobertura futura de posiciones críticas o clave dentro de la organización.'),
  ('7b4711b1-75f6-43d9-8183-9aec39fd2dee'::uuid, 1, 'Reporte SIM – Indicador Personal', 'Es un proceso estratégico mediante el cual una organización identifica y prepara a colaboradores clave con el potencial (N) y el desempeño (M/P) necesario para ocupar posiciones críticas en el futuro, asegurando así la continuidad del liderazgo y la operación del negocio.'),
  ('5bdaa8dd-d10a-446f-b999-7b1975bf19e1'::uuid, 0, 'Silo Compras', 'Se refiere a cómo se debe preparar un pedido antes de su envío: pieza, inner, caja, tarima, kg, rollo.'),
  ('5bdaa8dd-d10a-446f-b999-7b1975bf19e1'::uuid, 1, 'Silo Logística', 'Define desde cuál nivel de empaque se realiza el picking (preparación de pedidos) en el almacén para despacho al cliente. Los valores aplicables son: unidad, inner, caja, tarima.'),
  ('2351ce25-b4aa-43a6-9da7-dc63a17d5588'::uuid, 0, 'Silo Procesos', 'Capacidad de seguir el historial, aplicación y cumplimiento de una norma o proceso.'),
  ('2351ce25-b4aa-43a6-9da7-dc63a17d5588'::uuid, 1, 'Silo Logística', 'Registro digital completo de cada pedido desde recepción hasta entrega final.')
ON CONFLICT DO NOTHING;

INSERT INTO termino_etiquetas (termino_id, etiqueta_id, orden)
SELECT v.termino_id::uuid, e.id, v.orden
